insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('bc9aa789-9719-4d3b-bdb6-8e44324d657d', 'default', 'b0000000-0000-0000-0000-000000000023', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu buồng tim, van tim và vòng tuần hoàn lớn nhỏ","audio_url":null,"youtube_id":"rGO4cC09y98","description":"• **Điểm cốt lõi:** Thất trái tim có thành cơ dày gấp 3 lần thất phải để tạo áp lực tống máu đi khắp 100,000km mạch máu.\n• **Ứng dụng thực hành:** Tăng huyết áp mạn tính buộc thất trái phì đại suy tim.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/rGO4cC09y98/hqdefault.jpg"},{"title":"02. Phản xạ thụ thể áp lực điều hòa huyết áp tức thời","audio_url":null,"youtube_id":"0BshHKU0iuU","description":"• **Điểm cốt lõi:** Hồng cầu sống 120 ngày và chứa 270 triệu phân tử Hemoglobin.\n• **Ứng dụng thực hành:** Mỗi phân tử mang được 4 phân tử oxy ($O_2$) cung cấp năng lượng cho từng tế bào thở.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/0BshHKU0iuU/hqdefault.jpg"},{"title":"03. Cấu tạo hồng cầu và cơ chế vận chuyển oxy, CO2","audio_url":null,"youtube_id":"B4-4WeeT8rk","description":"• **Điểm cốt lõi:** Cơ bắp chân hoạt động như \"trái tim thứ hai\" ép các tĩnh mạch sâu tống máu ngược về tim.\n• **Ứng dụng thực hành:** Đi bộ thường xuyên là phương thuốc số 1 chống suy giãn tĩnh mạch chân.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/B4-4WeeT8rk/hqdefault.jpg"},{"title":"04. Suy giãn tĩnh mạch chân: Nguyên nhân và cách phòng ngừa","audio_url":null,"youtube_id":"BRbElUTIqdU","description":"• **Điểm cốt lõi:** Thụ thể áp lực xoang cảnh giúp ổn định huyết áp tức thời khi đứng dậy.\n• **Ứng dụng thực hành:** Suy yếu phản xạ này gây tụt huyết áp tư thế khiến mắt tối sầm và choáng ngã ở người lớn tuổi.","duration_text":"4:33","thumbnail_url":"https://i.ytimg.com/vi/BRbElUTIqdU/hqdefault.jpg"},{"title":"05. Cơ chế điều hòa huyết áp và các nhóm can thiệp y khoa","audio_url":null,"youtube_id":"6NgEKmN47pE","description":"• **Định nghĩa & Bản chất:** Chất Nitric Oxide (NO) do lớp nội mạc mạch máu tiết ra.\n• **Ý nghĩa chuyên môn:** Chìa khóa làm giãn nở mạch máu tự nhiên, giữ cho huyết áp ổn định và ngăn ngừa cục máu đông.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/6NgEKmN47pE/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('bf4dbe70-3e60-4254-aa4e-2961592886cb', 'default', 'b0000000-0000-0000-0003-000000000001', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu não người: 3 phần chính và 4 thùy đại não 3D","audio_url":null,"youtube_id":"PWkxyQKrB9U","description":"• **Trọng tâm cơ chế:** Não bộ chia làm 4 thùy chuyên biệt.\n• **Chi tiết sinh học:** Thùy trán kiểm soát cảm xúc và tư duy logic, thùy chẩm xử lý thị giác, thùy thái dương lưu giữ ký ức và thùy đỉnh định vị không gian.","duration_text":"3:49","thumbnail_url":"https://i.ytimg.com/vi/PWkxyQKrB9U/hqdefault.jpg"},{"title":"02. Tổng quan giải phẫu và chức năng hệ tuần hoàn tim mạch","audio_url":null,"youtube_id":"rGO4cC09y98","description":"• **Trọng tâm cơ chế:** Hệ tuần hoàn và hệ hô hấp là cặp đôi sinh học sinh tử.\n• **Chi tiết sinh học:** Tim bơm máu đến phế nang phổi để nạp đầy oxy trước khi phân phối nuôi dưỡng từng tế bào sống.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/rGO4cC09y98/hqdefault.jpg"},{"title":"03. Giải phẫu và chức năng sinh lý hệ hô hấp","audio_url":null,"youtube_id":"Z0rKB1Q2nUE","description":"• **Điểm cốt lõi:** Hệ bạch huyết không có máy bơm như tim.\n• **Ứng dụng thực hành:** Dịch bạch huyết chỉ lưu thông nhờ sự co bóp của cơ bắp khi vận động và nhịp thở sâu của cơ hoành.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Z0rKB1Q2nUE/hqdefault.jpg"},{"title":"04. Tổng quan hệ bạch huyết và vai trò dẫn lưu miễn dịch","audio_url":null,"youtube_id":"1xZ-Xgq31y8","description":"• **Điểm cốt lõi:** 11 hệ cơ quan trong cơ thể kết nối chặt chẽ như một khối thống nhất.\n• **Ứng dụng thực hành:** Chăm sóc sức khỏe toàn diện đòi hỏi cân bằng cả giấc ngủ, dinh dưỡng, vận động và tinh thần.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/1xZ-Xgq31y8/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
