values ('facf92ec-cf32-415f-804d-6c32fb044a74', 'default', 'b0000000-0000-0000-0004-000000000002', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ thể hấp thu thức ăn như thế nào qua nhung mao ruột non","audio_url":null,"youtube_id":"j1YUy47HXEw","description":"• **Điểm cốt lõi:** Diện tích ruột non tương đương một sân tennis nhờ hàng triệu nhung mao.\n• **Ứng dụng thực hành:** Bất kỳ tổn thương viêm nhiễm nào làm cùn nhung mao cũng gây hội chứng kém hấp thu và sụt cân.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/j1YUy47HXEw/hqdefault.jpg"},{"title":"02. Mô phỏng 3D quá trình tiêu hóa và hấp thu dinh dưỡng","audio_url":null,"youtube_id":"UHBMu20GXF4","description":"• **Điểm cốt lõi:** Hấp thu đường và nước tại ruột non bắt buộc phải có ion Natri đi kèm (kênh SGLT-1).\n• **Ứng dụng thực hành:** Đó là lý do khi tiêu chảy cần uống Oresol có đủ cả muối và đường để bù nước cấp tốc.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/UHBMu20GXF4/hqdefault.jpg"},{"title":"03. Các giai đoạn phân cắt thức ăn và vận chuyển dưỡng chất","audio_url":null,"youtube_id":"wUhEiCvjSCI","description":"• **Điểm cốt lõi:** Chất béo sau khi hấp thu không đi thẳng vào máu mà đi vào hệ bạch huyết dưới dạng Chylomicron trước khi đổ vào tĩnh mạch dưới đòn để vào tim..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/wUhEiCvjSCI/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Hội chứng rò rỉ ruột (Leaky Gut) và viêm niêm mạc","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Định nghĩa & Bản chất:** Hội chứng rò rỉ ruột (Leaky Gut) cho phép độc tố vi khuẩn LPS lọt vào tuần hoàn máu,.\n• **Ý nghĩa chuyên môn:** Nguồn cơn châm ngòi cho các bệnh viêm mạn tính và viêm khớp tự miễn.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('e6f23dfa-a3f5-438f-91da-6b9322f08b4a', 'default', 'b0000000-0000-0000-0000-000000000022', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Phân loại và chức năng năm loại xương trong cơ thể người","audio_url":null,"youtube_id":"mDaFENFro-o","description":"• **Điểm cốt lõi:** 206 chiếc xương trong cơ thể liên tục thay mới.\n• **Ứng dụng thực hành:** Sau mỗi 10 năm bạn sẽ có một bộ xương hoàn toàn mới nhờ hoạt động nhịp nhàng của tạo cốt bào và hủy cốt bào.","duration_text":"3:45","thumbnail_url":"https://i.ytimg.com/vi/mDaFENFro-o/hqdefault.jpg"},{"title":"02. Phân loại và đặc điểm các loại khớp hoạt dịch","audio_url":null,"youtube_id":"cMmZ6VX-5QI","description":"• **Điểm cốt lõi:** Sụn khớp hoạt dịch và sụn chêm khớp gối hoàn toàn không có mạch máu.\n• **Ứng dụng thực hành:** Chúng chỉ nhận dinh dưỡng khi khớp cử động nén nhả để dịch khớp thẩm thấu vào sụn.","duration_text":"1:32","thumbnail_url":"https://i.ytimg.com/vi/cMmZ6VX-5QI/hqdefault.jpg"},{"title":"03. Cơ chế co cơ xương từ kích thích thần kinh đến trượt sợi actin-myosin","audio_url":null,"youtube_id":"yfTB9KL1heo","description":"• **Điểm cốt lõi:** Quá trình co cơ bắp tiêu tốn năng lượng ATP và ion Canxi nội bào.\n• **Ứng dụng thực hành:** Thiếu canxi hoặc magie sẽ khiến các sợi cơ actin-myosin không thể nhả giãn, gây chuột rút đau đớn.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/yfTB9KL1heo/hqdefault.jpg"},{"title":"04. Giải phẫu khớp gối và chức năng vận động chịu lực","audio_url":null,"youtube_id":"-BVV1UA_0L4","description":"• **Điểm cốt lõi:** Khớp gối chịu tải trọng gấp 3-4 lần trọng lượng cơ thể khi đi bộ và gấp 7 lần khi leo cầu thang.\n• **Ứng dụng thực hành:** Kiểm soát cân nặng là biện pháp hàng đầu bảo vệ khớp gối khỏi thoái hóa.","duration_text":"9:27","thumbnail_url":"https://i.ytimg.com/vi/-BVV1UA_0L4/hqdefault.jpg"},{"title":"05. Loãng xương: Cơ chế hủy cốt bào, yếu tố nguy cơ và phòng ngừa","audio_url":null,"youtube_id":"rEvcYRR8LTI","description":"• **Định nghĩa & Bản chất:** Tập luyện kháng lực (tạ, bodyweight) tạo áp lực cơ học kích thích tạo cốt bào tăng mật độ xương,.\n• **Ý nghĩa chuyên môn:** Phương thuốc phòng chống loãng xương hiệu quả nhất.","duration_text":"4:31","thumbnail_url":"https://i.ytimg.com/vi/rEvcYRR8LTI/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('48ad39d4-7595-416c-9637-d0fce82a1a60', 'default', 'b0000000-0000-0000-0005-000000000001', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Trao đổi mao mạch, áp lực keo và cơ chế hình thành phù nề","youtube_id":"xceWKaMOHi0","description":"• **Điểm cốt lõi:** Áp lực keo do Albumin quyết định khả năng giữ nước trong lòng mạch.\n• **Ứng dụng thực hành:** Khi gan suy giảm tổng hợp Albumin hoặc thận rò rỉ đạm, nước tràn ra khoang gian bào gây phù chân và báng bụng.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/xceWKaMOHi0/hqdefault.jpg"},{"title":"02. Dịch não tủy (CSF) và vai trò dung môi đệm thần kinh","youtube_id":"gPdMDLKlkIQ","description":"• **Điểm cốt lõi:** Dịch não tủy thay mới 4–5 lần mỗi ngày.\n• **Ứng dụng thực hành:** Thiếu nước mạn tính làm giảm tốc độ thanh thải độc chất của hệ Glymphatic não trong khi ngủ, dẫn đến đau đầu âm ỉ và sương mù não.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/gPdMDLKlkIQ/hqdefault.jpg"},{"title":"03. Phần 1: Nước sạch tạp chất và sạch hợp chất hóa học","youtube_id":"GKDbKjU1Q1w","description":"• **Trọng tâm cơ chế:** Nước sạch tinh khiết là điều kiện tiên quyết.\n• **Chi tiết sinh học:** Loại bỏ hoàn toàn vi khuẩn, kim loại nặng và dư lượng hóa chất công nghiệp trước khi đánh giá các chỉ số sinh hóa nâng cao.","duration_text":"15 phút","thumbnail_url":"https://i.ytimg.com/vi/GKDbKjU1Q1w/hqdefault.jpg"},{"title":"04. Phần 2: Nước tốt – Chỉ số TDS, pH, Hydrogen và cụm phân tử nhỏ","youtube_id":"m6iOXWjP3sU","description":"• **Trọng tâm cơ chế:** Nước tốt cho sức khỏe cần hội tụ.\n• **Chi tiết sinh học:** Độ sạch tuyệt đối, giàu Hydrogen hoạt tính chống oxy hóa tế bào, ORP âm sâu và phân tử nước cụm nhỏ giúp thẩm thấu nhanh qua kênh Aquaporin.","duration_text":"16 phút","thumbnail_url":"https://i.ytimg.com/vi/m6iOXWjP3sU/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('2b035e37-d287-4d8f-8fa3-31e54be88037', 'default', 'b0000000-0000-0000-0008-000000000006', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Miễn dịch niêm mạc ruột: Nơi tập trung 70% hệ miễn dịch cơ thể","audio_url":null,"youtube_id":"nf0_cUb9XU8","description":"• **Điểm cốt lõi:** Đường ruột là trường đào tạo 70% tế bào miễn dịch.\n• **Ứng dụng thực hành:** Chăm sóc hệ vi sinh đường ruột khỏe mạnh là bước đi cốt lõi nhất để nâng cao sức đề kháng toàn thân.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/nf0_cUb9XU8/hqdefault.jpg"},{"title":"02. Bệnh tự miễn (Vẩy nến): Cơ chế bệnh học khi miễn dịch tấn công cơ thể","audio_url":null,"youtube_id":"pttHZkFVEpk","description":"• **Điểm cốt lõi:** Bệnh tự miễn xảy ra khi hệ miễn dịch bị mất phương hướng nhận nhầm tế bào cơ thể là kẻ thù.\n• **Ứng dụng thực hành:** Chữa lành niêm mạc ruột và giảm viêm là nền tảng phục hồi.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/pttHZkFVEpk/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Bộ ba Vitamin C, Vitamin D3 và Kẽm tăng sức đề kháng","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Bộ ba Vitamin C, Vitamin D3 và Kẽm hiệp đồng tác dụng.\n• **Tác dụng sinh học:** Các tế bào miễn dịch nhận diện và vô hiệu hóa virus đường hô hấp ngay từ cửa ngõ.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Giấc ngủ và quản lý Stress kích hoạt tế bào miễn dịch","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Giấc ngủ sâu từ 22h đêm là lúc hệ miễn dịch được sạc pin và tái sinh đội quân bạch cầu.\n• **Ứng dụng thực hành:** Thức khuya triền miên làm sức đề kháng sụt giảm một nửa.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('0f037469-9b30-42b1-b327-d788d3f69e79', 'default', 'b0000000-0000-0000-0008-000000000003', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và chức năng lọc máu, bảo vệ miễn dịch của lách 3D","audio_url":null,"youtube_id":"a4Qm2lm50eU","description":"• **Điểm cốt lõi:** Tế bào T-CD4+ là tổng công trình sư điều phối toàn bộ hệ thống miễn dịch.\n• **Ứng dụng thực hành:** Virus HIV tấn công chính tế bào này làm hệ miễn dịch sụp đổ hoàn toàn.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/a4Qm2lm50eU/hqdefault.jpg"},{"title":"02. Tuyến ức và lách: Cơ quan huấn luyện tế bào T trưởng thành","audio_url":null,"youtube_id":"2KZ0kgCHA0w","description":"• **Điểm cốt lõi:** Tuyến ức là trường học huấn luyện tế bào T nhưng teo nhỏ dần sau tuổi dậy thì.\n• **Ứng dụng thực hành:** Duy trì lối sống lành mạnh giúp các tế bào T trưởng thành hoạt động bền bỉ.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/2KZ0kgCHA0w/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Tế bào lympho T (T hỗ trợ, T gây độc) và tế bào B","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Lách lọc sạch máu và bắt giữ vi khuẩn có vỏ bọc.\n• **Ứng dụng thực hành:** Người bị cắt lách sau chấn thương có nguy cơ nhiễm trùng máu cực cao, bắt buộc phải tiêm phòng phế cầu.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Cơ chế hình thành kháng thể và trí nhớ miễn dịch","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Trọng tâm cơ chế:** Trí nhớ miễn dịch là nền tảng của vaccine.\n• **Chi tiết sinh học:** Đưa mầm bệnh bất hoạt vào để tế bào B và T ghi nhớ, giúp cơ thể tiêu diệt virus thật chỉ trong vài giờ khi tiếp xúc.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('151043f0-91d7-4c27-964c-d32ef04a3597', 'default', 'b0000000-0000-0000-0008-000000000002', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Quá trình tạo máu tại tủy xương và biệt hóa tế bào gốc miễn dịch","audio_url":null,"youtube_id":"xuPbu34pkOE","description":"• **Điểm cốt lõi:** Bạch cầu trung tính là cảm tử quân lao vào ổ nhiễm trùng nuốt vi khuẩn.\n• **Ứng dụng thực hành:** Mủ tại vết thương thực chất là xác của hàng triệu bạch cầu trung tính đã hy sinh.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/xuPbu34pkOE/hqdefault.jpg"},{"title":"02. Histamine và cơ chế dị ứng, sốc phản vệ của hệ miễn dịch","audio_url":null,"youtube_id":"M_CxZGhL5rc","description":"• **Điểm cốt lõi:** Đại thực bào vừa là cỗ xe dọn rác khổng lồ vừa là sứ giả mang mảnh vỡ mầm bệnh đến hạch bạch huyết.\n• **Mục tiêu thực hành:** Kích hoạt đội quân miễn dịch thích ứng tinh nhuệ.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/M_CxZGhL5rc/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Bạch cầu trung tính và đại thực bào săn lùng vi khuẩn","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Tế bào NK (Natural Killer) liên tục tuần tra để tiêu diệt các mầm mống ung thư mới chớm nở.\n• **Ứng dụng thực hành:** Thiếu ngủ và stress mạn tính làm suy giảm tới 70% hoạt tính của tế bào NK.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Tế bào sát thủ tự nhiên (NK Cell) tiêu diệt tế bào lạ","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Sốc phản vệ là phản ứng dị ứng tối khẩn cấp do Histamine làm sập huyết áp và co thắt đường thở.\n• **Ứng dụng thực hành:** Adrenaline tiêm bắp là liều thuốc duy nhất cứu sống tính mạng.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('182373c9-3fcf-4d7a-a430-248ed64245c1', 'default', 'b0000000-0000-0000-0000-000000000051', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Hệ nội tiết và cơ chế truyền tín hiệu của hormone 3D","audio_url":null,"youtube_id":"WwIpjj9lJpY","description":"• **Đặc điểm sinh lý:** Hormone là các sứ giả sinh học lưu hành trong máu với nồng độ cực nhỏ (nanogram).\n• **Lưu ý quan trọng:** Có quyền năng chi phối toàn bộ năng lượng, tâm trạng và sinh sản.","duration_text":"4:14","thumbnail_url":"https://i.ytimg.com/vi/WwIpjj9lJpY/hqdefault.jpg"},{"title":"02. Vùng dưới đồi: Trung tâm điều khiển nội tiết và thần kinh tự chủ","audio_url":null,"youtube_id":"h0bm9We5D4c","description":"• **Điểm cốt lõi:** Cơ chế điều hòa ngược âm tính (Feedback âm) là van an toàn tự động bảo vệ cơ thể.\n• **Ứng dụng thực hành:** Lạm dụng thuốc hormone ngoại sinh (như corticoid) sẽ làm teo tuyến nội tiết tự nhiên.","duration_text":"5:49","thumbnail_url":"https://i.ytimg.com/vi/h0bm9We5D4c/hqdefault.jpg"},{"title":"03. Sinh lý tuyến tùng và điều hòa nhịp sinh học ngày đêm","audio_url":null,"youtube_id":"wBAtpVd__Eo","description":"• **Định nghĩa & Bản chất:** Trục vùng dưới đồi - tuyến yên.\n• **Ý nghĩa chuyên môn:** Cầu nối biến những căng thẳng tâm lý thành các rối loạn nội tiết thực thể tại buồng trứng, tuyến giáp và thượng thận.","duration_text":"4:43","thumbnail_url":"https://i.ytimg.com/vi/wBAtpVd__Eo/hqdefault.jpg"},{"title":"04. Tổng quan tuyến giáp và tuyến cận giáp trong cơ thể","audio_url":null,"youtube_id":"5EIlNIzOWks","description":"• **Đặc điểm sinh lý:** Tuyến cận giáp nằm ép sau tuyến giáp tuy nhỏ bằng hạt gạo.\n• **Lưu ý quan trọng:** Đóng vai trò sinh tử tiết hormone PTH điều hòa nồng độ canxi huyết tương liên tục.","duration_text":"1:16","thumbnail_url":"https://i.ytimg.com/vi/5EIlNIzOWks/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('b5ccc22e-43d8-4ca8-bf42-458964081b01', 'default', 'b0000000-0000-0000-0005-000000000003', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Chuyển hóa magie, dấu hiệu chuột rút và hạ magie máu","youtube_id":"Q4TWnCF8vQY","description":"• **Định nghĩa & Bản chất:** Chuột rút bắp chân và co giật cơ vô cớ thường.\n• **Ý nghĩa chuyên môn:** Tín hiệu sớm của thiếu hụt Magie và mất nước tế bào, không thể chỉ bù đắp bằng nước lọc trơ khoáng thông thường.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/Q4TWnCF8vQY/hqdefault.jpg"},{"title":"02. TDS và điện phân bóng đèn: Nhận thức các chất dẫn truyền hòa tan trong nước","youtube_id":"2CqOkuLX34s","description":"• **Trọng tâm cơ chế:** Thử nghiệm điện phân làm lộ rõ các ion kim loại và tạp chất hòa tan trong nước.\n• **Chi tiết sinh học:** Nước chứa nhiều tạp chất công nghiệp sẽ kết tủa màu nâu đỏ, váng dầu và mùi nồng.","duration_text":"28:17","thumbnail_url":"https://i.ytimg.com/vi/2CqOkuLX34s/hqdefault.jpg"},{"title":"03. Kỹ thuật đo và kiểm chuẩn chỉ số TDS để nhận biết độ tinh khiết","youtube_id":"ihDRqxnYLSE","description":"• **Định nghĩa & Bản chất:** Bút đo TDS chỉ phản ánh tổng hàm lượng chất rắn dẫn điện hòa tan, không phân biệt được đâu.\n• **Ý nghĩa chuyên môn:** Ion khoáng sinh học có lợi hay kim loại nặng độc hại.","duration_text":"03:28","thumbnail_url":"https://i.ytimg.com/vi/ihDRqxnYLSE/hqdefault.jpg"},{"title":"04. Kiểm tra độ suy giảm chất lượng nước và nồng độ Hydrogen","youtube_id":"DOXo1RQxtto","description":"• **Điểm cốt lõi:** Nồng độ Hydro hòa tan (ppb) và độ pH kiềm tính suy giảm rất nhanh sau khi rót khỏi máy.\n• **Ứng dụng thực hành:** Nước giàu Hydrogen cần được uống tươi trực tiếp trong vòng 15–30 phút.","duration_text":"03:25","thumbnail_url":"https://i.ytimg.com/vi/DOXo1RQxtto/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('15728c15-8f95-4d3e-9bf3-849ef138ee88', 'default', 'b0000000-0000-0000-0007-000000000004', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Viêm tụy cấp và mạn tính: Cơ chế, triệu chứng và cấp cứu y khoa","audio_url":null,"youtube_id":"xhZxOzTOLCs","description":"• **Điểm cốt lõi:** Dịch tụy giàu Bicarbonate đóng vai trò dập tắt ngọn lửa axit từ dạ dày.\n• **Ứng dụng thực hành:** Nếu tụy không tiết đủ kiềm, axit dạ dày sẽ làm bỏng loét niêm mạc tá tràng và ức chế enzyme tiêu hóa.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/xhZxOzTOLCs/hqdefault.jpg"},{"title":"02. Phẫu thuật cắt tụy và tự ghép đảo tụy giảm đau viêm","audio_url":null,"youtube_id":"ancoWGshUHE","description":"• **Điểm cốt lõi:** Viêm tụy cấp thường bùng phát sau một bữa ăn thịnh soạn nhiều rượu bia và mỡ động vật.\n• **Ứng dụng thực hành:** Triệu chứng đau bụng thượng vị dữ dội lan ra sau lưng kèm nôn ói liên tục.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/ancoWGshUHE/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Dịch tụy ngoại tiết: Bicarbonate trung hòa axit dạ dày","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Định nghĩa & Bản chất:** Sỏi mật rơi xuống làm tắc nghẽn ống mật tụy chung (bóng Vater).\n• **Ý nghĩa chuyên môn:** Thủ phạm hàng đầu gây viêm tụy cấp tắc nghẽn, cần phải can thiệp lấy sỏi nội soi ERCP cấp cứu.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Bảo vệ tuyến tụy tránh làm việc quá tải do rượu bia và mỡ xấu","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Suy tụy ngoại tiết mạn tính gây hội chứng đi ngoài phân mỡ (phân nổi bồng bềnh.\n• **Ứng dụng thực hành:** Váng dầu và mùi nồng nặc) do mỡ hoàn toàn không được enzyme Lipase phân giải.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('a4248c7f-1dcb-42ca-a9c2-204b0e2cdcdb', 'default', 'b0000000-0000-0000-0006-000000000001', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu tuyến giáp và các rối loạn chức năng thường gặp","audio_url":null,"youtube_id":"rGDl1rKvGE0","description":"• **Điểm cốt lõi:** Tuyến giáp quyết định tốc độ chuyển hóa của mọi tế bào.\n• **Ứng dụng thực hành:** Người bị suy giáp dù ăn rất ít vẫn tăng cân và luôn trong trạng thái kiệt sức, ớn lạnh.","duration_text":"3:41","thumbnail_url":"https://i.ytimg.com/vi/rGDl1rKvGE0/hqdefault.jpg"},{"title":"02. Bệnh tuyến giáp (Suy giáp, cường giáp): Nguyên nhân gốc rễ & Giải pháp","audio_url":null,"youtube_id":"iQGZq9axY1k","description":"• **Điểm cốt lõi:** Gan là nơi chuyển đổi 60% lượng hormone T4 thụ động thành T3 hoạt tính sinh học.\n• **Ứng dụng thực hành:** Lá gan nhiễm mỡ hoặc suy yếu sẽ làm suy giảm chức năng tuyến giáp gián tiếp.","duration_text":"10:52","thumbnail_url":"https://i.ytimg.com/vi/iQGZq9axY1k/hqdefault.jpg"},{"title":"03. Cường giáp do bệnh Basedow / Graves và cơ chế tự miễn","audio_url":null,"youtube_id":"_TSBt0Y7xM8","description":"• **Điểm cốt lõi:** Viêm tuyến giáp Hashimoto là bệnh tự miễn do hệ miễn dịch tấn công nhầm tuyến giáp.\n• **Ứng dụng thực hành:** Cần kiểm soát tình trạng rò rỉ ruột và bổ sung đủ Selen, Kẽm để giảm kháng thể.","duration_text":"3:34","thumbnail_url":"https://i.ytimg.com/vi/_TSBt0Y7xM8/hqdefault.jpg"},{"title":"04. Cường tuyến cận giáp: Nguyên nhân, biến chứng loãng xương & Điều trị","audio_url":null,"youtube_id":"_Cp7u8jb4ww","description":"• **Điểm cốt lõi:** Cường cận giáp kéo canxi ồ ạt ra khỏi khung xương gây giòn xương và lắng đọng tạo sỏi thận.\n• **Ứng dụng thực hành:** Cần xét nghiệm canxi ion hóa và hormone PTH khi bị sỏi thận tái phát.","duration_text":"4:38","thumbnail_url":"https://i.ytimg.com/vi/_Cp7u8jb4ww/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('a15c9316-6af9-41d1-8e01-4618f1a684d7', 'default', 'b0000000-0000-0000-0005-000000000004', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cách sử dụng nước tinh khiết và nước hydrogen ion kiềm khoa học","youtube_id":"-sy4yw1d0Sw","description":"• **Điểm cốt lõi:** Nước tinh khiết chuẩn RO dùng để nấu ăn, pha chế.\n• **Ứng dụng thực hành:** Nước ion kiềm giàu Hydro tự nhiên tối ưu để uống trực tiếp hỗ trợ giải phóng axit lactic và giảm stress oxy hóa.","duration_text":"09:53","thumbnail_url":"https://i.ytimg.com/vi/-sy4yw1d0Sw/hqdefault.jpg"},{"title":"02. Khi nào cơ thể nên dùng nước kiềm và cách dùng chuẩn sinh học","youtube_id":"a7t333vDGoI","description":"• **Trọng tâm cơ chế:** Uống nước kiềm chuẩn sinh học.\n• **Chi tiết sinh học:** Không uống sát hoặc ngay sau bữa ăn chính vì độ kiềm làm loãng và trung hòa axit chlohydric (HCl) của dạ dày gây đầy bụng khó tiêu.","duration_text":"06:19","thumbnail_url":"https://i.ytimg.com/vi/a7t333vDGoI/hqdefault.jpg"},{"title":"03. Chỉ số ORP, Hydrogen hoạt tính và khả năng hấp thu của nước","youtube_id":"wZAzgbjTAIE","description":"• **Điểm cốt lõi:** ORP âm sâu (-300mV đến -600mV) và Hydrogen hòa tan cao là chỉ số vàng đo lường năng lực khử gốc tự do.\n• **Ứng dụng thực hành:** Nước có ORP dương là nước có tính oxy hóa tế bào.","duration_text":"13:06","thumbnail_url":"https://i.ytimg.com/vi/wZAzgbjTAIE/hqdefault.jpg"},{"title":"04. Kinh nghiệm thực nghiệm và lưu ý sử dụng nước hydrogen ion kiềm","youtube_id":"y10vgTVy9bI","description":"• **Điểm cốt lõi:** Bảo quản nước giàu Hydro trong bình thép không gỉ hoặc thủy tinh tối màu đậy kín.\n• **Ứng dụng thực hành:** Các phân tử H2 siêu nhỏ dễ dàng khuếch tán bay hơi qua bình nhựa mỏng.","duration_text":"11:23","thumbnail_url":"https://i.ytimg.com/vi/y10vgTVy9bI/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('c7fccca1-9451-439e-ac2b-6343a026eef6', 'default', 'b0000000-0000-0000-0004-000000000004', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Hệ vi sinh đường ruột: 7 Thực phẩm lên men nuôi dưỡng lợi khuẩn","audio_url":null,"youtube_id":"e9-INC1uflE","description":"• **Điểm cốt lõi:** Hệ vi sinh ruột tạo ra hơn 90% lượng Serotonin của toàn bộ cơ thể.\n• **Ứng dụng thực hành:** Tâm trạng bất an, lo âu và trầm cảm thường bắt nguồn từ một đường ruột bị loạn khuẩn và viêm mạn.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/e9-INC1uflE/hqdefault.jpg"},{"title":"02. Tế bào NeuroPort và trục thần kinh ruột - não bộ (Gut-Brain Axis)","audio_url":null,"youtube_id":"vwqjaFU0JC8","description":"• **Điểm cốt lõi:** Chất xơ hòa tan là thức ăn thiết yếu nuôi dưỡng lợi khuẩn sản sinh Butyrate – nguồn năng lượng duy nhất.\n• **Mục tiêu thực hành:** Tái tạo và làm lành các tế bào biểu mô đại tràng.","duration_text":"1:51","thumbnail_url":"https://i.ytimg.com/vi/vwqjaFU0JC8/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Mất cân bằng hệ vi sinh đường ruột (Dysbiosis)","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Sau mỗi đợt dùng kháng sinh, hệ vi sinh đường ruột có thể mất từ 3 đến 6 tháng mới hồi phục.\n• **Ứng dụng thực hành:** Bắt buộc phải bổ sung men vi sinh và thực phẩm lên men tự nhiên.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Vai trò của Prebiotic (chất xơ) và Probiotic sống","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Chế độ ăn đa dạng với hơn 30 loại thực phẩm nguồn gốc thực vật mỗi tuần là chìa khóa vàng.\n• **Tác dụng sinh học:** Hệ vi sinh vật đường ruột phong phú và giàu sức đề kháng.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('266338ad-bd0c-4025-bd78-1a1c3a69fcb5', 'default', 'b0000000-0000-0000-0006-000000000003', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và sinh lý tuyến tụy ngoại tiết và nội tiết 3D","audio_url":null,"youtube_id":"LLL7Hu6oG3U","description":"• **Định nghĩa & Bản chất:** Tiểu đường tuýp 2 bản chất.\n• **Ý nghĩa chuyên môn:** Bệnh lý kháng Insulin do dư thừa năng lượng tích mỡ, không phải do tụy bị hỏng ngay từ ban đầu.","duration_text":"4:36","thumbnail_url":"https://i.ytimg.com/vi/LLL7Hu6oG3U/hqdefault.jpg"},{"title":"02. Hiểu rõ về bệnh tiểu đường Tuýp 2: Kháng insulin tại gan và cơ bắp","audio_url":null,"youtube_id":"_rjKydrefAU","description":"• **Điểm cốt lõi:** Tập luyện phát triển cơ bắp là cách tốt nhất để chữa kháng Insulin.\n• **Cơ chế sinh học:** Mô cơ có thể hấp thu đường trực tiếp mà không cần phụ thuộc hoàn toàn vào Insulin.","duration_text":"3:00","thumbnail_url":"https://i.ytimg.com/vi/_rjKydrefAU/hqdefault.jpg"},{"title":"03. Tiểu đường Tuýp 2: Nguyên nhân gốc rễ và giải pháp can thiệp tự nhiên","audio_url":null,"youtube_id":"EpOE0zj3UsI","description":"• **Định nghĩa & Bản chất:** Dấu hiệu vệt da sẫm màu ở sau gáy hoặc nách (gai đen).\n• **Ý nghĩa chuyên môn:** Tín hiệu lâm sàng cảnh báo nồng độ Insulin trong máu đang tăng rất cao.","duration_text":"7:47","thumbnail_url":"https://i.ytimg.com/vi/EpOE0zj3UsI/hqdefault.jpg"},{"title":"04. Đái tháo đường Tuýp 1: Cơ chế tự miễn phá hủy tế bào Beta tụy","audio_url":null,"youtube_id":"JaYcs0wIxMk","description":"• **Điểm cốt lõi:** Cắt giảm đường tinh chế và áp dụng khoảng nhịn giữa các bữa ăn.\n• **Tác dụng sinh học:** Các thụ thể tế bào được nghỉ ngơi và lấy lại độ nhạy cảm tự nhiên với Insulin.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/JaYcs0wIxMk/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('c35e4d06-6381-4b74-a710-29097f9492ca', 'default', 'b0000000-0000-0000-0004-000000000003', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và chức năng đại tràng: Tái hấp thu nước & Tạo khuôn phân","audio_url":null,"youtube_id":"GV94HZoQhi8","description":"• **Điểm cốt lõi:** Đại tràng tái hấp thu gần 2 lít nước mỗi ngày.\n• **Ứng dụng thực hành:** Nếu bạn uống không đủ nước, đại tràng sẽ rút kiệt nước từ chất thải khiến phân biến thành sỏi khô cứng gây táo bón.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/GV94HZoQhi8/hqdefault.jpg"},{"title":"02. Sinh lý nhu động ruột già và cơ chế phản xạ tống phân","audio_url":null,"youtube_id":"og2S8ZkOv-g","description":"• **Điểm cốt lõi:** Phản xạ đi ngoài mạnh nhất vào buổi sáng ngay sau khi thức dậy nhờ phản xạ dạ dày - ruột.\n• **Ứng dụng thực hành:** Hãy tập thói quen uống 1 ly nước ấm và đi vệ sinh cố định vào khung giờ này.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/og2S8ZkOv-g/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Táo bón mạn tính, trĩ và các rối loạn bài tiết","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Cơ chế tác động:** Táo bón mạn tính làm tăng áp lực ổ bụng khi rặn,.\n• **Hậu quả lâm sàng:** Các đám rối tĩnh mạch trĩ bị ứ máu phình to, dẫn đến sa búi trĩ và chảy máu tươi.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Tầm soát Polyp đại tràng và phòng ngừa ung thư đại trực tràng","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Polyp đại tràng tiến triển hoàn toàn không có triệu chứng đau đớn.\n• **Ứng dụng thực hành:** Chủ động nội soi định kỳ giúp loại bỏ polyp ngay từ giai đoạn lành tính, triệt tiêu nguy cơ ung thư.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
