  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('f536b268-e1fa-49e6-81df-396b16302856', 'default', 'b0000000-0000-0000-0004-000000000005', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Enzyme tiêu hóa: Amylase, Protease và Lipase phân giải thức ăn","audio_url":null,"youtube_id":"UHBMu20GXF4","description":"• **Điểm cốt lõi:** Enzyme tiêu hóa suy giảm theo tuổi tác và sự suy kiệt tuyến tụy.\n• **Ứng dụng thực hành:** Bổ sung enzyme tự nhiên từ dứa (Bromelain) và đu đủ (Papain) giúp hỗ trợ phân giải đạm rất tốt.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/UHBMu20GXF4/hqdefault.jpg"},{"title":"02. Vai trò của Insulin và men chuyển hóa trong cơ thể","audio_url":null,"youtube_id":"5zM-j1V2ruQ","description":"• **Điểm cốt lõi:** Cơ thể không thể hấp thu protein nguyên vẹn.\n• **Ứng dụng thực hành:** Nếu thiếu protease, đạm thô lọt xuống ruột già sẽ lên men thối rữa tạo ra mùi hôi khó chịu và độc tố cho gan.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/5zM-j1V2ruQ/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Thiếu hụt enzyme tiêu hóa ở người trưởng thành","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Enzyme Lipase của tụy chỉ hoạt động hiệu quả khi chất béo đã được dịch mật nhũ tương hóa thành các hạt siêu nhỏ.\n• **Ứng dụng thực hành:** Người cắt túi mật thường gặp khó khăn tiêu hóa mỡ.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Cách kích hoạt cơ thể tự tiết đủ enzyme tự nhiên","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Không nên uống quá nhiều nước lạnh trong khi ăn.\n• **Cơ chế sinh học:** Sẽ làm loãng nồng độ enzyme tiêu hóa và giảm nhiệt độ tối ưu (37 độ C) của các phản ứng sinh hóa trong dạ dày.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('88d0f521-9fc8-4e49-b786-a174f66858a3', 'default', 'b0000000-0000-0000-0006-000000000002', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và chức năng hormone tuyến thượng thận (Adrenaline/Cortisol)","audio_url":null,"youtube_id":"lyw1A_AMTCo","description":"• **Điểm cốt lõi:** Cortisol tăng cao mạn tính do stress thúc đẩy quá trình tích tụ mỡ sâu nội tạng quanh eo và bẻ gãy các mô cơ nạc.\n• **Mục tiêu thực hành:** Chuyển hóa thành đường.","duration_text":"4:20","thumbnail_url":"https://i.ytimg.com/vi/lyw1A_AMTCo/hqdefault.jpg"},{"title":"02. Mất ngủ, khó ngủ: Nguyên nhân gốc rễ liên quan Stress thượng thận","audio_url":null,"youtube_id":"zFiEhzZN-ow","description":"• **Điểm cốt lõi:** Cortisol cao vào ban đêm sẽ trực tiếp ức chế tuyến tùng tiết Melatonin.\n• **Ứng dụng thực hành:** Gây ra hiện tượng mắt mở thao thức dù cơ thể vô cùng mệt mỏi.","duration_text":"6:39","thumbnail_url":"https://i.ytimg.com/vi/zFiEhzZN-ow/hqdefault.jpg"},{"title":"03. Trầm cảm và lo âu ở người trẻ: Nguyên nhân sinh hóa và cách phục hồi","audio_url":null,"youtube_id":"nHKDWdPl9vk","description":"• **Điểm cốt lõi:** Lạm dụng cà phê và chất kích thích khi cơ thể đang kiệt quệ chỉ ép tuyến thượng thận vắt kiệt những giọt Adrenaline cuối cùng.\n• **Ứng dụng thực hành:** Đẩy nhanh tiến trình suy kiệt.","duration_text":"9:05","thumbnail_url":"https://i.ytimg.com/vi/nHKDWdPl9vk/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Hội chứng kiệt quệ thượng thận (Adrenal Fatigue)","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Các bài tập thở chậm 4-7-8, tiếp xúc ánh nắng sớm và bổ sung thảo dược thích nghi (Ashwagandha, Rhodiola).\n• **Tác dụng sinh học:** Điều hòa lại trục HPA thượng thận.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('b47d08d6-9b4a-4638-b47c-c03b956922bb', 'default', 'b0000000-0000-0000-0006-000000000004', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Tuyến tùng, Melatonin và chu kỳ giấc ngủ sâu phục hồi","audio_url":null,"youtube_id":"wBAtpVd__Eo","description":"• **Điểm cốt lõi:** Ánh sáng xanh từ điện thoại đánh lừa não bộ rằng trời vẫn đang sáng.\n• **Ứng dụng thực hành:** Ức chế tuyến tùng tiết Melatonin và làm phá hủy hoàn toàn chất lượng giấc ngủ sâu.","duration_text":"4:43","thumbnail_url":"https://i.ytimg.com/vi/wBAtpVd__Eo/hqdefault.jpg"},{"title":"02. Rối loạn giấc ngủ và cách cân bằng lại trục sinh học","audio_url":null,"youtube_id":"zFiEhzZN-ow","description":"• **Điểm cốt lõi:** Hormone tăng trưởng GH tiết ra nhiều nhất lúc ngủ sâu từ 23h đêm đến 2h sáng.\n• **Ứng dụng thực hành:** Ngủ muộn sau 12h đêm làm mất đi cơ hội vàng để cơ thể sửa chữa và tái sinh mô nạc.","duration_text":"6:39","thumbnail_url":"https://i.ytimg.com/vi/zFiEhzZN-ow/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Hormone tăng trưởng (GH) tiết ra lúc 23h - 2h sáng","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Melatonin là một chất chống oxy hóa ty thể cực mạnh.\n• **Ứng dụng thực hành:** Có khả năng quét dọn gốc tự do và bảo vệ não bộ khỏi các bệnh thoái hóa thần kinh.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Tối ưu hóa phòng ngủ và giảm ánh sáng xanh bảo vệ Melatonin","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Nhiệt độ phòng ngủ mát mẻ giúp nhiệt độ lõi cơ thể hạ xuống.\n• **Ứng dụng thực hành:** Kích hoạt phản xạ sinh học đưa hệ thần kinh nhanh chóng chìm vào trạng thái ngủ sâu phục hồi.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('ccf72169-3939-442b-8e7c-300c469c3752', 'default', 'b0000000-0000-0000-0000-000000000006', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Thoát vị đĩa đệm cột sống và cơ chế chèn ép thần kinh","audio_url":null,"youtube_id":"0antcXeEShQ","description":"• **Điểm cốt lõi:** Đau lưng cấp tính không nên nằm bất động tại giường quá 48 giờ.\n• **Ứng dụng thực hành:** Nằm lì làm cơ bắp teo nhược và giảm tuần hoàn thẩm thấu nuôi dưỡng đĩa đệm khiến bệnh lâu khỏi hơn.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/0antcXeEShQ/hqdefault.jpg"},{"title":"02. Trượt đốt sống thoái hóa L4-L5 và hẹp ống sống","audio_url":null,"youtube_id":"dK8hcSNa1Xg","description":"• **Điểm cốt lõi:** Hội chứng cổ vai cánh tay thường bắt nguồn từ thoái hóa rễ C6-C7.\n• **Ứng dụng thực hành:** Cần phân biệt với viêm quanh khớp vai đơn thuần bằng cách kiểm tra tầm vận động xoay cổ (Spurling Test).","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/dK8hcSNa1Xg/hqdefault.jpg"},{"title":"03. Viêm cột sống dính khớp và quá trình vôi hóa cột sống","audio_url":null,"youtube_id":"ZNiivNxupnY","description":"• **Điểm cốt lõi:** Nghiệm pháp Adams cúi gập người là bài kiểm tra đơn giản và nhạy nhất.\n• **Mục tiêu thực hành:** Phát hiện sớm vẹo cột sống ở thanh thiếu niên nhờ phát hiện ụ gồ sườn không đối xứng.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/ZNiivNxupnY/hqdefault.jpg"},{"title":"04. Vẹo cột sống vô căn và biến dạng cột sống","audio_url":null,"youtube_id":"H65R2bY3ltk","description":"• **Điểm cốt lõi:** Trượt đốt sống độ 1 và 2 hoàn toàn có thể sống khỏe mạnh trọn đời nếu luyện tập cơ ngang bụng và cơ mông khỏe.\n• **Ứng dụng thực hành:** Tuyệt đối tránh các động tác ưỡn lưng quá mức (Hyperextension).","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/H65R2bY3ltk/hqdefault.jpg"},{"title":"05. Phân biệt đau thần kinh tọa và chèn ép rễ thần kinh","audio_url":null,"youtube_id":"C9TI_aBZpQY","description":"• **Điểm cốt lõi:** Phẫu thuật cột sống chỉ là giải pháp cuối cùng khi có chèn ép thần kinh tiến triển hoặc hội chứng chùm đuôi ngựa.\n• **Ứng dụng thực hành:** 95% trường hợp phục hồi bền vững nhờ bảo tồn tự nhiên.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/C9TI_aBZpQY/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('87db58ea-4ea2-45ae-a355-77503bd71c24', 'default', 'b0000000-0000-0000-0000-000000000005', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Kỹ thuật nâng vật an toàn và bảo vệ cột sống thắt lưng","audio_url":null,"youtube_id":"ghKFigEGSjM","description":"• **Điểm cốt lõi:** Ngồi tựa lưng với góc ngả 100-110 độ có đệm thắt lưng.\n• **Tác dụng sinh học:** Phân tán áp lực lên đĩa đệm tốt hơn nhiều so với việc cố gắng ngồi thẳng đơ 90 độ liên tục suốt nhiều giờ.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/ghKFigEGSjM/hqdefault.jpg"},{"title":"02. Tác hại của ngồi khom lưng lên cột sống ngực và cơ","audio_url":null,"youtube_id":"zVSfKSupbJ4","description":"• **Trọng tâm cơ chế:** Khi nâng vật nặng, luôn biến cơ thể thành đòn bẩy chân gập (Leg Drive).\n• **Chi tiết sinh học:** Ôm sát vật vào ngực, dùng sức mạnh cơ đùi và cơ mông thay vì cúi gập cong lưng chịu tải.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/zVSfKSupbJ4/hqdefault.jpg"},{"title":"03. Tổn thương cột sống thắt lưng do ngồi khom gù kéo dài","audio_url":null,"youtube_id":"Tk8CuCrhCrA","description":"• **Điểm cốt lõi:** Gối ngủ quá cao làm gập đốt sống cổ suốt 8 tiếng.\n• **Ứng dụng thực hành:** Chèn ép động mạch đốt sống thân nền gây thiếu máu não thức dậy chóng mặt, căng cứng cơ thang vai gáy.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Tk8CuCrhCrA/hqdefault.jpg"},{"title":"04. Bài tập và điều chỉnh tư thế đầu đưa ra trước (Text Neck)","audio_url":null,"youtube_id":"r_saIJDw06o","description":"• **Điểm cốt lõi:** Nằm kẹp gối giữa hai đầu gối khi ngủ nghiêng.\n• **Tác dụng sinh học:** Giữ xương chậu thăng bằng, ngăn ngừa khớp cùng chậu và cột sống thắt lưng bị vặn xoắn gây đau buốt lúc nửa đêm.","duration_text":"2:15","thumbnail_url":"https://i.ytimg.com/vi/r_saIJDw06o/hqdefault.jpg"},{"title":"05. Bài tập phục hồi nhóm cơ cổ chuyên sâu (Dr.Loan)","audio_url":null,"youtube_id":"xWt7Hnig9RQ","description":"• **Cơ chế tác động:** Lối sống tĩnh tại ngồi lì trên 6 tiếng liên tục làm tê liệt phản xạ co cơ tự nhiên,.\n• **Hậu quả lâm sàng:** Đĩa đệm mất nước và các dây chằng cột sống bị kéo căng dão mạn tính.","duration_text":"7:05","thumbnail_url":"https://i.ytimg.com/vi/xWt7Hnig9RQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('6bbb2127-e142-4efd-b21d-f1059385c5cb', 'default', 'b0000000-0000-0000-0008-000000000004', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. [Cần bổ sung] 5 Lớp kháng thể chính: IgG, IgA, IgM, IgE, IgD","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Kháng thể IgM xuất hiện sớm báo hiệu nhiễm trùng cấp tính.\n• **Ứng dụng thực hành:** Kháng thể IgG xuất hiện muộn hơn nhưng tồn tại nhiều năm tạo miễn dịch bảo vệ bền vững.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"02. [Cần bổ sung] Kháng thể IgA niêm mạc bảo vệ đường ruột và đường hô hấp","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** IgG là món quà miễn dịch duy nhất mẹ truyền cho con qua nhau thai.\n• **Ứng dụng thực hành:** Bảo vệ bé trong 6 tháng đầu đời trước khi hệ miễn dịch của bé tự hoàn thiện.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"03. [Cần bổ sung] IgG: Kháng thể bảo vệ bền vững xuyên qua nhau thai","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Kháng thể IgA tiết (sIgA) trên niêm mạc ruột và đường thở là tuyến chốt chặn đầu tiên.\n• **Ứng dụng thực hành:** Thiếu sIgA khiến bạn hay bị viêm họng và tiêu chảy tái diễn.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Kháng thể trung hòa độc tố và khóa mục tiêu virus","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Kháng thể tiêu diệt virus bằng cách khóa chặt các gai thụ thể.\n• **Ứng dụng thực hành:** Ngăn không cho virus bám và chui vào bên trong tế bào khỏe mạnh của cơ thể.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('f5a032f6-9f7c-45ed-905f-911bdded34d2', 'default', 'b0000000-0000-0000-0006-000000000005', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ chế kháng insulin và tiền đái tháo đường do lối sống ít vận động","audio_url":null,"youtube_id":"SEnNH2U8LMY","description":"• **Điểm cốt lõi:** Hội chứng chuyển hóa làm tăng gấp 3 lần nguy cơ nhồi máu cơ tim và đột quỵ.\n• **Ứng dụng thực hành:** Kiểm soát mỡ bụng và độ nhạy Insulin là mục tiêu phòng ngừa hàng đầu.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/SEnNH2U8LMY/hqdefault.jpg"},{"title":"02. Bệnh Gút: Cơ chế lắng đọng tinh thể Urat gây viêm khớp sưng đau","audio_url":null,"youtube_id":"lFvlH3wIPF0","description":"• **Điểm cốt lõi:** Cơn gút cấp bắt nguồn từ tinh thể Urat hình kim đâm rách màng hoạt dịch khớp.\n• **Ứng dụng thực hành:** Uống bia và nước ngọt Fructose là hai thủ phạm hàng đầu làm tăng vọt Axit Uric máu.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/lFvlH3wIPF0/hqdefault.jpg"},{"title":"03. Bệnh Gút (Thống phong): Nguyên nhân gốc rễ, triệu chứng và giải pháp","audio_url":null,"youtube_id":"0vWAdFdLyEI","description":"• **Điểm cốt lõi:** Rối loạn tiền đình ở người trung niên thường bắt nguồn từ thoái hóa đốt sống cổ chèn ép động mạch đốt sống.\n• **Ứng dụng thực hành:** Cần kết hợp chỉnh hình cột sống và tăng lưu thông máu não.","duration_text":"4:19","thumbnail_url":"https://i.ytimg.com/vi/0vWAdFdLyEI/hqdefault.jpg"},{"title":"04. Rối loạn tiền đình và tuần hoàn não: Nguyên nhân gốc rễ & Phòng ngừa","audio_url":null,"youtube_id":"O7k5B616nuE","description":"• **Điểm cốt lõi:** Uống đủ nước kiềm giàu khoáng.\n• **Tác dụng sinh học:** Kiềm hóa nước tiểu nhẹ nhàng, hỗ trợ thận tăng tốc độ đào thải tinh thể Axit Uric ra ngoài, ngăn ngừa sỏi Urat.","duration_text":"10:05","thumbnail_url":"https://i.ytimg.com/vi/O7k5B616nuE/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('bdde28c7-f000-419a-81f3-fa88a626b9db', 'default', 'b0000000-0000-0000-0000-000000000024', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu đường dẫn khí và cơ chế hít thở","audio_url":null,"youtube_id":"Z0rKB1Q2nUE","description":"• **Điểm cốt lõi:** Cơ hoành là cơ hô hấp chính yếu.\n• **Ứng dụng thực hành:** Thở bằng ngực nông chỉ dùng được 20% dung tích phổi, trong khi thở cơ hoành (thở bụng) giúp thông khí sâu và kích hoạt đối giao cảm.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Z0rKB1Q2nUE/hqdefault.jpg"},{"title":"02. Giải phẫu màng phế nang - mao mạch và con đường trao đổi khí","audio_url":null,"youtube_id":"tBHix90hrCA","description":"• **Điểm cốt lõi:** Màng phế nang mỏng chỉ nửa micromet với diện tích bằng cả căn nhà.\n• **Ứng dụng thực hành:** Hít khói thuốc lá và bụi mịn PM2.5 làm phá hủy vĩnh viễn màng lọc mong manh này.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/tBHix90hrCA/hqdefault.jpg"},{"title":"03. Viêm phế quản: Tại sao tái đi tái lại & Giải pháp gốc rễ","audio_url":null,"youtube_id":"0tokQdry8Is","description":"• **Điểm cốt lõi:** Chất Surfactant là tấm đệm sinh học chống xẹp phế nang.\n• **Ứng dụng thực hành:** Thiếu surfactant ở trẻ sinh non gây hội chứng suy hô hấp cấp đe dọa tính mạng.","duration_text":"6:30","thumbnail_url":"https://i.ytimg.com/vi/0tokQdry8Is/hqdefault.jpg"},{"title":"04. Bệnh phổi tắc nghẽn mạn tính (COPD) và khí phế thủng","audio_url":null,"youtube_id":"YkMep-OqZsI","description":"• **Cơ chế tác động:** Khí phế thủng trong COPD làm mất tính đàn hồi của phế nang.\n• **Hậu quả lâm sàng:** Bệnh nhân không thể thở ra hết dưỡng khí cũ, dẫn đến lồng ngực biến dạng hình thùng.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/YkMep-OqZsI/hqdefault.jpg"},{"title":"05. Ngáy và hội chứng ngưng thở khi ngủ do tắc nghẽn đường thở","audio_url":null,"youtube_id":"v-Z0sVF8XPU","description":"• **Điểm cốt lõi:** Hội chứng ngưng thở khi ngủ làm gián đoạn hô hấp hàng trăm lần mỗi đêm.\n• **Ứng dụng thực hành:** Làm sụt giảm oxy máu não trầm trọng và tăng gấp 3 lần nguy cơ nhồi máu cơ tim.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/v-Z0sVF8XPU/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('5a5e05ae-c38a-4ad7-bd9c-9d7c62f866ad', 'default', 'b0000000-0000-0000-0000-000000000025', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và chức năng 12 đôi dây thần kinh sọ não 3D","audio_url":null,"youtube_id":"mNvVou6jxWg","description":"• **Điểm cốt lõi:** Dây thần kinh số X (dây phế vị) là cầu nối dài nhất từ thân não đến tim, phổi và ruột.\n• **Ứng dụng thực hành:** Kích hoạt dây X qua hít thở sâu giúp hạ nhịp tim và ổn định tiêu hóa tức thì.","duration_text":"9:21","thumbnail_url":"https://i.ytimg.com/vi/mNvVou6jxWg/hqdefault.jpg"},{"title":"02. Hàng rào máu não: Tấm khiên bảo vệ trung ương thần kinh","audio_url":null,"youtube_id":"0cKG1hTyozs","description":"• **Điểm cốt lõi:** Hàng rào máu não là lá chắn bảo vệ trung ương thần kinh.\n• **Ứng dụng thực hành:** Tình trạng viêm mạn tính và mất ngủ có thể làm rò rỉ hàng rào này, tạo điều kiện cho độc tố xâm nhập gây thoái hóa não.","duration_text":"4:15","thumbnail_url":"https://i.ytimg.com/vi/0cKG1hTyozs/hqdefault.jpg"},{"title":"03. Chất dẫn truyền thần kinh GABA và Glutamate: Ức chế vs Kích thích","audio_url":null,"youtube_id":"cDiMjHmxNgY","description":"• **Điểm cốt lõi:** Glutamate kích thích tư duy còn GABA làm dịu thần kinh.\n• **Ứng dụng thực hành:** Tăng cường hoạt tính GABA tự nhiên giúp giải tỏa stress, làm êm dịu não bộ và cải thiện giấc ngủ sâu.","duration_text":"1:29","thumbnail_url":"https://i.ytimg.com/vi/cDiMjHmxNgY/hqdefault.jpg"},{"title":"04. Hệ thần kinh thực vật: Giao cảm (Fight/Flight) và Đối giao cảm (Rest/Digest)","audio_url":null,"youtube_id":"gzFtXyXUG5k","description":"• **Điểm cốt lõi:** Hệ giao cảm bị kích hoạt mạn tính do áp lực cuộc sống giữ cơ thể trong trạng thái báo động đỏ liên tục.\n• **Ứng dụng thực hành:** Làm teo hồi hải mã (trung tâm trí nhớ) và tăng huyết áp.","duration_text":"3:59","thumbnail_url":"https://i.ytimg.com/vi/gzFtXyXUG5k/hqdefault.jpg"},{"title":"05. Nguyên tắc bảo vệ não bộ: Giảm nguy cơ suy giảm trí nhớ & sa sút trí tuệ","audio_url":null,"youtube_id":"YBcPQGi1ykM","description":"• **Điểm cốt lõi:** Não bộ có tính mềm dẻo thần kinh (Neuroplasticity) trọn đời.\n• **Ứng dụng thực hành:** Học kỹ năng mới, tập thể dục nhịp điệu và ăn uống giàu Omega-3 giúp tạo thêm các synap kết nối nơron mới.","duration_text":"5:39","thumbnail_url":"https://i.ytimg.com/vi/YBcPQGi1ykM/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('fb8d5221-f1bb-4384-85be-70fc9486c51f', 'default', 'b0000000-0000-0000-0000-000000000026', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Nhiễm trùng đường tiết niệu: Nguyên nhân, cơ chế và phòng ngừa","audio_url":null,"youtube_id":"1CHp3RZaYQs","description":"• **Điểm cốt lõi:** 1 triệu đơn vị Nephron trong mỗi quả thận lọc 180 lít dịch mỗi ngày.\n• **Ứng dụng thực hành:** Các nephron một khi đã xơ hóa hoại tử do tiểu đường hoặc huyết áp cao sẽ không thể tái sinh.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/1CHp3RZaYQs/hqdefault.jpg"},{"title":"02. Cơ chế thần kinh kiểm soát phản xạ bàng quang và đi tiểu","audio_url":null,"youtube_id":"int0eXK2zow","description":"• **Điểm cốt lõi:** Thận sản xuất hormone EPO kích thích tủy xương tạo hồng cầu.\n• **Ứng dụng thực hành:** Bệnh nhân suy thận mạn tính luôn bị thiếu máu nặng nề do thiếu hụt hormone này.","duration_text":"1:41","thumbnail_url":"https://i.ytimg.com/vi/int0eXK2zow/hqdefault.jpg"},{"title":"03. Tiểu không tự chủ khi gắng sức do suy yếu cơ sàn chậu","audio_url":null,"youtube_id":"B3MMMc2ILRc","description":"• **Điểm cốt lõi:** Thói quen nhịn tiểu làm bàng quang bị giãn quá mức.\n• **Ứng dụng thực hành:** Nước tiểu ứ đọng tạo cơ hội cho vi khuẩn E.coli di chuyển ngược dòng gây viêm đài bể thận và nhiễm trùng huyết.","duration_text":"1:46","thumbnail_url":"https://i.ytimg.com/vi/B3MMMc2ILRc/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Cấu trúc Nephron lọc máu và cân bằng nước tiểu của thận","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Tập bài tập sàn chậu Kegel giúp gia cố nhóm cơ nâng đỡ đáy chậu, là giải pháp vàng không dùng thuốc.\n• **Mục tiêu thực hành:** Trị dứt điểm chứng tiểu không tự chủ khi gắng sức.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('23683284-f787-4957-b2a3-f1a568550ab0', 'default', 'b0000000-0000-0000-0000-000000000013', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Chuyển hóa lipid: Tiêu hóa, vận chuyển và nhiễm toan xeton","audio_url":null,"youtube_id":"nx3WbbjtLJ4","description":"• **Định nghĩa & Bản chất:** Chất béo chuyển hóa (Trans fat) trong dầu chiên đi chiên lại.\n• **Ý nghĩa chuyên môn:** Thủ phạm nguy hiểm hàng đầu gây viêm nội mạc và xơ vữa mạch máu, cần loại bỏ triệt để.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/nx3WbbjtLJ4/hqdefault.jpg"},{"title":"02. Chuyển hóa cholesterol và vai trò thực tế của LDL, HDL","audio_url":null,"youtube_id":"Wyz2wBilQso","description":"• **Điểm cốt lõi:** Tỷ lệ Omega-6/Omega-3 trong khẩu phần hiện đại bị lệch quá lớn.\n• **Ứng dụng thực hành:** Tăng cường cá béo (cá hồi, cá thu) giúp dập tắt viêm và bảo vệ tim mạch.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Wyz2wBilQso/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Omega-3 EPA/DHA và màng phospholipid tế bào","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Cholesterol là nguyên liệu tổng hợp màng tế bào và hormone sinh dục.\n• **Ứng dụng thực hành:** Tránh kiêng khem mù quáng mà cần tập trung hạ thấp mức độ oxy hóa của mỡ máu.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Nhận diện chất béo chuyển hóa (Trans fat) gây hại","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Axit béo Omega-3 EPA và DHA có tác dụng bảo vệ tế bào thần kinh não bộ.\n• **Ứng dụng thực hành:** Cải thiện thị lực và giảm nguy cơ đông máu cục bộ nguy hiểm.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('208e5840-4511-4c29-8169-f93d1cdac94a', 'default', 'b0000000-0000-0000-0004-000000000001', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và tổng quan chức năng hệ tiêu hóa ở người","audio_url":null,"youtube_id":"Q4AD4ILfkNQ","description":"• **Trọng tâm cơ chế:** Nhai kỹ là bước khởi đầu quyết định thành bại của hệ tiêu hóa.\n• **Chi tiết sinh học:** Nhai 25-30 lần giúp thức ăn được nhuyễn mịn và thấm đẫm enzyme Amylase trước khi chạm dạ dày.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Q4AD4ILfkNQ/hqdefault.jpg"},{"title":"02. Giải phẫu và sinh lý dạ dày: Tiết axit HCl và enzyme Pepsin","audio_url":null,"youtube_id":"B3O7735YF7M","description":"• **Điểm cốt lõi:** Axit dạ dày pH 1.5-2.0 là hàng rào vô trùng số 1 của cơ thể.\n• **Ứng dụng thực hành:** Uống thuốc ức chế axit (PPI) kéo dài làm giảm độ toan, tạo cơ hội cho vi khuẩn gây hại lọt xuống đường ruột.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/B3O7735YF7M/hqdefault.jpg"},{"title":"03. Mô phỏng 3D hệ tiêu hóa từ khoang miệng đến thực quản","audio_url":null,"youtube_id":"Y540F7rxoRA","description":"• **Điểm cốt lõi:** Trào ngược dạ dày thực quản không phải lúc nào cũng do thừa axit mà đa phần do áp lực ổ bụng tăng cao đẩy cơ thắt dưới thực quản (LES) mở ngược lên..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Y540F7rxoRA/hqdefault.jpg"},{"title":"04. Cơ chế trào ngược dạ dày thực quản (GERD) và biến chứng","audio_url":null,"youtube_id":"5_3pbRpu2_I","description":"• **Cơ chế tác động:** Ăn tối sát giờ ngủ (dưới 3 tiếng) hoặc nằm ngay sau ăn.\n• **Hậu quả lâm sàng:** Trọng lực không giữ được dịch vị, gây ợ chua đêm và viêm thanh quản mạn tính.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/5_3pbRpu2_I/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('1f748deb-9859-44ce-9b0a-f67225295f67', 'default', 'b0000000-0000-0000-0007-000000000003', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ vòng Oddi và chức năng dự trữ cô đặc mật của túi mật","audio_url":null,"youtube_id":"nIo5VqMlauU","description":"• **Điểm cốt lõi:** Túi mật cô đặc dịch mật lên gấp 10 lần để sẵn sàng tống xuất khi chất béo chạm tới tá tràng.\n• **Ứng dụng thực hành:** Nhịn ăn sáng kéo dài làm mật bị ứ đọng cô đặc quá mức, dễ kết tủa thành sỏi mật.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/nIo5VqMlauU/hqdefault.jpg"},{"title":"02. Sỏi mật: Nguyên nhân gốc rễ hình thành sỏi bùn, sỏi cholesterol & Giải pháp","audio_url":null,"youtube_id":"oMk9rcHw_Jw","description":"• **Điểm cốt lõi:** Muối mật nhũ tương hóa mỡ thành các hạt Micelle siêu nhỏ.\n• **Ứng dụng thực hành:** Không có muối mật, các vitamin tan trong dầu (A, D, E, K) và Omega-3 hoàn toàn không thể hấp thu vào cơ thể.","duration_text":"4:10","thumbnail_url":"https://i.ytimg.com/vi/oMk9rcHw_Jw/hqdefault.jpg"},{"title":"03. Mô phỏng phẫu thuật cắt túi mật mở (Open Cholecystectomy)","audio_url":null,"youtube_id":"fwFuQHxU3_M","description":"• **Điểm cốt lõi:** 95% lượng muối mật được tái hấp thu ở cuối ruột non để tái sử dụng.\n• **Ứng dụng thực hành:** Chất xơ hòa tan trong bữa ăn giúp gắn kết và đào thải một phần muối mật, buộc gan tiêu hao Cholesterol để tạo mật mới.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/fwFuQHxU3_M/hqdefault.jpg"},{"title":"04. Phẫu thuật cắt túi mật mở và giải phẫu hệ thống đường mật 3D","audio_url":null,"youtube_id":"xzaJpPAv-0E","description":"• **Điểm cốt lõi:** Người đã phẫu thuật cắt túi mật mất kho lưu trữ cô đặc mật.\n• **Ứng dụng thực hành:** Dịch mật chảy nhỏ giọt liên tục xuống ruột khiến họ dễ bị tiêu chảy phân mỡ khi ăn bữa ăn nhiều dầu mỡ.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/xzaJpPAv-0E/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('95a91feb-3fe4-4492-aec8-ebd075e6271b', 'default', 'b0000000-0000-0000-0000-000000000002', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ chế thoát vị đĩa đệm và chèn ép rễ thần kinh","audio_url":null,"youtube_id":"mqe4uEaLjRM","description":"• **Điểm cốt lõi:** Nhân nhầy đĩa đệm hoạt động như một bọc thủy lực phân tán lực nén 360 độ.\n• **Ứng dụng thực hành:** Mất nước theo tuổi tác làm nhân nhầy xẹp xuống, mất tính đàn hồi và dồn áp lực xé rách vòng sợi.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/mqe4uEaLjRM/hqdefault.jpg"},{"title":"02. Rách vòng sợi và thoát vị đĩa đệm chèn ép","audio_url":null,"youtube_id":"sd1sig3xfE8","description":"• **Điểm cốt lõi:** Đĩa đệm người lớn không có mạch máu.\n• **Ứng dụng thực hành:** Chỉ có vận động nhịp nhàng (đi bộ, kéo giãn) mới tạo áp lực bơm - hút đưa dịch dinh dưỡng qua mâm sụn để tái tạo mô đĩa đệm.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/sd1sig3xfE8/hqdefault.jpg"},{"title":"03. Thoái hóa đĩa đệm thắt lưng và cơ chế gây đau","audio_url":null,"youtube_id":"LS8c1z0sovo","description":"• **Điểm cốt lõi:** Ngồi làm việc sai tư thế tạo áp lực nội đĩa đệm lên đến 185% so với đứng thẳng.\n• **Ứng dụng thực hành:** Cần đứng dậy thay đổi tư thế mỗi 45-60 phút để giải phóng áp lực cho đĩa đệm thắt lưng.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/LS8c1z0sovo/hqdefault.jpg"},{"title":"04. Thoái hóa đĩa đệm cột sống cổ và cơ chế đau","audio_url":null,"youtube_id":"eijvLKjwvcE","description":"• **Trọng tâm cơ chế:** Vị trí sau - bên của vòng sợi là gót chân Achilles sinh học.\n• **Chi tiết sinh học:** Lớp sợi mỏng nhất và dây chằng dọc sau không che phủ hết, khiến nhân nhầy dễ thoát ra chèn ép rễ thần kinh tọa.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/eijvLKjwvcE/hqdefault.jpg"},{"title":"05. Thoát vị đĩa đệm và hẹp ống sống thắt lưng","audio_url":null,"youtube_id":"DlrJdu820yM","description":"• **Trọng tâm cơ chế:** Vận động đúng cách là liều thuốc số 1 cho đĩa đệm.\n• **Chi tiết sinh học:** Tập luyện các bài tập nén nhả trục dọc nhẹ nhàng giúp kích thích tế bào sụn tổng hợp Proteoglycan giữ nước cho nhân nhầy.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/DlrJdu820yM/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('60b733e2-b713-4c52-9a8d-8d1b6eae7b06', 'default', 'b0000000-0000-0000-0007-000000000006', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. [Cần bổ sung] Top thảo dược tự nhiên hạ men gan và bảo vệ màng tế bào gan","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Định nghĩa & Bản chất:** Silymarin trong cây kế sữa.\n• **Ý nghĩa chuyên môn:** Tấm khiên sinh học bảo vệ màng tế bào gan trước độc tố thuốc tây và kích hoạt tế bào gan tái tạo cấu trúc mới nhanh chóng.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"02. [Cần bổ sung] Nghệ vàng Curcumin và Silymarin từ cây kế sữa","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Choline (có nhiều trong lòng đỏ trứng gà và gan bò) là chất vận chuyển bắt buộc để đưa mỡ ra khỏi gan.\n• **Ứng dụng thực hành:** Ăn kiêng thiếu choline làm mỡ ứ đọng trầm trọng trong gan.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Thực phẩm giàu Choline giúp vận chuyển mỡ ra khỏi gan","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Sulforaphane trong mầm súp lơ xanh kích hoạt mạnh mẽ các enzyme giải độc Giai đoạn 2 của gan,.\n• **Tác dụng sinh học:** Vô hiệu hóa các hợp chất gây ung thư.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] 5 Thói quen đơn giản để gan tự làm sạch mỗi đêm","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Ngủ sâu giấc trước 23h là khung giờ vàng.\n• **Mục tiêu thực hành:** Tuần hoàn máu dồn về gan thực hiện chu trình thanh lọc độc tố và tái tạo tế bào chất sinh học.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('c59e79c1-4d02-4ef5-8f54-144d52904420', 'default', 'b0000000-0000-0000-0000-000000000003', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Giải phẫu và chức năng các nhóm cơ vùng thắt lưng","audio_url":null,"youtube_id":"RJ9NWoeS8nQ","description":"• **Điểm cốt lõi:** Dây chằng vàng nối giữa các bản sống có tính đàn hồi cao.\n• **Ứng dụng thực hành:** Quá trình lão hóa và viêm mạn làm dây chằng vàng dày phì đại, lồi vào lòng ống sống gây hẹp ống sống thắt lưng.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/RJ9NWoeS8nQ/hqdefault.jpg"},{"title":"02. Giải phẫu cơ cổ và nguyên nhân đau mỏi cổ vai gáy","audio_url":null,"youtube_id":"Dk3Hvx6awxc","description":"• **Điểm cốt lõi:** Cơ nhiều chân (Multifidus) là nhóm cơ sâu quan trọng nhất kiểm soát ổn định từng đốt sống.\n• **Ứng dụng thực hành:** Đau lưng làm cơ này teo biến thành mô mỡ nếu không được tập kích hoạt chuyên biệt.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Dk3Hvx6awxc/hqdefault.jpg"},{"title":"03. Cấu trúc cung đốt sống và hệ thống dây chằng vàng","audio_url":null,"youtube_id":"NCflooZLk8M","description":"• **Điểm cốt lõi:** Co thắt cơ lưng là phản ứng tự vệ của cơ thể để khóa khớp tổn thương, không phải là nguyên nhân gốc rễ.\n• **Ứng dụng thực hành:** Đấm bóp thô bạo vào chỗ co thắt cấp tính có thể làm rách thêm bao xơ đĩa đệm.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/NCflooZLk8M/hqdefault.jpg"},{"title":"04. Cấu trúc và chi phối thần kinh khớp liên mỏm","audio_url":null,"youtube_id":"6aHqadx-jKg","description":"• **Trọng tâm cơ chế:** Mất cân bằng cơ chéo dưới (Janda).\n• **Chi tiết sinh học:** Cơ gập hông và cơ thắt lưng bị co ngắn trong khi cơ mông và cơ bụng bị ức chế yếu đi, kéo xương chậu đổ trước làm cột sống ưỡn quá mức.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/6aHqadx-jKg/hqdefault.jpg"},{"title":"05. Cơ lưng rộng: Nguyên ủy, bám tận và chức năng vận động","audio_url":null,"youtube_id":"DwZXOTZvjdo","description":"• **Điểm cốt lõi:** Tập cơ cốt lõi (Core) không phải gập bụng 6 múi mà là kiểm soát cơ ngang bụng và sàn chậu.\n• **Mục tiêu thực hành:** Tạo áp lực thủy tĩnh nội bụng (IAP), giảm tải 40% lực nén lên đĩa đệm L4-L5.","duration_text":"2:46","thumbnail_url":"https://i.ytimg.com/vi/DwZXOTZvjdo/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('fad6b08a-829c-4627-a235-15becefbe081', 'default', 'b0000000-0000-0000-0000-000000000004', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Tủy sống và dây thần kinh tủy: Khác biệt về chức năng","audio_url":null,"youtube_id":"dl4SHBMBcog","description":"• **Điểm cốt lõi:** Tủy sống kết thúc ở bờ dưới L1-L2.\n• **Ứng dụng thực hành:** Từ L2 trở xuống là chùm rễ thần kinh đuôi ngựa bơi trong bể dịch não tủy. Tổn thương dưới L2 là tổn thương rễ thần kinh ngoại biên.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/dl4SHBMBcog/hqdefault.jpg"},{"title":"02. Giải phẫu và chèn ép dây thần kinh tủy cổ","audio_url":null,"youtube_id":"WLToIajbOl4","description":"• **Điểm cốt lõi:** Chèn ép rễ L5 gây mất khả năng đi bằng gót chân và tê mu bàn chân.\n• **Ứng dụng thực hành:** Chèn ép rễ S1 làm mất phản xạ gân gót và không thể nhón ngón chân đi bằng đầu mũi chân.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/WLToIajbOl4/hqdefault.jpg"},{"title":"03. Giải phẫu và chức năng dây thần kinh tủy thắt lưng","audio_url":null,"youtube_id":"uPIFuRm5IYQ","description":"• **Điểm cốt lõi:** Hội chứng chùm đuôi ngựa với tê bì vùng yên ngựa và mất chủ động đại tiểu tiện là cấp cứu ngoại thần kinh tối khẩn.\n• **Ứng dụng thực hành:** Can thiệp chậm trễ sau 48h sẽ để lại di chứng tàn phế vĩnh viễn.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/uPIFuRm5IYQ/hqdefault.jpg"},{"title":"04. Giải phẫu và đường đi dây thần kinh tọa chi phối chân","audio_url":null,"youtube_id":"8mj6EbsjChw","description":"• **Định nghĩa & Bản chất:** Cơn đau thần kinh tọa thực chất.\n• **Ý nghĩa chuyên môn:** Phản ứng viêm hóa học do nhân nhầy thoát vị giải phóng phospholipase A2 và TNF-alpha gây kích ứng rễ thần kinh, bên cạnh chèn ép cơ học.","duration_text":"4:56","thumbnail_url":"https://i.ytimg.com/vi/8mj6EbsjChw/hqdefault.jpg"},{"title":"05. Hội chứng đuôi ngựa do chèn ép rễ thần kinh thắt lưng","audio_url":null,"youtube_id":"2EllnEpmUJw","description":"• **Điểm cốt lõi:** Phục hồi thần kinh đòi hỏi thời gian.\n• **Cơ chế sinh học:** Sợi trục thần kinh ngoại biên chỉ tái sinh với tốc độ 1mm mỗi ngày trong điều kiện được giải áp và bổ sung đầy đủ vitamin nhóm B (B1, B6, B12).","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/2EllnEpmUJw/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
