values ('21316079-bae1-4642-94c2-c16e218092dd', 'default', 'b0000000-0000-0000-0005-000000000006', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cân bằng acid-base và cơ chế điều hòa pH máu sinh học","youtube_id":"EcQp36ZCfO8","description":"• **Điểm cốt lõi:** Hệ đệm Bicarbonate trong máu phản ứng trong vài giây để duy trì pH 7.40.\n• **Ứng dụng thực hành:** Uống nước ion kiềm tự nhiên hỗ trợ giảm tải gánh nặng đệm axit nội sinh của cơ thể.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/EcQp36ZCfO8/hqdefault.jpg"},{"title":"02. Nhiễm toan chuyển hóa vs Nhiễm kiềm hô hấp: Cơ chế và triệu chứng","youtube_id":"33roUxgvlzM","description":"• **Điểm cốt lõi:** Nhiễm toan chuyển hóa khiến cơ thể phải huy động muối Canxi Phosphat từ xương.\n• **Mục tiêu thực hành:** Trung hòa axit trong máu, là nguyên nhân sâu xa dẫn đến thoái hóa xương và loãng xương.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/33roUxgvlzM/hqdefault.jpg"},{"title":"03. Nước tinh khiết – Tính axit của nước RO và cơ chế nước kiềm","youtube_id":"VclP_6uVw50","description":"• **Điểm cốt lõi:** Nước qua màng RO trơ khoáng có tính axit nhẹ (pH 5.5-6.5).\n• **Ứng dụng thực hành:** Không nên dùng nước trơ khoáng lâu dài mà cần qua lõi tái tạo khoáng kiềm Magie, Canxi sinh học.","duration_text":"18:57","thumbnail_url":"https://i.ytimg.com/vi/VclP_6uVw50/hqdefault.jpg"},{"title":"04. Kiềm sạch vs Kiềm bẩn, Kiềm khoáng tự nhiên vs Kiềm nhân tạo","youtube_id":"cpR-H5tEph8","description":"• **Điểm cốt lõi:** Cảnh giác với nước kiềm đóng chai dùng hóa chất nâng pH nhân tạo.\n• **Ứng dụng thực hành:** Nước ion kiềm tươi chuẩn điện phân giàu ion H+ và OH- tự nhiên mới mang lại hoạt tính sinh học đích thực.","duration_text":"13:36","thumbnail_url":"https://i.ytimg.com/vi/cpR-H5tEph8/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('710b9474-94ca-4a86-af07-1bc501261aaa', 'default', 'b0000000-0000-0000-0000-000000000015', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Điều hòa canxi máu qua PTH, calcitonin và vitamin D","audio_url":null,"youtube_id":"XH27RPoSWS4","description":"• **Điểm cốt lõi:** Uống canxi bắt buộc phải đi kèm Vitamin D3 và K2 (MK-7).\n• **Ứng dụng thực hành:** Nếu thiếu K2, canxi tự do trong máu sẽ lắng đọng vào thành mạch gây xơ vữa và sỏi thận.","duration_text":"8:42","thumbnail_url":"https://i.ytimg.com/vi/XH27RPoSWS4/hqdefault.jpg"},{"title":"02. Cân bằng nội môi canxi và vai trò PTH, vitamin D3","audio_url":null,"youtube_id":"M9GccjpSnN0","description":"• **Điểm cốt lõi:** Kẽm là vi khoáng sinh tử cho hệ miễn dịch và tái tạo niêm mạc ruột.\n• **Ứng dụng thực hành:** Ngậm kẽm khi chớm cảm cúm giúp rút ngắn thời gian mắc bệnh đường hô hấp rõ rệt.","duration_text":"5:00","thumbnail_url":"https://i.ytimg.com/vi/M9GccjpSnN0/hqdefault.jpg"},{"title":"03. Chuyển hóa magie và hậu quả của hạ magie máu","audio_url":null,"youtube_id":"Q4TWnCF8vQY","description":"• **Điểm cốt lõi:** Sắt từ thực vật (sắt không Heme) hấp thu kém.\n• **Ứng dụng thực hành:** Kết hợp với thực phẩm giàu Vitamin C như ớt chuông, cam chanh giúp tăng tỷ lệ hấp thu sắt lên gấp 3-4 lần.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/Q4TWnCF8vQY/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Vitamin tan trong dầu (A, D, E, K) và khoáng vi lượng","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Vitamin nhóm B tham gia vào chu trình Krebs tạo năng lượng ATP.\n• **Ứng dụng thực hành:** Thiếu hụt vitamin B1, B6, B12 khiến cơ thể thường xuyên uể oải, mất tập trung và tê bì tay chân.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('8ba8fefe-de7a-4e76-87eb-0a9bd85ea2f6', 'default', 'b0000000-0000-0000-0007-000000000005', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Bệnh gan nhiễm mỡ không do rượu (NAFLD) và biến chứng xơ gan","audio_url":null,"youtube_id":"ahuwmDmoA0w","description":"• **Điểm cốt lõi:** Gan nhiễm mỡ độ 1 và độ 2 hoàn toàn có thể đảo ngược 100% nếu thay đổi lối sống.\n• **Ứng dụng thực hành:** Gan là cơ quan duy nhất có khả năng tự tái sinh thần kỳ nếu được giải phóng khỏi mỡ thừa.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/ahuwmDmoA0w/hqdefault.jpg"},{"title":"02. Tiến trình xơ hóa gan từ gan nhiễm mỡ: Cơ chế và cách phát hiện","audio_url":null,"youtube_id":"qh0Gcc9I7UM","description":"• **Điểm cốt lõi:** Đường Fructose trong nước ngọt và bánh kẹo là độc chất âm thầm hàng đầu gây gan nhiễm mỡ.\n• **Cơ chế sinh học:** Toàn bộ lượng đường này bị gan biến trực tiếp thành Triglyceride.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/qh0Gcc9I7UM/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Đảo ngược gan nhiễm mỡ độ 1 và độ 2 bằng chế độ ăn","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Men gan bình thường không có nghĩa là gan khỏe mạnh.\n• **Ứng dụng thực hành:** Giai đoạn gan nhiễm mỡ đơn thuần men gan thường không tăng, cần siêu âm hoặc đo độ đàn hồi FibroScan.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Vận động và đốt mỡ nội tạng quanh tế bào gan","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Giảm 7-10% trọng lượng cơ thể bằng cách cắt giảm tinh bột tinh chế và nhịn ăn gián đoạn.\n• **Tác dụng sinh học:** Loại bỏ đáng kể mỡ nội tạng và dập tắt phản ứng viêm tại mô gan.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('552c7f93-00ec-4750-833a-7a291025fe3e', 'default', 'b0000000-0000-0000-0004-000000000006', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ chế trào ngược dạ dày thực quản và biến chứng viêm loét","audio_url":null,"youtube_id":"5_3pbRpu2_I","description":"• **Điểm cốt lõi:** Nhiễm khuẩn HP không phải lúc nào cũng cần uống kháng sinh diệt trừ nếu không có vết loét hoặc tiền sử gia đình ung thư dạ dày.\n• **Ứng dụng thực hành:** Quản trị niêm mạc lành lặn là ưu tiên cốt lõi.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/5_3pbRpu2_I/hqdefault.jpg"},{"title":"02. Thoát vị khe hoành và can thiệp phẫu thuật chống trào ngược","audio_url":null,"youtube_id":"QFyBSmDAhwE","description":"• **Điểm cốt lõi:** Hội chứng ruột kích thích (IBS) gắn liền với căng thẳng tâm lý.\n• **Ứng dụng thực hành:** Giảm stress và áp dụng chế độ ăn Low-FODMAP là biện pháp can thiệp đầu tay mang lại hiệu quả cao.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/QFyBSmDAhwE/hqdefault.jpg"},{"title":"03. Miễn dịch niêm mạc ruột và cơ chế bệnh viêm đại tràng (IBD)","audio_url":null,"youtube_id":"nf0_cUb9XU8","description":"• **Điểm cốt lõi:** Phác đồ phục hồi đường ruột 4R (Remove - Replace - Reinoculate - Repair) là quy trình vàng.\n• **Tác dụng sinh học:** Phục hồi niêm mạc ruột bị viêm loét từ gốc rễ sinh học.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/nf0_cUb9XU8/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Vi khuẩn HP dạ dày và phác đồ chăm sóc niêm mạc","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Trọng tâm cơ chế:** Dấu hiệu báo động đỏ đường tiêu hóa.\n• **Chi tiết sinh học:** Đi ngoài ra máu đen hoặc đỏ tươi, sụt cân nhanh không rõ lý do, sốt kèm đau bụng ban đêm cần phải nội soi tiêu hóa khẩn cấp.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('7bf240cb-292f-43ae-bf93-9624d0bf31b0', 'default', 'b0000000-0000-0000-0000-000000000011', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Dinh dưỡng mục tiêu là gì – Tùng Dinh Dưỡng Wellness","audio_url":null,"youtube_id":"RTIFBf9eHv8","description":"• **Điểm cốt lõi:** Dinh dưỡng mục tiêu tập trung vào chất lượng dưỡng chất nuôi dưỡng tế bào thay.\n• **Cơ chế sinh học:** Chỉ đếm lượng calo thô nạp vào cơ thể.","duration_text":"3:11","thumbnail_url":"https://i.ytimg.com/vi/RTIFBf9eHv8/hqdefault.jpg"},{"title":"02. Cơ chế nhịn ăn gián đoạn và đốt mỡ dự trữ","audio_url":null,"youtube_id":"9ti0nVbqjLo","description":"• **Trọng tâm cơ chế:** Bữa ăn lành mạnh cần cân đối bộ ba đa lượng.\n• **Chi tiết sinh học:** Đạm chất lượng cao, chất béo không bão hòa và tinh bột chuyển hóa chậm giàu chất xơ.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/9ti0nVbqjLo/hqdefault.jpg"},{"title":"03. Top 7 Thực phẩm lên men cho đường ruột khỏe mạnh","audio_url":null,"youtube_id":"e9-INC1uflE","description":"• **Điểm cốt lõi:** Kiểm soát nồng độ hormone Insulin sau ăn là chìa khóa then chốt.\n• **Mục tiêu thực hành:** Ngăn chặn quá trình tích tụ mỡ thừa nội tạng quanh ổ bụng.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/e9-INC1uflE/hqdefault.jpg"},{"title":"04. [Cần bổ sung] 4 Trụ cột dinh dưỡng tế bào tự chữa lành","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Quy tắc đĩa ăn một nửa là rau củ.\n• **Tác dụng sinh học:** Kiểm soát lượng đường huyết ổn định và cung cấp enzyme tự nhiên cho hệ vi sinh đường ruột.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
