values ('cf9c5fdd-8e9f-4483-ad2b-7abc7b54f2c3', 'default', 'b0000000-0000-0000-0008-000000000005', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Tổng quan giải phẫu hệ bạch huyết và vai trò dẫn lưu miễn dịch 3D","audio_url":null,"youtube_id":"1xZ-Xgq31y8","description":"• **Định nghĩa & Bản chất:** Hạch bạch huyết sưng đau ở cổ khi bị viêm họng.\n• **Ý nghĩa chuyên môn:** Dấu hiệu đáng mừng cho thấy đội quân miễn dịch tại hạch đang tập trung đánh bại vi khuẩn xâm nhập.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/1xZ-Xgq31y8/hqdefault.jpg"},{"title":"02. Bể dưỡng chấp và đường dẫn lưu dịch bạch huyết về tĩnh mạch dưới đòn","audio_url":null,"youtube_id":"8EdwowKxeCA","description":"• **Điểm cốt lõi:** Hệ bạch huyết không có quả tim bơm máu.\n• **Ứng dụng thực hành:** Vận động cơ bắp và hít thở sâu bằng cơ hoành là cách duy nhất để tống đẩy dòng dịch bạch huyết lưu thông.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/8EdwowKxeCA/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Mạng lưới hạch an ninh (hạch cổ, hạch nách, hạch bẹn)","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Bể dưỡng chấp ở ổ bụng thu gom toàn bộ chất béo Chylomicron từ ruột non đưa vào ống ngực.\n• **Ứng dụng thực hành:** Ăn chất béo lành mạnh giúp dòng dưỡng chấp lưu thông trơn tru.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Massage dẫn lưu bạch huyết và vận động lưu thông dòng dịch","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Massage dẫn lưu bạch huyết nhẹ nhàng theo chiều hướng về tim.\n• **Tác dụng sinh học:** Giải phóng ứ trệ dịch gian bào, giảm phù chân và tăng tốc đào thải độc tố tế bào.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('70e9f4b8-ad5f-4138-a8da-2403c0795e83', 'default', 'b0000000-0000-0000-0007-000000000001', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Suy gan: Nguyên nhân, cơ chế bệnh sinh và hướng phục hồi","audio_url":null,"youtube_id":"qh0Gcc9I7UM","description":"• **Điểm cốt lõi:** Tĩnh mạch môn đưa toàn bộ dinh dưỡng tan trong nước từ ruột về gan kiểm duyệt.\n• **Ứng dụng thực hành:** Suy giảm chức năng gan làm ứ trệ tuần hoàn cửa, gây trĩ và giãn vỡ tĩnh mạch thực quản.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/qh0Gcc9I7UM/hqdefault.jpg"},{"title":"02. Tuần hoàn ruột gan và quá trình chuyển hóa acid mật","audio_url":null,"youtube_id":"fE1UUaU2f9o","description":"• **Điểm cốt lõi:** Gan là kho dự trữ Glycogen và duy trì đường huyết ổn định cả ngày lẫn đêm.\n• **Ứng dụng thực hành:** Ăn uống thất thường hoặc nhịn đói kéo dài làm cạn kiệt năng lượng dự trữ tại gan.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/fE1UUaU2f9o/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Giải phẫu lá gan và 500 chức năng sinh hóa 3D","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Gan sản xuất 100% Albumin và các yếu tố đông máu.\n• **Ứng dụng thực hành:** Khi gan suy yếu, áp lực keo giảm khiến nước tràn vào ổ bụng (cổ trướng) và dễ bầm tím chảy máu dưới da.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Gan dự trữ Glycogen và điều hòa đường huyết 24/7","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Chu trình Urea tại gan là bức tường bảo vệ não bộ khỏi độc chất Amoniac (NH3).\n• **Ứng dụng thực hành:** Suy gan nặng làm NH3 ngấm vào tế bào thần kinh gây lơ mơ và hôn mê gan.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('a88e8501-9a22-48c1-a6ca-6a0bfe93a1fc', 'default', 'b0000000-0000-0000-0007-000000000002', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ chế chuyển hóa và đào thải độc chất qua dịch mật","audio_url":null,"youtube_id":"fE1UUaU2f9o","description":"• **Điểm cốt lõi:** Giai đoạn 1 của giải độc gan tạo ra các chất trung gian độc hại gấp nhiều lần.\n• **Ứng dụng thực hành:** Bắt buộc phải có đủ chất chống oxy hóa để bảo vệ tế bào gan khỏi bị tổn thương hoại tử.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/fE1UUaU2f9o/hqdefault.jpg"},{"title":"02. [Cần bổ sung] Thải độc gan giai đoạn 1 (Cytochrome P450)","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Giai đoạn 2 liên hợp đòi hỏi nguồn cung cấp axit amin chứa lưu huỳnh và Glutathione dồi dào.\n• **Ứng dụng thực hành:** Thiếu hụt protein chất lượng cao sẽ làm đình trệ toàn bộ quá trình đào thải độc tố.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Thải độc gan giai đoạn 2 (Liên hợp Glutathione/Sulfate)","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Thuốc giảm đau Paracetamol chuyển hóa ở gan tạo chất độc NAPQI làm cạn kiệt nguồn Glutathione.\n• **Ứng dụng thực hành:** Tuyệt đối không dùng quá liều hoặc dùng chung với rượu bia.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Dấu hiệu nhận biết sớm lá gan đang bị quá tải độc chất","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Định nghĩa & Bản chất:** Mề đay, mẩn ngứa ban đêm và mụn nhọt kéo dài.\n• **Ý nghĩa chuyên môn:** Tiếng chuông cảnh báo gan đang quá tải độc tố và dòng dịch mật bài xuất bị ứ trệ.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('6bec44b5-3d9d-4b00-839c-58e288d27631', 'default', 'b0000000-0000-0000-0008-000000000001', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Phản ứng viêm: Đáp ứng miễn dịch đầu tiên và cơ chế bảo vệ mô","audio_url":null,"youtube_id":"e09yx-sXgzU","description":"• **Điểm cốt lõi:** Lớp màng axit tự nhiên trên da (pH 5.5) là tấm khiên vô hình chống vi khuẩn.\n• **Ứng dụng thực hành:** Lạm dụng xà phòng tẩy rửa mạnh làm tróc mất lớp màng bảo vệ sinh học này.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/e09yx-sXgzU/hqdefault.jpg"},{"title":"02. Cơ chế sốt tự nhiên: Phân biệt sốt sinh lý và tăng thân nhiệt nguy hiểm","audio_url":null,"youtube_id":"qnDCM8KZuas","description":"• **Điểm cốt lõi:** Phản ứng viêm là nỗ lực của cơ thể để khoanh vùng và tiêu diệt mầm bệnh.\n• **Ứng dụng thực hành:** Lạm dụng thuốc kháng viêm quá sớm sẽ cản trở quá trình dọn dẹp ổ nhiễm trùng.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/qnDCM8KZuas/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Hàng rào da, niêm mạc và axit dạ dày ngăn vi khuẩn xâm nhập","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Sốt nhẹ (37.8-38.5 độ C) là vũ khí miễn dịch tự nhiên giúp tăng tốc độ di chuyển của bạch cầu.\n• **Ứng dụng thực hành:** Không nên vội vã uống thuốc hạ sốt khi cơ thể vẫn tỉnh táo và đủ nước.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Vi khuẩn thường trú trên da và bảo vệ cửa ngõ cơ thể","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Axit dạ dày tiêu diệt 99% vi sinh vật từ thức ăn.\n• **Ứng dụng thực hành:** Suy giảm độ toan dạ dày do thuốc ức chế axit làm tăng gấp 3 lần nguy cơ nhiễm khuẩn đường ruột.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('d6d0b51f-f6a9-4d74-b34b-d57b08e21b3b', 'default', 'b0000000-0000-0000-0005-000000000002', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Tăng kali máu: Nguyên nhân, sinh lý và tác động lên nhịp tim","youtube_id":"Q-rcaOK_MXs","description":"• **Trọng tâm cơ chế:** Tăng Kali máu trên 5.5 mEq/L là cấp cứu khẩn cấp.\n• **Chi tiết sinh học:** Làm thay đổi điện thế màng cơ tim, tạo sóng T cao nhọn trên điện tâm đồ và có nguy cơ gây ngừng tim đột ngột.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/Q-rcaOK_MXs/hqdefault.jpg"},{"title":"02. Hạ kali máu: Triệu chứng yếu cơ và rối loạn nhịp tim","youtube_id":"dHQJ85r_XQk","description":"• **Điểm cốt lõi:** Hạ Kali máu làm tăng phân cực màng tế bào cơ.\n• **Ứng dụng thực hành:** Dẫn đến yếu liệt cơ tứ chi, chướng bụng giảm nhu động ruột và phát sinh các cơn loạn nhịp tim nguy hiểm.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/dHQJ85r_XQk/hqdefault.jpg"},{"title":"03. Tăng canxi máu: Cơ chế bệnh sinh và triệu chứng lâm sàng","youtube_id":"v2eos3-4W2I","description":"• **Điểm cốt lõi:** Tăng Canxi máu kéo dài kích thích lắng đọng tinh thể Canxi Oxalate tại thận tạo sỏi và vôi hóa mạch máu.\n• **Ứng dụng thực hành:** Đồng thời ức chế dẫn truyền thần kinh cơ gây uể oải, táo bón.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/v2eos3-4W2I/hqdefault.jpg"},{"title":"04. Hạ canxi máu: Co rút cơ (dấu hiệu Chvostek/Trousseau) và điều hòa canxi","youtube_id":"6W_02syNlLw","description":"• **Điểm cốt lõi:** Hạ Canxi máu kích thích thần kinh quá mức gây co giật cơ, tê bì quanh miệng và ngón tay.\n• **Ứng dụng thực hành:** Cần bổ sung kèm Magie và Vitamin D3 để tái hấp thu canxi hiệu quả.","duration_text":"06:00","thumbnail_url":"https://i.ytimg.com/vi/6W_02syNlLw/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('46294f69-48c6-4f6c-8092-6e11dfad4904', 'default', '77f600d0-4fe0-47ec-92c3-682a36505dbb', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Phần 1: Bảo vệ cột sống cổ trong khi ngủ & Tư thế nằm chuẩn","youtube_id":"FigkQuzhi_M","description":"• **Điểm cốt lõi:** Tùng Dinh Dưỡng hướng dẫn tư thế ngủ đúng và tại sao cần giữ đường cong sinh lý cột sống cổ trong giấc ngủ..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"12 phút","thumbnail_url":"https://i.ytimg.com/vi/FigkQuzhi_M/hqdefault.jpg"},{"title":"02. Phần 2: Chọn gối đúng – Bảo vệ cột sống cổ","youtube_id":"WCHp3K6BdfM","description":"• **Điểm cốt lõi:** Tiêu chuẩn chọn gối nâng đỡ đốt sống cổ.\n• **Ứng dụng thực hành:** Tránh gập cổ hoặc ngửa cổ quá mức gây chèn ép rễ thần kinh.","duration_text":"10 phút","thumbnail_url":"https://i.ytimg.com/vi/WCHp3K6BdfM/hqdefault.jpg"},{"title":"03. Rễ cổ C3 C4 C5 & Cơ hoành: Hụt hơi, khó thở, tức ngực","youtube_id":"w0hg_qYPWV4","description":"• **Điểm cốt lõi:** Mối liên hệ giải phẫu giữa rễ thần kinh hoành xuất phát từ C3-C5 với cơ hoành và trào ngược dạ dày thực quản..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"14 phút","thumbnail_url":"https://i.ytimg.com/vi/w0hg_qYPWV4/hqdefault.jpg"},{"title":"04. Cột sống cổ C3 C4 C5 & Khó thở, tức ngực không rõ nguyên nhân","youtube_id":"-PYXqZyXW6I","description":"• **Điểm cốt lõi:** Giải mã tình trạng hụt hơi.\n• **Ứng dụng thực hành:** Hồi hộp, trào ngược kéo dài do sai lệch đốt sống cổ chèn ép thần kinh hoành.","duration_text":"11 phút","thumbnail_url":"https://i.ytimg.com/vi/-PYXqZyXW6I/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('7757642d-9c25-41ea-ac9f-5969d5c02a67', 'default', 'b0000000-0000-0000-0000-000000000012', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ chế dịch mã tổng hợp protein và nuôi dưỡng tế bào","audio_url":null,"youtube_id":"WbMw9BytMu8","description":"• **Điểm cốt lõi:** Cơ bắp cần đạt ngưỡng 2.5-3.0g Leucine trong mỗi bữa ăn (khoảng 120-150g ức gà hoặc cá).\n• **Mục tiêu thực hành:** Kích hoạt quá trình tổng hợp và phục hồi sợi cơ.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/WbMw9BytMu8/hqdefault.jpg"},{"title":"02. [Cần bổ sung] Phân loại đạm thực vật vs đạm động vật","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Người cao tuổi có hiện tượng kháng đồng hóa.\n• **Ứng dụng thực hành:** Cần tăng lượng đạm lên 1.2-1.5g/kg mỗi ngày để chống lại hội chứng teo cơ mất sức (Sarcopenia).","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Nhu cầu Protein chuẩn theo trọng lượng cơ thể","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Trọng tâm cơ chế:** Phối hợp đạm động vật và thực vật theo tỷ lệ 50.\n• **Chi tiết sinh học:** 50 là chiến lược tối ưu giúp vừa đủ axit amin thiết yếu vừa bảo vệ tim mạch và thận.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Tái tạo khối cơ và sụn khớp sau chấn thương","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Ăn thiếu đạm làm suy sụp hệ miễn dịch.\n• **Ứng dụng thực hành:** Rụng tóc, da nhăn nheo và vết thương lâu lành do cơ thể không đủ nguyên liệu tổng hợp kháng thể và collagen.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('639d1ee9-916a-4120-a0fd-ecd9795c48b5', 'default', 'b0000000-0000-0000-0000-000000000014', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cơ chế kháng insulin và tiền đái tháo đường do lối sống","audio_url":null,"youtube_id":"SEnNH2U8LMY","description":"• **Điểm cốt lõi:** Tinh bột chuyển hóa nhanh (GI cao) làm đường huyết tăng vọt.\n• **Ứng dụng thực hành:** Kích thích tụy xả ồ ạt Insulin – hormone chủ đạo khóa chặt kho mỡ và ép cơ thể tích trữ mỡ thừa.","duration_text":"6 phút","thumbnail_url":"https://i.ytimg.com/vi/SEnNH2U8LMY/hqdefault.jpg"},{"title":"02. Thói quen ăn uống xấu khiến bệnh tiểu đường trầm trọng hơn","audio_url":null,"youtube_id":"6DcTT9yJJl0","description":"• **Điểm cốt lõi:** Nấu cơm hoặc khoai rồi để nguội trong tủ mát biến tinh bột thường thành tinh bột kháng RS3.\n• **Ứng dụng thực hành:** Giảm chỉ số đường huyết và nuôi dưỡng hệ lợi khuẩn đại tràng.","duration_text":"2:19","thumbnail_url":"https://i.ytimg.com/vi/6DcTT9yJJl0/hqdefault.jpg"},{"title":"03. [Cần bổ sung] Phân biệt tinh bột nhanh vs tinh bột chuyển hóa chậm (GI)","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Nhịn ăn gián đoạn 16/8 hạ thấp Insulin.\n• **Tác dụng sinh học:** Cơ thể tiếp cận và đốt cháy mỡ nội tạng dự trữ, đồng thời kích hoạt quá trình tự dọn rác tế bào Autophagy.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"},{"title":"04. [Cần bổ sung] Chiến lược kiểm soát cơn thèm đường và hạ đường huyết","audio_url":null,"youtube_id":"dQw4w9WgXcQ","description":"• **Điểm cốt lõi:** Chất xơ hòa tan (Beta-glucan.\n• **Ứng dụng thực hành:** Pectin) tạo lớp gel nhớt làm chậm quá trình hấp thu đường và cholesterol, giữ cho năng lượng luôn tỉnh táo suốt cả ngày.","duration_text":"3:30","thumbnail_url":"https://i.ytimg.com/vi/dQw4w9WgXcQ/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
