values ('adaab3bc-1dc4-49fc-8fde-184c7954b005', 'default', 'e26ae74f-ff55-41e8-b3e5-5c63d87b9870', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Bệnh ĐAU VAI: Nguyên nhân, cơ chế, biểu hiện & Test loại trừ","youtube_id":"ag3FDGmWNak","description":"• **Điểm cốt lõi:** Chẩn đoán phân biệt hội chứng chóp xoay.\n• **Ứng dụng thực hành:** Đông cứng khớp vai và đau vai do thoái hóa đốt sống cổ.","duration_text":"14 phút","thumbnail_url":"https://i.ytimg.com/vi/ag3FDGmWNak/hqdefault.jpg"},{"title":"02. Nguyên nhân đau đầu gối & Cơ chế thoái hóa sụn chêm","youtube_id":"79vItfY90Ns","description":"• **Điểm cốt lõi:** Sai lệch trục chịu lực háng - gối - cổ chân dẫn đến mòn sụn và viêm bao hoạt dịch..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"10 phút","thumbnail_url":"https://i.ytimg.com/vi/79vItfY90Ns/hqdefault.jpg"},{"title":"03. Nguyên nhân đau gót chân (Gai gót & Viêm cân gan chân)","youtube_id":"aZMVEk_GqJM","description":"• **Điểm cốt lõi:** Cơ chế co rút gân gót Achilles và viêm mạc gan chân do mất độ cong vòm bàn chân..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"12 phút","thumbnail_url":"https://i.ytimg.com/vi/aZMVEk_GqJM/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
