values ('8b4a1df5-2b62-4b22-9ccd-25d332de4bc4', 'default', '7fb84afb-b9be-4b4c-bfa7-6b3a488cafdd', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Cột sống & Tim mạch: Tức ngực, hụt hơi, tim đập nhanh, hồi hộp","youtube_id":"qN9e2d6za40","description":"• **Điểm cốt lõi:** Thần kinh giao cảm ngực xuất phát từ T1-T5 điều khiển nhịp tim.\n• **Ứng dụng thực hành:** Khi sai lệch đốt sống ngực sẽ gây loạn nhịp.","duration_text":"15 phút","thumbnail_url":"https://i.ytimg.com/vi/qN9e2d6za40/hqdefault.jpg"},{"title":"02. Rối loạn tiền đình: Nguyên nhân & Mối liên hệ với cột sống cổ","youtube_id":"0drCuLZ7rPU","description":"• **Điểm cốt lõi:** Động mạch đốt sống chui qua các lỗ ngang C1-C6 nuôi tiểu não và ốc tai tiền đình..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"16 phút","thumbnail_url":"https://i.ytimg.com/vi/0drCuLZ7rPU/hqdefault.jpg"},{"title":"03. Suy giãn tĩnh mạch: Cơ chế & Liên quan cột sống thắt lưng","youtube_id":"OkEMCpxse1g","description":"• **Điểm cốt lõi:** Chèn ép đám rối tĩnh mạch chậu và thần kinh chi phối trương lực thành mạch máu chi dưới..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"14 phút","thumbnail_url":"https://i.ytimg.com/vi/OkEMCpxse1g/hqdefault.jpg"},{"title":"04. Bệnh trĩ (Nguyên nhân theo giải phẫu) & Giải pháp phục hồi","youtube_id":"ygOBzrzeinU","description":"• **Điểm cốt lõi:** Ứ trệ tuần hoàn tĩnh mạch trực tràng dưới áp lực ổ bụng và tư thế ngồi sinh hoạt..\n• **Bài học thực hành:** Áp dụng nguyên lý vào thói quen sinh hoạt và chăm sóc sức khỏe chủ động hàng ngày.","duration_text":"12 phút","thumbnail_url":"https://i.ytimg.com/vi/ygOBzrzeinU/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
