insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('78739e0b-1d36-474d-b05c-b9acfe65abd5', 'default', 'b0000000-0000-0000-0005-000000000005', 'videos', 'playlist', 1, true, '{"videos":[{"title":"01. Sự hình thành, luân chuyển và tái hấp thu dịch não tủy 3D","youtube_id":"zMLfSZZfe8U","description":"• **Điểm cốt lõi:** Dịch não tủy luân chuyển 500ml mỗi ngày trong khoang dưới nhện.\n• **Ứng dụng thực hành:** Uống đủ nước là điều kiện bắt buộc để duy trì áp lực nội sọ sinh lý và bảo vệ mô thần kinh mềm.","duration_text":"04:48","thumbnail_url":"https://i.ytimg.com/vi/zMLfSZZfe8U/hqdefault.jpg"},{"title":"02. Tuần hoàn dịch não tủy từ não thất đến khoang dưới nhện","youtube_id":"5zxA3QsoVbM","description":"• **Điểm cốt lõi:** Giấc ngủ sâu từ 23h đến 4h sáng là giai đoạn hệ Glymphatic dùng dịch não tủy dọn dẹp các mảng bám Beta-Amyloid gây thoái hóa thần kinh.\n• **Ứng dụng thực hành:** Mất nước làm đình trệ chu trình này.","duration_text":"01:00","thumbnail_url":"https://i.ytimg.com/vi/5zxA3QsoVbM/hqdefault.jpg"},{"title":"03. Thí nghiệm rửa thực phẩm & Quản trị dinh dưỡng qua dòng nước","youtube_id":"Bo3BfN9ZPr0","description":"• **Điểm cốt lõi:** Ngâm rửa rau củ quả trong nước kiềm giàu hydrogen.\n• **Tác dụng sinh học:** Bẻ gãy các liên kết hóa học của thuốc bảo vệ thực vật gốc dầu, giúp thực phẩm sạch và giữ trọn vi chất.","duration_text":"09:38","thumbnail_url":"https://i.ytimg.com/vi/Bo3BfN9ZPr0/hqdefault.jpg"},{"title":"04. Than hoạt tính và cơ chế lọc hấp phụ tạp chất hữu cơ","youtube_id":"v7WOMYGaV30","description":"• **Điểm cốt lõi:** Lõi lọc than hoạt tính khối đặc (Carbon Block) có khả năng hấp phụ vượt trội so với than hạt.\n• **Ứng dụng thực hành:** Cần thay thế định kỳ để tránh hiện tượng bão hòa nhả ngược độc chất vào nước.","duration_text":"08:02","thumbnail_url":"https://i.ytimg.com/vi/v7WOMYGaV30/hqdefault.jpg"}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('7a763048-a005-48c2-9ee7-5307d96e03cc', 'default', 'b0000000-0000-0000-0007-000000000001', 'text', 'y_nghia', 2, true, '{"text":"### 🏭 Tóm tắt cốt lõi: Gan – Nhà máy sinh hóa 500 chức năng & Tĩnh mạch môn\n- **Cơ quan nội tạng lớn nhất:** Nặng 1.4 – 1.6kg, đảm nhiệm hơn 500 chức năng sinh hóa sống còn. Toàn bộ dòng máu mang chất dinh dưỡng tan trong nước từ ruột non đều theo Tĩnh mạch môn (Portal Vein) đổ thẳng về Gan để lọc và xử lý trước khi vào tuần hoàn chung.\n- **Chức năng điều hòa đường huyết 24/7:** Gan chuyển hóa Glucose dư thừa thành Glycogen dự trữ (khoảng 100g tại gan). Khi nhịn đói hoặc hạ đường huyết, gan phân giải Glycogen thành Glucose phóng thích vào máu; khi cạn kiệt, gan thực hiện Tân tạo đường (Gluconeogenesis) từ axit amin và glycerol.\n- **Tổng hợp Protein & Yếu tố đông máu:** Gan tổng hợp toàn bộ lượng Albumin huyết tương (duy trì áp lực keo chống phù nề) và các yếu tố đông máu thiết yếu (Fibrinogen, Prothrombin). Suy gan dẫn đến phù thũng báng bụng và xuất huyết dưới da.\n- **Chuyển hóa đạm & Chu trình Urea:** Gan thu gom khí Amoniac (NH3) cực độc sinh ra từ quá trình thoái hóa protein, đưa vào Chu trình Urea biến thành hợp chất Urea vô hại để thận đào thải ra nước tiểu. Suy gan làm NH3 tích tụ trong máu tràn lên não gây Bệnh não gan (Hôn mê gan).","lines":["**Cơ quan nội tạng lớn nhất:** Nặng 1.4 – 1.6kg, đảm nhiệm hơn 500 chức năng sinh hóa sống còn. Toàn bộ dòng máu mang chất dinh dưỡng tan trong nước từ ruột non đều theo Tĩnh mạch môn (Portal Vein) đổ thẳng về Gan để lọc và xử lý trước khi vào tuần hoàn chung.","**Chức năng điều hòa đường huyết 24/7:** Gan chuyển hóa Glucose dư thừa thành Glycogen dự trữ (khoảng 100g tại gan). Khi nhịn đói hoặc hạ đường huyết, gan phân giải Glycogen thành Glucose phóng thích vào máu; khi cạn kiệt, gan thực hiện Tân tạo đường (Gluconeogenesis) từ axit amin và glycerol.","**Tổng hợp Protein & Yếu tố đông máu:** Gan tổng hợp toàn bộ lượng Albumin huyết tương (duy trì áp lực keo chống phù nề) và các yếu tố đông máu thiết yếu (Fibrinogen, Prothrombin). Suy gan dẫn đến phù thũng báng bụng và xuất huyết dưới da.","**Chuyển hóa đạm & Chu trình Urea:** Gan thu gom khí Amoniac (NH3) cực độc sinh ra từ quá trình thoái hóa protein, đưa vào Chu trình Urea biến thành hợp chất Urea vô hại để thận đào thải ra nước tiểu. Suy gan làm NH3 tích tụ trong máu tràn lên não gây Bệnh não gan (Hôn mê gan)."],"title":"🏭 Tóm tắt cốt lõi: Gan – Nhà máy sinh hóa 500 chức năng & Tĩnh mạch môn","format":"bullet","content":"### 🏭 Tóm tắt cốt lõi: Gan – Nhà máy sinh hóa 500 chức năng & Tĩnh mạch môn\n- **Cơ quan nội tạng lớn nhất:** Nặng 1.4 – 1.6kg, đảm nhiệm hơn 500 chức năng sinh hóa sống còn. Toàn bộ dòng máu mang chất dinh dưỡng tan trong nước từ ruột non đều theo Tĩnh mạch môn (Portal Vein) đổ thẳng về Gan để lọc và xử lý trước khi vào tuần hoàn chung.\n- **Chức năng điều hòa đường huyết 24/7:** Gan chuyển hóa Glucose dư thừa thành Glycogen dự trữ (khoảng 100g tại gan). Khi nhịn đói hoặc hạ đường huyết, gan phân giải Glycogen thành Glucose phóng thích vào máu; khi cạn kiệt, gan thực hiện Tân tạo đường (Gluconeogenesis) từ axit amin và glycerol.\n- **Tổng hợp Protein & Yếu tố đông máu:** Gan tổng hợp toàn bộ lượng Albumin huyết tương (duy trì áp lực keo chống phù nề) và các yếu tố đông máu thiết yếu (Fibrinogen, Prothrombin). Suy gan dẫn đến phù thũng báng bụng và xuất huyết dưới da.\n- **Chuyển hóa đạm & Chu trình Urea:** Gan thu gom khí Amoniac (NH3) cực độc sinh ra từ quá trình thoái hóa protein, đưa vào Chu trình Urea biến thành hợp chất Urea vô hại để thận đào thải ra nước tiểu. Suy gan làm NH3 tích tụ trong máu tràn lên não gây Bệnh não gan (Hôn mê gan)."}'::jsonb)
