insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('f6e0a9c5-ecf4-4dae-8ee6-8515ac038b5f', 'default', 'b0000000-0000-0000-0007-000000000002', 'text', 'y_nghia', 2, true, '{"text":"### 🧪 Tóm tắt cốt lõi: Hai giai đoạn giải độc gan (Phase 1 & Phase 2 Detoxification)\n- **Bản chất của giải độc gan:** Hầu hết các độc chất (thuốc tây, rượu bia, thuốc trừ sâu, phụ gia thực phẩm) là hợp chất tan trong chất béo (Lipophilic), khó đào thải. Gan phải chuyển hóa chúng thành dạng tan trong nước (Hydrophilic) để tống ra ngoài qua nước tiểu (thận) hoặc dịch mật (phân).\n- **Giai đoạn 1 (Phase 1 - Biến đổi sinh học):**\n  - Thực hiện bởi họ enzyme **Cytochrome P450**.\n  - Sử dụng các phản ứng oxy hóa, khử, thủy phân để tạo nhóm chức phân cực.\n  - *Lưu ý quan trọng:* Sản phẩm trung gian của Giai đoạn 1 thường **độc hại và có tính oxy hóa mạnh gấp nhiều lần** chất ban đầu. Nếu Giai đoạn 2 bị tắc nghẽn, các gốc tự do này sẽ phá hủy màng tế bào gan.\n- **Giai đoạn 2 (Phase 2 - Phản ứng liên hợp):**\n  - Gắn các gốc sinh học hòa tan vào chất trung gian qua 6 con đường: Liên hợp Glutathione, Liên hợp Sulfate, Liên hợp Glycine, Glucuronidation, Methyl hóa và Acetyl hóa.\n  - Đòi hỏi nguồn cung cấp liên tục các axit amin chứa lưu huỳnh (Cysteine, Methionine), Glutathione, Vitamin nhóm B, Selen và Kẽm.\n- **Dấu hiệu gan quá tải độc chất:** Mề đay mẩn ngứa, hơi thở hôi, vàng da, mệt mỏi mạn tính, nước tiểu sẫm màu và khó tiêu chất béo.","lines":["**Bản chất của giải độc gan:** Hầu hết các độc chất (thuốc tây, rượu bia, thuốc trừ sâu, phụ gia thực phẩm) là hợp chất tan trong chất béo (Lipophilic), khó đào thải. Gan phải chuyển hóa chúng thành dạng tan trong nước (Hydrophilic) để tống ra ngoài qua nước tiểu (thận) hoặc dịch mật (phân).","**Giai đoạn 1 (Phase 1 - Biến đổi sinh học):**","Thực hiện bởi họ enzyme **Cytochrome P450**.","Sử dụng các phản ứng oxy hóa, khử, thủy phân để tạo nhóm chức phân cực.","*Lưu ý quan trọng:* Sản phẩm trung gian của Giai đoạn 1 thường **độc hại và có tính oxy hóa mạnh gấp nhiều lần** chất ban đầu. Nếu Giai đoạn 2 bị tắc nghẽn, các gốc tự do này sẽ phá hủy màng tế bào gan.","**Giai đoạn 2 (Phase 2 - Phản ứng liên hợp):**","Gắn các gốc sinh học hòa tan vào chất trung gian qua 6 con đường: Liên hợp Glutathione, Liên hợp Sulfate, Liên hợp Glycine, Glucuronidation, Methyl hóa và Acetyl hóa.","Đòi hỏi nguồn cung cấp liên tục các axit amin chứa lưu huỳnh (Cysteine, Methionine), Glutathione, Vitamin nhóm B, Selen và Kẽm.","**Dấu hiệu gan quá tải độc chất:** Mề đay mẩn ngứa, hơi thở hôi, vàng da, mệt mỏi mạn tính, nước tiểu sẫm màu và khó tiêu chất béo."],"title":"🧪 Tóm tắt cốt lõi: Hai giai đoạn giải độc gan (Phase 1 & Phase 2 Detoxification)","format":"bullet","content":"### 🧪 Tóm tắt cốt lõi: Hai giai đoạn giải độc gan (Phase 1 & Phase 2 Detoxification)\n- **Bản chất của giải độc gan:** Hầu hết các độc chất (thuốc tây, rượu bia, thuốc trừ sâu, phụ gia thực phẩm) là hợp chất tan trong chất béo (Lipophilic), khó đào thải. Gan phải chuyển hóa chúng thành dạng tan trong nước (Hydrophilic) để tống ra ngoài qua nước tiểu (thận) hoặc dịch mật (phân).\n- **Giai đoạn 1 (Phase 1 - Biến đổi sinh học):**\n  - Thực hiện bởi họ enzyme **Cytochrome P450**.\n  - Sử dụng các phản ứng oxy hóa, khử, thủy phân để tạo nhóm chức phân cực.\n  - *Lưu ý quan trọng:* Sản phẩm trung gian của Giai đoạn 1 thường **độc hại và có tính oxy hóa mạnh gấp nhiều lần** chất ban đầu. Nếu Giai đoạn 2 bị tắc nghẽn, các gốc tự do này sẽ phá hủy màng tế bào gan.\n- **Giai đoạn 2 (Phase 2 - Phản ứng liên hợp):**\n  - Gắn các gốc sinh học hòa tan vào chất trung gian qua 6 con đường: Liên hợp Glutathione, Liên hợp Sulfate, Liên hợp Glycine, Glucuronidation, Methyl hóa và Acetyl hóa.\n  - Đòi hỏi nguồn cung cấp liên tục các axit amin chứa lưu huỳnh (Cysteine, Methionine), Glutathione, Vitamin nhóm B, Selen và Kẽm.\n- **Dấu hiệu gan quá tải độc chất:** Mề đay mẩn ngứa, hơi thở hôi, vàng da, mệt mỏi mạn tính, nước tiểu sẫm màu và khó tiêu chất béo."}'::jsonb)
