values ('d4503df9-b5d2-4174-8455-b3576fd16367', 'default', 'b0000000-0000-0000-0000-000000000001', 'text', 'y_nghia', 2, true, '{"text":"### 🦴 Tóm tắt cốt lõi: Giải phẫu hệ thống Cột sống & Đường cong chữ S sinh học\n- **Cấu trúc trục chịu lực trung tâm:** Cột sống gồm 33–34 đốt sống chia làm 5 đoạn: 7 đốt sống cổ (C1–C7, nâng đỡ hộp sọ 5kg và linh hoạt nhất), 12 đốt sống ngực (T1–T12 gắn với xương sườn tạo lồng ngực), 5 đốt sống thắt lưng (L1–L5 to dày chịu lực nén tối đa), 5 đốt cùng dính liền (S1–S5) và 3–5 đốt cụt.\n- **Ý nghĩa cơ học của đường cong chữ S:** Nhìn nghiêng có 4 đoạn cong sinh lý: ưỡn cổ (20–40°), gù ngực (20–40°), ưỡn thắt lưng (30–50°), cong cùng cụt. Theo công thức Euler $R = N^2 + 1$ (với $N=3$ đoạn cong động), cột sống tăng sức chịu lực nén gấp **10 lần** so với một thanh thẳng đứng.\n- **Hệ quả của mất đường cong sinh lý:** Tật gù lưng, cổ rùa hoặc lưng phẳng làm mất cơ chế giảm chấn tự nhiên. Trọng lực dồn trực tiếp 100% lên các đĩa đệm và diện khớp liên mấu, đẩy nhanh tốc độ thoái hóa sụn khớp lên 300–500%.\n- **Cấu tạo giải phẫu từng đốt sống:** Thân đốt phía trước chịu lực nén; cung đốt sống phía sau bao bọc lỗ đốt sống tạo thành ống tủy bảo vệ tủy sống; các cuống, mỏm gai, mỏm ngang là nơi bám của hệ thống dây chằng và cơ dựng sống.","lines":["**Cấu trúc trục chịu lực trung tâm:** Cột sống gồm 33–34 đốt sống chia làm 5 đoạn: 7 đốt sống cổ (C1–C7, nâng đỡ hộp sọ 5kg và linh hoạt nhất), 12 đốt sống ngực (T1–T12 gắn với xương sườn tạo lồng ngực), 5 đốt sống thắt lưng (L1–L5 to dày chịu lực nén tối đa), 5 đốt cùng dính liền (S1–S5) và 3–5 đốt cụt.","**Ý nghĩa cơ học của đường cong chữ S:** Nhìn nghiêng có 4 đoạn cong sinh lý: ưỡn cổ (20–40°), gù ngực (20–40°), ưỡn thắt lưng (30–50°), cong cùng cụt. Theo công thức Euler $R = N^2 + 1$ (với $N=3$ đoạn cong động), cột sống tăng sức chịu lực nén gấp **10 lần** so với một thanh thẳng đứng.","**Hệ quả của mất đường cong sinh lý:** Tật gù lưng, cổ rùa hoặc lưng phẳng làm mất cơ chế giảm chấn tự nhiên. Trọng lực dồn trực tiếp 100% lên các đĩa đệm và diện khớp liên mấu, đẩy nhanh tốc độ thoái hóa sụn khớp lên 300–500%.","**Cấu tạo giải phẫu từng đốt sống:** Thân đốt phía trước chịu lực nén; cung đốt sống phía sau bao bọc lỗ đốt sống tạo thành ống tủy bảo vệ tủy sống; các cuống, mỏm gai, mỏm ngang là nơi bám của hệ thống dây chằng và cơ dựng sống."],"title":"🦴 Tóm tắt cốt lõi: Giải phẫu hệ thống Cột sống & Đường cong chữ S sinh học","format":"bullet","content":"### 🦴 Tóm tắt cốt lõi: Giải phẫu hệ thống Cột sống & Đường cong chữ S sinh học\n- **Cấu trúc trục chịu lực trung tâm:** Cột sống gồm 33–34 đốt sống chia làm 5 đoạn: 7 đốt sống cổ (C1–C7, nâng đỡ hộp sọ 5kg và linh hoạt nhất), 12 đốt sống ngực (T1–T12 gắn với xương sườn tạo lồng ngực), 5 đốt sống thắt lưng (L1–L5 to dày chịu lực nén tối đa), 5 đốt cùng dính liền (S1–S5) và 3–5 đốt cụt.\n- **Ý nghĩa cơ học của đường cong chữ S:** Nhìn nghiêng có 4 đoạn cong sinh lý: ưỡn cổ (20–40°), gù ngực (20–40°), ưỡn thắt lưng (30–50°), cong cùng cụt. Theo công thức Euler $R = N^2 + 1$ (với $N=3$ đoạn cong động), cột sống tăng sức chịu lực nén gấp **10 lần** so với một thanh thẳng đứng.\n- **Hệ quả của mất đường cong sinh lý:** Tật gù lưng, cổ rùa hoặc lưng phẳng làm mất cơ chế giảm chấn tự nhiên. Trọng lực dồn trực tiếp 100% lên các đĩa đệm và diện khớp liên mấu, đẩy nhanh tốc độ thoái hóa sụn khớp lên 300–500%.\n- **Cấu tạo giải phẫu từng đốt sống:** Thân đốt phía trước chịu lực nén; cung đốt sống phía sau bao bọc lỗ đốt sống tạo thành ống tủy bảo vệ tủy sống; các cuống, mỏm gai, mỏm ngang là nơi bám của hệ thống dây chằng và cơ dựng sống."}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('fd9e83b0-804f-4c09-8e54-cb5857db2933', 'default', '091a43c0-b763-434a-9f73-f3c1ab1552cd', 'text', 'y_nghia', 2, true, '{"lines":["**Cơ chế rách bao xơ và thoát nhân nhầy**: Đĩa đệm cấu tạo gồm vòng sợi xơ (annulus fibrosus) bao bọc nhân nhầy (nucleus pulposus). Dưới áp lực cơ học dồn nén sai trục kết hợp thoái hóa mất nước, các sợi collagen vòng bao ngoài bị nứt rách, khiến nhân nhầy thoát ra sau hoặc sang bên, chèn ép bao màng cứng, rễ thần kinh hoặc tủy sống.","**Tại sao có người đau ít, người đau nhiều?**: Mức độ đau không hoàn toàn tỷ lệ thuận với kích thước khối thoát vị trên phim MRI mà phụ thuộc vào: 1) Mức độ đáp ứng viêm hóa học xung quanh rễ thần kinh; 2) Ngưỡng kích thích của hệ thần kinh giao cảm; 3) Độ rộng của ống sống bẩm sinh. Nhiều trường hợp xẹp nặng nhưng ít viêm lại đau ít hơn khối thoát vị cấp tính gây phù nề rễ thần kinh.","**3 Trụ cột hồi phục xương khớp bền vững**: 1. Giải áp cơ học: Đưa đốt sống về lại đường cong sinh lý tự nhiên, mở rộng lỗ liên hợp để rễ thần kinh được giải thoát.\n2. Dinh dưỡng tế bào: Cung cấp đầy đủ nguyên liệu tái tạo đĩa đệm và sụn khớp (nước, collagen tuýp II, chondroitin, glucosamine và khoáng chất).\n3. Tăng cường khối cơ lõi (Core muscles): Xây dựng hệ thống cơ dựng sống và cơ bụng khỏe để chịu lực thay cho cột sống."],"title":"Tóm tắt cốt lõi & Nguyên lý sinh học","format":"bullet","content":"### 1. Cơ chế rách bao xơ và thoát nhân nhầy\n\nĐĩa đệm cấu tạo gồm vòng sợi xơ (annulus fibrosus) bao bọc nhân nhầy (nucleus pulposus). Dưới áp lực cơ học dồn nén sai trục kết hợp thoái hóa mất nước, các sợi collagen vòng bao ngoài bị nứt rách, khiến nhân nhầy thoát ra sau hoặc sang bên, chèn ép bao màng cứng, rễ thần kinh hoặc tủy sống.\n\n---\n\n### 2. Tại sao có người đau ít, người đau nhiều?\n\nMức độ đau không hoàn toàn tỷ lệ thuận với kích thước khối thoát vị trên phim MRI mà phụ thuộc vào: 1) Mức độ đáp ứng viêm hóa học xung quanh rễ thần kinh; 2) Ngưỡng kích thích của hệ thần kinh giao cảm; 3) Độ rộng của ống sống bẩm sinh. Nhiều trường hợp xẹp nặng nhưng ít viêm lại đau ít hơn khối thoát vị cấp tính gây phù nề rễ thần kinh.\n\n---\n\n### 3. 3 Trụ cột hồi phục xương khớp bền vững\n\n1. Giải áp cơ học: Đưa đốt sống về lại đường cong sinh lý tự nhiên, mở rộng lỗ liên hợp để rễ thần kinh được giải thoát.\n2. Dinh dưỡng tế bào: Cung cấp đầy đủ nguyên liệu tái tạo đĩa đệm và sụn khớp (nước, collagen tuýp II, chondroitin, glucosamine và khoáng chất).\n3. Tăng cường khối cơ lõi (Core muscles): Xây dựng hệ thống cơ dựng sống và cơ bụng khỏe để chịu lực thay cho cột sống.","takeaways":[{"title":"Cơ chế rách bao xơ và thoát nhân nhầy","content":"Đĩa đệm cấu tạo gồm vòng sợi xơ (annulus fibrosus) bao bọc nhân nhầy (nucleus pulposus). Dưới áp lực cơ học dồn nén sai trục kết hợp thoái hóa mất nước, các sợi collagen vòng bao ngoài bị nứt rách, khiến nhân nhầy thoát ra sau hoặc sang bên, chèn ép bao màng cứng, rễ thần kinh hoặc tủy sống."},{"title":"Tại sao có người đau ít, người đau nhiều?","content":"Mức độ đau không hoàn toàn tỷ lệ thuận với kích thước khối thoát vị trên phim MRI mà phụ thuộc vào: 1) Mức độ đáp ứng viêm hóa học xung quanh rễ thần kinh; 2) Ngưỡng kích thích của hệ thần kinh giao cảm; 3) Độ rộng của ống sống bẩm sinh. Nhiều trường hợp xẹp nặng nhưng ít viêm lại đau ít hơn khối thoát vị cấp tính gây phù nề rễ thần kinh."},{"title":"3 Trụ cột hồi phục xương khớp bền vững","content":"1. Giải áp cơ học: Đưa đốt sống về lại đường cong sinh lý tự nhiên, mở rộng lỗ liên hợp để rễ thần kinh được giải thoát.\n2. Dinh dưỡng tế bào: Cung cấp đầy đủ nguyên liệu tái tạo đĩa đệm và sụn khớp (nước, collagen tuýp II, chondroitin, glucosamine và khoáng chất).\n3. Tăng cường khối cơ lõi (Core muscles): Xây dựng hệ thống cơ dựng sống và cơ bụng khỏe để chịu lực thay cho cột sống."}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('144011e1-bd94-4740-be98-7b4847328e2c', 'default', 'b0000000-0000-0000-0000-000000000002', 'text', 'y_nghia', 2, true, '{"text":"### 💿 Tóm tắt cốt lõi: Phức hợp Đĩa đệm & Cơ chế dinh dưỡng thẩm thấu\n- **Cấu tạo 3 thành phần của đĩa đệm:**\n  1. *Nhân nhầy (Nucleus Pulposus):* Dạng gel Mucopolysaccharide, Proteoglycan và 80–88% là nước, hoạt động như đệm thủy lực phân phối đều lực nén theo định luật Pascal.\n  2. *Vòng sợi (Anulus Fibrosus):* 15–20 lớp sợi Collagen Type I & II xếp đan chéo góc 30–60°. Vùng sau - bên mỏng và ít lớp hơn, tạo điểm yếu sinh học dễ bị xé rách gây thoát vị.\n  3. *Mâm sụn đốt sống (Endplate):* Sụn hyaline dày ~1mm bao phủ mặt trên và dưới thân đốt sống.\n- **Cơ chế dinh dưỡng thẩm thấu khuếch tán:** Đĩa đệm của người trưởng thành **hoàn toàn không có mạch máu nuôi dưỡng trực tiếp**. Đĩa đệm chỉ nhận oxy, glucose và nước thông qua cơ chế bơm - hút thẩm thấu khi cơ thể vận động nén - nhả nhịp nhàng.\n- **Áp lực nội đĩa đệm theo tư thế (Nghiên cứu Nachemson):** Nằm ngửa = 25kg (25%); Đứng thẳng = 100kg (100%); Ngồi thẳng lưng = 140kg (140%); Ngồi gù lưng cúi người = 185kg (185%); Cúi gập lưng nâng vật nặng = 275kg (275%).\n- **4 Giai đoạn bệnh lý đĩa đệm:** Phồng lồi đĩa đệm (Degeneration/Bulging) -> Rách vòng sợi (Torn anulus) -> Thoát vị thực thụ chèn rễ (Extrusion) -> Mảnh rời đĩa đệm rơi vào ống sống (Sequestration).","lines":["**Cấu tạo 3 thành phần của đĩa đệm:**","*Nhân nhầy (Nucleus Pulposus):* Dạng gel Mucopolysaccharide, Proteoglycan và 80–88% là nước, hoạt động như đệm thủy lực phân phối đều lực nén theo định luật Pascal.","*Vòng sợi (Anulus Fibrosus):* 15–20 lớp sợi Collagen Type I & II xếp đan chéo góc 30–60°. Vùng sau - bên mỏng và ít lớp hơn, tạo điểm yếu sinh học dễ bị xé rách gây thoát vị.","*Mâm sụn đốt sống (Endplate):* Sụn hyaline dày ~1mm bao phủ mặt trên và dưới thân đốt sống.","**Cơ chế dinh dưỡng thẩm thấu khuếch tán:** Đĩa đệm của người trưởng thành **hoàn toàn không có mạch máu nuôi dưỡng trực tiếp**. Đĩa đệm chỉ nhận oxy, glucose và nước thông qua cơ chế bơm - hút thẩm thấu khi cơ thể vận động nén - nhả nhịp nhàng.","**Áp lực nội đĩa đệm theo tư thế (Nghiên cứu Nachemson):** Nằm ngửa = 25kg (25%); Đứng thẳng = 100kg (100%); Ngồi thẳng lưng = 140kg (140%); Ngồi gù lưng cúi người = 185kg (185%); Cúi gập lưng nâng vật nặng = 275kg (275%).","**4 Giai đoạn bệnh lý đĩa đệm:** Phồng lồi đĩa đệm (Degeneration/Bulging) -> Rách vòng sợi (Torn anulus) -> Thoát vị thực thụ chèn rễ (Extrusion) -> Mảnh rời đĩa đệm rơi vào ống sống (Sequestration)."],"title":"💿 Tóm tắt cốt lõi: Phức hợp Đĩa đệm & Cơ chế dinh dưỡng thẩm thấu","format":"bullet","content":"### 💿 Tóm tắt cốt lõi: Phức hợp Đĩa đệm & Cơ chế dinh dưỡng thẩm thấu\n- **Cấu tạo 3 thành phần của đĩa đệm:**\n  1. *Nhân nhầy (Nucleus Pulposus):* Dạng gel Mucopolysaccharide, Proteoglycan và 80–88% là nước, hoạt động như đệm thủy lực phân phối đều lực nén theo định luật Pascal.\n  2. *Vòng sợi (Anulus Fibrosus):* 15–20 lớp sợi Collagen Type I & II xếp đan chéo góc 30–60°. Vùng sau - bên mỏng và ít lớp hơn, tạo điểm yếu sinh học dễ bị xé rách gây thoát vị.\n  3. *Mâm sụn đốt sống (Endplate):* Sụn hyaline dày ~1mm bao phủ mặt trên và dưới thân đốt sống.\n- **Cơ chế dinh dưỡng thẩm thấu khuếch tán:** Đĩa đệm của người trưởng thành **hoàn toàn không có mạch máu nuôi dưỡng trực tiếp**. Đĩa đệm chỉ nhận oxy, glucose và nước thông qua cơ chế bơm - hút thẩm thấu khi cơ thể vận động nén - nhả nhịp nhàng.\n- **Áp lực nội đĩa đệm theo tư thế (Nghiên cứu Nachemson):** Nằm ngửa = 25kg (25%); Đứng thẳng = 100kg (100%); Ngồi thẳng lưng = 140kg (140%); Ngồi gù lưng cúi người = 185kg (185%); Cúi gập lưng nâng vật nặng = 275kg (275%).\n- **4 Giai đoạn bệnh lý đĩa đệm:** Phồng lồi đĩa đệm (Degeneration/Bulging) -> Rách vòng sợi (Torn anulus) -> Thoát vị thực thụ chèn rễ (Extrusion) -> Mảnh rời đĩa đệm rơi vào ống sống (Sequestration)."}'::jsonb)
