insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('eeabb00a-abf1-427c-a0e4-9f7df4359647', 'default', 'b0000000-0000-0000-0000-000000000023', 'text', 'y_nghia', 2, true, '{"text":"### ❤️ Tóm tắt cốt lõi: Trái tim & Mạng lưới tuần hoàn máu nuôi cơ thể\n- **Cấu trúc 4 buồng & Van tim một chiều:** Tim gồm 2 tâm nhĩ (nhận máu) và 2 tâm thất (bơm máu), ngăn cách bởi 4 van tim: van 2 lá, 3 lá, van động mạch chủ và van động mạch phổi. Tiếng tim đập $T_1, T_2$ chính là âm thanh đóng kín dứt khoát của các van tim.\n- **Hai vòng tuần hoàn lớn nhỏ:**\n  - *Tiểu tuần hoàn (Phổi):* Thất phải bơm máu nghèo oxy lên phổi trao đổi khí, máu đỏ tươi giàu oxy trở về nhĩ trái.\n  - *Đại tuần hoàn (Hệ thống):* Thất trái với lớp cơ dày khỏe bơm máu áp lực cao vào động mạch chủ đi khắp các mô tế bào toàn thân.\n- **Điều hòa huyết áp bằng Thụ thể áp lực (Baroreceptors):** Các cảm biến áp suất tại xoang cảnh và quai động mạch chủ liên tục gửi tín hiệu về hành não để điều chỉnh nhịp tim và giãn/co mạch tức thì khi ta thay đổi tư thế từ nằm sang đứng.\n- **Suy giãn tĩnh mạch chi dưới:** Máu từ chân trở về tim phải thắng trọng lực nhờ van tĩnh mạch một chiều và sự co bóp của cơ bắp chân (\"trái tim thứ hai\"). Đứng lâu, ngồi nhiều làm van tĩnh mạch bị thoái hóa hở rộng, máu ứ trệ gây phù chân, nặng chân và nổi gân xanh ngoằn ngoèo.","lines":["**Cấu trúc 4 buồng & Van tim một chiều:** Tim gồm 2 tâm nhĩ (nhận máu) và 2 tâm thất (bơm máu), ngăn cách bởi 4 van tim: van 2 lá, 3 lá, van động mạch chủ và van động mạch phổi. Tiếng tim đập $T_1, T_2$ chính là âm thanh đóng kín dứt khoát của các van tim.","**Hai vòng tuần hoàn lớn nhỏ:**","*Tiểu tuần hoàn (Phổi):* Thất phải bơm máu nghèo oxy lên phổi trao đổi khí, máu đỏ tươi giàu oxy trở về nhĩ trái.","*Đại tuần hoàn (Hệ thống):* Thất trái với lớp cơ dày khỏe bơm máu áp lực cao vào động mạch chủ đi khắp các mô tế bào toàn thân.","**Điều hòa huyết áp bằng Thụ thể áp lực (Baroreceptors):** Các cảm biến áp suất tại xoang cảnh và quai động mạch chủ liên tục gửi tín hiệu về hành não để điều chỉnh nhịp tim và giãn/co mạch tức thì khi ta thay đổi tư thế từ nằm sang đứng.","**Suy giãn tĩnh mạch chi dưới:** Máu từ chân trở về tim phải thắng trọng lực nhờ van tĩnh mạch một chiều và sự co bóp của cơ bắp chân (\"trái tim thứ hai\"). Đứng lâu, ngồi nhiều làm van tĩnh mạch bị thoái hóa hở rộng, máu ứ trệ gây phù chân, nặng chân và nổi gân xanh ngoằn ngoèo."],"title":"❤️ Tóm tắt cốt lõi: Trái tim & Mạng lưới tuần hoàn máu nuôi cơ thể","format":"bullet","content":"### ❤️ Tóm tắt cốt lõi: Trái tim & Mạng lưới tuần hoàn máu nuôi cơ thể\n- **Cấu trúc 4 buồng & Van tim một chiều:** Tim gồm 2 tâm nhĩ (nhận máu) và 2 tâm thất (bơm máu), ngăn cách bởi 4 van tim: van 2 lá, 3 lá, van động mạch chủ và van động mạch phổi. Tiếng tim đập $T_1, T_2$ chính là âm thanh đóng kín dứt khoát của các van tim.\n- **Hai vòng tuần hoàn lớn nhỏ:**\n  - *Tiểu tuần hoàn (Phổi):* Thất phải bơm máu nghèo oxy lên phổi trao đổi khí, máu đỏ tươi giàu oxy trở về nhĩ trái.\n  - *Đại tuần hoàn (Hệ thống):* Thất trái với lớp cơ dày khỏe bơm máu áp lực cao vào động mạch chủ đi khắp các mô tế bào toàn thân.\n- **Điều hòa huyết áp bằng Thụ thể áp lực (Baroreceptors):** Các cảm biến áp suất tại xoang cảnh và quai động mạch chủ liên tục gửi tín hiệu về hành não để điều chỉnh nhịp tim và giãn/co mạch tức thì khi ta thay đổi tư thế từ nằm sang đứng.\n- **Suy giãn tĩnh mạch chi dưới:** Máu từ chân trở về tim phải thắng trọng lực nhờ van tĩnh mạch một chiều và sự co bóp của cơ bắp chân (\"trái tim thứ hai\"). Đứng lâu, ngồi nhiều làm van tĩnh mạch bị thoái hóa hở rộng, máu ứ trệ gây phù chân, nặng chân và nổi gân xanh ngoằn ngoèo."}'::jsonb)
