insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('c20e6f84-712a-412b-bb7c-bf4cb76aaeaa', 'default', 'fc1910eb-c846-40bc-9616-55f1c9dea833', 'text', 'y_nghia', 2, true, '{"lines":["**Nghịch lý bổ sung Canxi: Uống vào có vào xương không?**: Canxi tự do đưa vào đường tiêu hóa nếu thiếu các yếu tố đồng vận chuyển (Vitamin D3 kích hoạt hấp thu ở ruột non, Vitamin K2 định hướng gắn canxi vào mô xương) sẽ bị đào thải qua thận gây sỏi hoặc lắng đọng ở thành mạch máu gây xơ vữa và vôi hóa dây chằng quanh cột sống.","**Vai trò thiết yếu của Magie và Kẽm**: Magie kích hoạt hormone calcitonin đưa canxi vào xương và ức chế hormone cận giáp (PTH) - hormone rút canxi từ xương ra máu. Kẽm là đồng yếu tố enzyme tham gia trực tiếp tổng hợp khung collagen nền của xương. Thiếu magie và kẽm thì dù uống bao nhiêu canxi xương vẫn xốp và giòn.","**Cơ chế dinh dưỡng thẩm thấu của đĩa đệm**: Sau 20 tuổi, đĩa đệm không còn mạch máu trực tiếp nuôi dưỡng mà nhận dinh dưỡng hoàn toàn qua cơ chế thẩm thấu khuếch tán từ mâm sụn đốt sống (vertebral endplate). Do đó, việc vận động đúng biên độ và uống đủ nước giàu khoáng chất là điều kiện tiên quyết để ép dinh dưỡng thẩm thấu vào nuôi nhân nhầy."],"title":"Tóm tắt cốt lõi & Nguyên lý sinh học","format":"bullet","content":"### 1. Nghịch lý bổ sung Canxi: Uống vào có vào xương không?\n\nCanxi tự do đưa vào đường tiêu hóa nếu thiếu các yếu tố đồng vận chuyển (Vitamin D3 kích hoạt hấp thu ở ruột non, Vitamin K2 định hướng gắn canxi vào mô xương) sẽ bị đào thải qua thận gây sỏi hoặc lắng đọng ở thành mạch máu gây xơ vữa và vôi hóa dây chằng quanh cột sống.\n\n---\n\n### 2. Vai trò thiết yếu của Magie và Kẽm\n\nMagie kích hoạt hormone calcitonin đưa canxi vào xương và ức chế hormone cận giáp (PTH) - hormone rút canxi từ xương ra máu. Kẽm là đồng yếu tố enzyme tham gia trực tiếp tổng hợp khung collagen nền của xương. Thiếu magie và kẽm thì dù uống bao nhiêu canxi xương vẫn xốp và giòn.\n\n---\n\n### 3. Cơ chế dinh dưỡng thẩm thấu của đĩa đệm\n\nSau 20 tuổi, đĩa đệm không còn mạch máu trực tiếp nuôi dưỡng mà nhận dinh dưỡng hoàn toàn qua cơ chế thẩm thấu khuếch tán từ mâm sụn đốt sống (vertebral endplate). Do đó, việc vận động đúng biên độ và uống đủ nước giàu khoáng chất là điều kiện tiên quyết để ép dinh dưỡng thẩm thấu vào nuôi nhân nhầy.","takeaways":[{"title":"Nghịch lý bổ sung Canxi: Uống vào có vào xương không?","content":"Canxi tự do đưa vào đường tiêu hóa nếu thiếu các yếu tố đồng vận chuyển (Vitamin D3 kích hoạt hấp thu ở ruột non, Vitamin K2 định hướng gắn canxi vào mô xương) sẽ bị đào thải qua thận gây sỏi hoặc lắng đọng ở thành mạch máu gây xơ vữa và vôi hóa dây chằng quanh cột sống."},{"title":"Vai trò thiết yếu của Magie và Kẽm","content":"Magie kích hoạt hormone calcitonin đưa canxi vào xương và ức chế hormone cận giáp (PTH) - hormone rút canxi từ xương ra máu. Kẽm là đồng yếu tố enzyme tham gia trực tiếp tổng hợp khung collagen nền của xương. Thiếu magie và kẽm thì dù uống bao nhiêu canxi xương vẫn xốp và giòn."},{"title":"Cơ chế dinh dưỡng thẩm thấu của đĩa đệm","content":"Sau 20 tuổi, đĩa đệm không còn mạch máu trực tiếp nuôi dưỡng mà nhận dinh dưỡng hoàn toàn qua cơ chế thẩm thấu khuếch tán từ mâm sụn đốt sống (vertebral endplate). Do đó, việc vận động đúng biên độ và uống đủ nước giàu khoáng chất là điều kiện tiên quyết để ép dinh dưỡng thẩm thấu vào nuôi nhân nhầy."}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
