insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('000fc299-c318-4194-a08e-178bf883e7b5', 'default', 'b0000000-0000-0000-0004-000000000003', 'text', 'y_nghia', 2, true, '{"text":"### 💩 Tóm tắt cốt lõi: Đại tràng – Giai đoạn \"ĐẨY\" nhu động & Tái hấp thu nước\n- **Giải phẫu & Sinh lý đại tràng:** Dài khoảng 1.5 mét, gồm manh tràng, đại tràng lên, đại tràng ngang, đại tràng xuống, đại tràng sigma và trực tràng. Đại tràng tiếp nhận 1.5–2 lít dưỡng chấp lỏng mỗi ngày từ hồi tràng, tái hấp thu tới 90% lượng nước và điện giải (khoảng 1.3–1.8 lít) để cô đặc phân.\n- **Cơ chế nhu động & Phản xạ tống phân (Defecation Reflex):**\n  - Chuyển động phân đoạn nhào trộn thức ăn.\n  - Nhu động khối lượng lớn (Mass Movement): Xảy ra 1–3 lần mỗi ngày, thường mạnh nhất sau bữa ăn sáng nhờ Phản xạ dạ dày - đại tràng (Gastrocolic Reflex).\n  - Phản xạ đi ngoài: Phân đi vào bóng trực tràng làm căng thụ thể áp lực, gửi tín hiệu thần kinh tủy sống làm giãn cơ thắt hậu môn trong (tự động) và kích hoạt cơ thắt ngoài (chủ động theo ý muốn).\n- **Táo bón mạn tính & Biến chứng trĩ:** Thiếu chất xơ và nước làm phân khô cứng, tăng áp lực rặn khi đi ngoài làm căng giãn phình tĩnh mạch đệm hậu môn dẫn đến búi trĩ và rách nứt kẽ hậu môn.\n- **Tầm soát Polyp đại trực tràng:** 95% ung thư đại trực tràng phát triển từ các khối polyp tuyến (Adenomatous polyp) âm thầm trong 5–10 năm. Nội soi đại tràng định kỳ sau tuổi 40 là tiêu chuẩn vàng phát hiện và cắt bỏ polyp sớm.","lines":["**Giải phẫu & Sinh lý đại tràng:** Dài khoảng 1.5 mét, gồm manh tràng, đại tràng lên, đại tràng ngang, đại tràng xuống, đại tràng sigma và trực tràng. Đại tràng tiếp nhận 1.5–2 lít dưỡng chấp lỏng mỗi ngày từ hồi tràng, tái hấp thu tới 90% lượng nước và điện giải (khoảng 1.3–1.8 lít) để cô đặc phân.","**Cơ chế nhu động & Phản xạ tống phân (Defecation Reflex):**","Chuyển động phân đoạn nhào trộn thức ăn.","Nhu động khối lượng lớn (Mass Movement): Xảy ra 1–3 lần mỗi ngày, thường mạnh nhất sau bữa ăn sáng nhờ Phản xạ dạ dày - đại tràng (Gastrocolic Reflex).","Phản xạ đi ngoài: Phân đi vào bóng trực tràng làm căng thụ thể áp lực, gửi tín hiệu thần kinh tủy sống làm giãn cơ thắt hậu môn trong (tự động) và kích hoạt cơ thắt ngoài (chủ động theo ý muốn).","**Táo bón mạn tính & Biến chứng trĩ:** Thiếu chất xơ và nước làm phân khô cứng, tăng áp lực rặn khi đi ngoài làm căng giãn phình tĩnh mạch đệm hậu môn dẫn đến búi trĩ và rách nứt kẽ hậu môn.","**Tầm soát Polyp đại trực tràng:** 95% ung thư đại trực tràng phát triển từ các khối polyp tuyến (Adenomatous polyp) âm thầm trong 5–10 năm. Nội soi đại tràng định kỳ sau tuổi 40 là tiêu chuẩn vàng phát hiện và cắt bỏ polyp sớm."],"title":"💩 Tóm tắt cốt lõi: Đại tràng – Giai đoạn \"ĐẨY\" nhu động & Tái hấp thu nước","format":"bullet","content":"### 💩 Tóm tắt cốt lõi: Đại tràng – Giai đoạn \"ĐẨY\" nhu động & Tái hấp thu nước\n- **Giải phẫu & Sinh lý đại tràng:** Dài khoảng 1.5 mét, gồm manh tràng, đại tràng lên, đại tràng ngang, đại tràng xuống, đại tràng sigma và trực tràng. Đại tràng tiếp nhận 1.5–2 lít dưỡng chấp lỏng mỗi ngày từ hồi tràng, tái hấp thu tới 90% lượng nước và điện giải (khoảng 1.3–1.8 lít) để cô đặc phân.\n- **Cơ chế nhu động & Phản xạ tống phân (Defecation Reflex):**\n  - Chuyển động phân đoạn nhào trộn thức ăn.\n  - Nhu động khối lượng lớn (Mass Movement): Xảy ra 1–3 lần mỗi ngày, thường mạnh nhất sau bữa ăn sáng nhờ Phản xạ dạ dày - đại tràng (Gastrocolic Reflex).\n  - Phản xạ đi ngoài: Phân đi vào bóng trực tràng làm căng thụ thể áp lực, gửi tín hiệu thần kinh tủy sống làm giãn cơ thắt hậu môn trong (tự động) và kích hoạt cơ thắt ngoài (chủ động theo ý muốn).\n- **Táo bón mạn tính & Biến chứng trĩ:** Thiếu chất xơ và nước làm phân khô cứng, tăng áp lực rặn khi đi ngoài làm căng giãn phình tĩnh mạch đệm hậu môn dẫn đến búi trĩ và rách nứt kẽ hậu môn.\n- **Tầm soát Polyp đại trực tràng:** 95% ung thư đại trực tràng phát triển từ các khối polyp tuyến (Adenomatous polyp) âm thầm trong 5–10 năm. Nội soi đại tràng định kỳ sau tuổi 40 là tiêu chuẩn vàng phát hiện và cắt bỏ polyp sớm."}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
