insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('aa435467-336e-4117-84b7-a32d6a670416', 'default', 'b0000000-0000-0000-0000-000000000024', 'text', 'y_nghia', 2, true, '{"text":"### 🫁 Tóm tắt cốt lõi: Hệ Hô hấp & Cơ chế trao đổi khí tại màng phế nang\n- **Cơ học hô hấp & Cơ hoành:** Động tác hít vào là quá trình chủ động: Cơ hoành co hạ thấp xuống 1.5–7cm kết hợp cơ liên sườn ngoài nâng lồng ngực lên, làm giảm áp suất trong khoang màng phổi (áp suất âm) hút không khí tràn vào phổi (Định luật Boyle). Thở ra bình thường là quá trình thụ động do tính đàn hồi co hồi của nhu mô phổi.\n- **Màng Phế nang - Mao mạch siêu mỏng:** Phổi có khoảng **300–500 triệu phế nang** với tổng diện tích bề mặt trao đổi khí lên tới **70–100 m²** (rộng bằng một căn hộ). Khoảng cách từ lòng phế nang đến hồng cầu mao mạch chỉ mỏng 0.5 micromet, cho phép Oxy và CO2 khuếch tán qua lại trong chớp mắt (0.25 giây).\n- **Chất hoạt động bề mặt Surfactant:** Do tế bào phế nang type II tiết ra, làm giảm sức căng bề mặt chất lỏng trong lòng phế nang, ngăn không cho các phế nang nhỏ bị xẹp lép ở cuối thì thở ra.\n- **Bệnh phổi tắc nghẽn mạn tính (COPD) & Ngưng thở khi ngủ:**\n  - *COPD:* Hút thuốc lá mạn tính phá hủy thành phế nang (khí phế thủng) và làm viêm phù nề đường thở, khiến khí bị bẫy lại trong phổi không thở ra hết được.\n  - *Hội chứng ngưng thở khi ngủ (OSA):* Cơ vùng hầu họng bị chùng nhão tụt ra sau bịt kín đường thở ban đêm, gây thiếu oxy não tái diễn, tăng huyết áp kháng trị và đột quỵ.","lines":["**Cơ học hô hấp & Cơ hoành:** Động tác hít vào là quá trình chủ động: Cơ hoành co hạ thấp xuống 1.5–7cm kết hợp cơ liên sườn ngoài nâng lồng ngực lên, làm giảm áp suất trong khoang màng phổi (áp suất âm) hút không khí tràn vào phổi (Định luật Boyle). Thở ra bình thường là quá trình thụ động do tính đàn hồi co hồi của nhu mô phổi.","**Màng Phế nang - Mao mạch siêu mỏng:** Phổi có khoảng **300–500 triệu phế nang** với tổng diện tích bề mặt trao đổi khí lên tới **70–100 m²** (rộng bằng một căn hộ). Khoảng cách từ lòng phế nang đến hồng cầu mao mạch chỉ mỏng 0.5 micromet, cho phép Oxy và CO2 khuếch tán qua lại trong chớp mắt (0.25 giây).","**Chất hoạt động bề mặt Surfactant:** Do tế bào phế nang type II tiết ra, làm giảm sức căng bề mặt chất lỏng trong lòng phế nang, ngăn không cho các phế nang nhỏ bị xẹp lép ở cuối thì thở ra.","**Bệnh phổi tắc nghẽn mạn tính (COPD) & Ngưng thở khi ngủ:**","*COPD:* Hút thuốc lá mạn tính phá hủy thành phế nang (khí phế thủng) và làm viêm phù nề đường thở, khiến khí bị bẫy lại trong phổi không thở ra hết được.","*Hội chứng ngưng thở khi ngủ (OSA):* Cơ vùng hầu họng bị chùng nhão tụt ra sau bịt kín đường thở ban đêm, gây thiếu oxy não tái diễn, tăng huyết áp kháng trị và đột quỵ."],"title":"🫁 Tóm tắt cốt lõi: Hệ Hô hấp & Cơ chế trao đổi khí tại màng phế nang","format":"bullet","content":"### 🫁 Tóm tắt cốt lõi: Hệ Hô hấp & Cơ chế trao đổi khí tại màng phế nang\n- **Cơ học hô hấp & Cơ hoành:** Động tác hít vào là quá trình chủ động: Cơ hoành co hạ thấp xuống 1.5–7cm kết hợp cơ liên sườn ngoài nâng lồng ngực lên, làm giảm áp suất trong khoang màng phổi (áp suất âm) hút không khí tràn vào phổi (Định luật Boyle). Thở ra bình thường là quá trình thụ động do tính đàn hồi co hồi của nhu mô phổi.\n- **Màng Phế nang - Mao mạch siêu mỏng:** Phổi có khoảng **300–500 triệu phế nang** với tổng diện tích bề mặt trao đổi khí lên tới **70–100 m²** (rộng bằng một căn hộ). Khoảng cách từ lòng phế nang đến hồng cầu mao mạch chỉ mỏng 0.5 micromet, cho phép Oxy và CO2 khuếch tán qua lại trong chớp mắt (0.25 giây).\n- **Chất hoạt động bề mặt Surfactant:** Do tế bào phế nang type II tiết ra, làm giảm sức căng bề mặt chất lỏng trong lòng phế nang, ngăn không cho các phế nang nhỏ bị xẹp lép ở cuối thì thở ra.\n- **Bệnh phổi tắc nghẽn mạn tính (COPD) & Ngưng thở khi ngủ:**\n  - *COPD:* Hút thuốc lá mạn tính phá hủy thành phế nang (khí phế thủng) và làm viêm phù nề đường thở, khiến khí bị bẫy lại trong phổi không thở ra hết được.\n  - *Hội chứng ngưng thở khi ngủ (OSA):* Cơ vùng hầu họng bị chùn