insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('8421021c-1427-4161-865d-8d1c2e240bf7', 'default', 'b0000000-0000-0000-0004-000000000002', 'text', 'y_nghia', 2, true, '{"text":"### 🌾 Tóm tắt cốt lõi: Ruột non – Trung tâm \"THẤM\" & Diện tích bề mặt hấp thu khổng lồ\n- **Cấu trúc nhung mao & Vi nhung mao:** Chiều dài ruột non 5–6 mét, nhưng nhờ hệ thống nếp gấp van Kerckring, nhung mao (Villi) và vi nhung mao (Microvilli) tạo thành bờ bàn chải (Brush Border), diện tích hấp thu được mở rộng lên tới **250–300 m²** (tương đương một sân tennis).\n- **Cơ chế vận chuyển dưỡng chất qua tế bào biểu mô (Enterocytes):**\n  - Đường đơn: Glucose và Galactose hấp thu tích cực thứ phát qua kênh SGLT-1 (đồng vận chuyển ion Na+); Fructose khuếch tán hỗ trợ qua kênh GLUT-5.\n  - Axit amin & Peptide: Hấp thu qua kênh đồng vận chuyển PepT1.\n  - Chất béo: Axit béo chuỗi dài được bao bọc bởi muối mật tạo hạt Micelle, đi vào tế bào ruột tái tổng hợp thành Chylomicron đưa vào hệ bạch huyết.\n- **Hội chứng rò rỉ ruột (Leaky Gut Syndrome):** Bình thường các tế bào ruột gắn kết khít khao nhờ các mối nối chặt (Tight Junctions - protein Zonulin, Occludin, Claudin). Khi bị viêm do stress, kháng sinh hoặc độc tố, các mối nối bị toác rộng, cho phép đại phân tử protein chưa tiêu hóa và nội độc tố vi khuẩn (LPS) lọt vào máu kích hoạt bệnh tự miễn và viêm toàn thân.","lines":["**Cấu trúc nhung mao & Vi nhung mao:** Chiều dài ruột non 5–6 mét, nhưng nhờ hệ thống nếp gấp van Kerckring, nhung mao (Villi) và vi nhung mao (Microvilli) tạo thành bờ bàn chải (Brush Border), diện tích hấp thu được mở rộng lên tới **250–300 m²** (tương đương một sân tennis).","**Cơ chế vận chuyển dưỡng chất qua tế bào biểu mô (Enterocytes):**","Đường đơn: Glucose và Galactose hấp thu tích cực thứ phát qua kênh SGLT-1 (đồng vận chuyển ion Na+); Fructose khuếch tán hỗ trợ qua kênh GLUT-5.","Axit amin & Peptide: Hấp thu qua kênh đồng vận chuyển PepT1.","Chất béo: Axit béo chuỗi dài được bao bọc bởi muối mật tạo hạt Micelle, đi vào tế bào ruột tái tổng hợp thành Chylomicron đưa vào hệ bạch huyết.","**Hội chứng rò rỉ ruột (Leaky Gut Syndrome):** Bình thường các tế bào ruột gắn kết khít khao nhờ các mối nối chặt (Tight Junctions - protein Zonulin, Occludin, Claudin). Khi bị viêm do stress, kháng sinh hoặc độc tố, các mối nối bị toác rộng, cho phép đại phân tử protein chưa tiêu hóa và nội độc tố vi khuẩn (LPS) lọt vào máu kích hoạt bệnh tự miễn và viêm toàn thân."],"title":"🌾 Tóm tắt cốt lõi: Ruột non – Trung tâm \"THẤM\" & Diện tích bề mặt hấp thu khổng lồ","format":"bullet","content":"### 🌾 Tóm tắt cốt lõi: Ruột non – Trung tâm \"THẤM\" & Diện tích bề mặt hấp thu khổng lồ\n- **Cấu trúc nhung mao & Vi nhung mao:** Chiều dài ruột non 5–6 mét, nhưng nhờ hệ thống nếp gấp van Kerckring, nhung mao (Villi) và vi nhung mao (Microvilli) tạo thành bờ bàn chải (Brush Border), diện tích hấp thu được mở rộng lên tới **250–300 m²** (tương đương một sân tennis).\n- **Cơ chế vận chuyển dưỡng chất qua tế bào biểu mô (Enterocytes):**\n  - Đường đơn: Glucose và Galactose hấp thu tích cực thứ phát qua kênh SGLT-1 (đồng vận chuyển ion Na+); Fructose khuếch tán hỗ trợ qua kênh GLUT-5.\n  - Axit amin & Peptide: Hấp thu qua kênh đồng vận chuyển PepT1.\n  - Chất béo: Axit béo chuỗi dài được bao bọc bởi muối mật tạo hạt Micelle, đi vào tế bào ruột tái tổng hợp thành Chylomicron đưa vào hệ bạch huyết.\n- **Hội chứng rò rỉ ruột (Leaky Gut Syndrome):** Bình thường các tế bào ruột gắn kết khít khao nhờ các mối nối chặt (Tight Junctions - protein Zonulin, Occludin, Claudin). Khi bị viêm do stress, kháng sinh hoặc độc tố, các mối nối bị toác rộng, cho phép đại phân tử protein chưa tiêu hóa và nội độc tố vi khuẩn (LPS) lọt vào máu kích hoạt bệnh tự miễn và viêm toàn thân."}'::jsonb)
