insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('d8f816d3-416e-4191-b5a5-bfbd38ee4222', 'default', '77f600d0-4fe0-47ec-92c3-682a36505dbb', 'text', 'y_nghia', 2, true, '{"lines":["**Tư thế nằm ngủ chuẩn sinh lý**: Cột sống cổ có đường cong ưỡn sinh lý ra trước (lordosis). Khi nằm ngủ, khoảng cách giữa đầu, gáy và mặt nệm phải được lấp đầy hoàn hảo. Nằm sấp là tư thế có hại nhất vì buộc cổ phải xoay cực hạn 90 độ suốt nhiều giờ, gây vặn xoắn động mạch đốt sống và căng cơ bán gai đầu.","**Tiêu chuẩn chọn gối nâng đỡ đốt sống cổ**: Gối quá cao làm gập cổ, xóa đường cong sinh lý, kéo căng tủy cổ và đĩa đệm. Gối quá thấp hoặc không gối làm cổ ngửa quá mức, ép các cuống khớp sau (facet joints). Gối chuẩn phải giữ cho trục đầu - cổ - ngực nằm trên một đường thẳng sinh học khi nằm nghiêng và giữ nguyên hõm gáy khi nằm ngửa.","**Rễ thần kinh C3-C4-C5 và cơ hoành**: Dây thần kinh hoành (Phrenic nerve) bắt nguồn chủ yếu từ rễ thần kinh cổ C3, C4, C5 (\"C3, 4, 5 keeps the diaphragm alive\"). Khi sai lệch đốt sống cổ chèn ép rễ này, trương lực cơ hoành bị suy giảm, dẫn đến khó thở, hụt hơi, tức ngực không rõ nguyên nhân và mở lỏng cơ thắt thực quản dưới gây trào ngược dạ dày thực quản mạn tính."],"title":"Tóm tắt cốt lõi & Nguyên lý sinh học","format":"bullet","content":"### 1. Tư thế nằm ngủ chuẩn sinh lý\n\nCột sống cổ có đường cong ưỡn sinh lý ra trước (lordosis). Khi nằm ngủ, khoảng cách giữa đầu, gáy và mặt nệm phải được lấp đầy hoàn hảo. Nằm sấp là tư thế có hại nhất vì buộc cổ phải xoay cực hạn 90 độ suốt nhiều giờ, gây vặn xoắn động mạch đốt sống và căng cơ bán gai đầu.\n\n---\n\n### 2. Tiêu chuẩn chọn gối nâng đỡ đốt sống cổ\n\nGối quá cao làm gập cổ, xóa đường cong sinh lý, kéo căng tủy cổ và đĩa đệm. Gối quá thấp hoặc không gối làm cổ ngửa quá mức, ép các cuống khớp sau (facet joints). Gối chuẩn phải giữ cho trục đầu - cổ - ngực nằm trên một đường thẳng sinh học khi nằm nghiêng và giữ nguyên hõm gáy khi nằm ngửa.\n\n---\n\n### 3. Rễ thần kinh C3-C4-C5 và cơ hoành\n\nDây thần kinh hoành (Phrenic nerve) bắt nguồn chủ yếu từ rễ thần kinh cổ C3, C4, C5 (\"C3, 4, 5 keeps the diaphragm alive\"). Khi sai lệch đốt sống cổ chèn ép rễ này, trương lực cơ hoành bị suy giảm, dẫn đến khó thở, hụt hơi, tức ngực không rõ nguyên nhân và mở lỏng cơ thắt thực quản dưới gây trào ngược dạ dày thực quản mạn tính.","takeaways":[{"title":"Tư thế nằm ngủ chuẩn sinh lý","content":"Cột sống cổ có đường cong ưỡn sinh lý ra trước (lordosis). Khi nằm ngủ, khoảng cách giữa đầu, gáy và mặt nệm phải được lấp đầy hoàn hảo. Nằm sấp là tư thế có hại nhất vì buộc cổ phải xoay cực hạn 90 độ suốt nhiều giờ, gây vặn xoắn động mạch đốt sống và căng cơ bán gai đầu."},{"title":"Tiêu chuẩn chọn gối nâng đỡ đốt sống cổ","content":"Gối quá cao làm gập cổ, xóa đường cong sinh lý, kéo căng tủy cổ và đĩa đệm. Gối quá thấp hoặc không gối làm cổ ngửa quá mức, ép các cuống khớp sau (facet joints). Gối chuẩn phải giữ cho trục đầu - cổ - ngực nằm trên một đường thẳng sinh học khi nằm nghiêng và giữ nguyên hõm gáy khi nằm ngửa."},{"title":"Rễ thần kinh C3-C4-C5 và cơ hoành","content":"Dây thần kinh hoành (Phrenic nerve) bắt nguồn chủ yếu từ rễ thần kinh cổ C3, C4, C5 (\"C3, 4, 5 keeps the diaphragm alive\"). Khi sai lệch đốt sống cổ chèn ép rễ này, trương lực cơ hoành bị suy giảm, dẫn đến khó thở, hụt hơi, tức ngực không rõ nguyên nhân và mở lỏng cơ thắt thực quản dưới gây trào ngược dạ dày thực quản mạn tính."}]}'::jsonb)
