insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('39345acf-001c-48d0-96e7-0f2ccfc4c1f7', 'default', 'b0000000-0000-0000-0008-000000000005', 'text', 'y_nghia', 2, true, '{"text":"### 💧 Tóm tắt cốt lõi: Hệ Bạch huyết – Mạng lưới dẫn lưu & Trạm gác an ninh hạch\n- **Tuần hoàn dịch bạch huyết:** Mỗi ngày có khoảng 20 lít dịch thoát ra từ mao mạch máu vào mô kẽ, 17 lít được tĩnh mạch tái hấp thu trực tiếp, còn lại **3 lít dịch bạch huyết** giàu protein, tế bào lạ và vi khuẩn được các mao mạch bạch huyết thu gom.\n- **Đường dẫn truyền sinh học:** Dịch bạch huyết từ nửa dưới cơ thể tập trung về Bể dưỡng chấp (Cisterna Chyli) ở bụng, đi lên qua **Ống ngực (Thoracic Duct)** và đổ vào Tĩnh mạch dưới đòn trái để tái hòa nhập dòng máu tuần hoàn.\n- **Trạm gác an ninh Hạch bạch huyết (Lymph Nodes):** Cơ thể có khoảng 600–700 hạch bạch huyết hình hạt đậu tập trung thành cụm ở cổ, nách, bẹn, mạc treo ruột. Hạch hoạt động như bộ lọc sinh học: dịch bạch huyết chảy chậm qua các xoang hạch chứa đầy đại thực bào và tế bào lympho để tiêu diệt mầm bệnh. Khi có viêm nhiễm tại chỗ, hạch tương ứng sẽ sưng to và đau (phản ứng hạch viêm bình thường).\n- **Lưu thông hệ bạch huyết:** Hệ bạch huyết **không có tim để bơm**; dòng dịch chảy được hoàn toàn nhờ sự co thắt của cơ bắp xung quanh, nhịp thở sâu của cơ hoành và van một chiều chống chảy ngược. Lười vận động làm dòng bạch huyết ứ trệ gây phù nề và tích lũy độc chất.","lines":["**Tuần hoàn dịch bạch huyết:** Mỗi ngày có khoảng 20 lít dịch thoát ra từ mao mạch máu vào mô kẽ, 17 lít được tĩnh mạch tái hấp thu trực tiếp, còn lại **3 lít dịch bạch huyết** giàu protein, tế bào lạ và vi khuẩn được các mao mạch bạch huyết thu gom.","**Đường dẫn truyền sinh học:** Dịch bạch huyết từ nửa dưới cơ thể tập trung về Bể dưỡng chấp (Cisterna Chyli) ở bụng, đi lên qua **Ống ngực (Thoracic Duct)** và đổ vào Tĩnh mạch dưới đòn trái để tái hòa nhập dòng máu tuần hoàn.","**Trạm gác an ninh Hạch bạch huyết (Lymph Nodes):** Cơ thể có khoảng 600–700 hạch bạch huyết hình hạt đậu tập trung thành cụm ở cổ, nách, bẹn, mạc treo ruột. Hạch hoạt động như bộ lọc sinh học: dịch bạch huyết chảy chậm qua các xoang hạch chứa đầy đại thực bào và tế bào lympho để tiêu diệt mầm bệnh. Khi có viêm nhiễm tại chỗ, hạch tương ứng sẽ sưng to và đau (phản ứng hạch viêm bình thường).","**Lưu thông hệ bạch huyết:** Hệ bạch huyết **không có tim để bơm**; dòng dịch chảy được hoàn toàn nhờ sự co thắt của cơ bắp xung quanh, nhịp thở sâu của cơ hoành và van một chiều chống chảy ngược. Lười vận động làm dòng bạch huyết ứ trệ gây phù nề và tích lũy độc chất."],"title":"💧 Tóm tắt cốt lõi: Hệ Bạch huyết – Mạng lưới dẫn lưu & Trạm gác an ninh hạch","format":"bullet","content":"### 💧 Tóm tắt cốt lõi: Hệ Bạch huyết – Mạng lưới dẫn lưu & Trạm gác an ninh hạch\n- **Tuần hoàn dịch bạch huyết:** Mỗi ngày có khoảng 20 lít dịch thoát ra từ mao mạch máu vào mô kẽ, 17 lít được tĩnh mạch tái hấp thu trực tiếp, còn lại **3 lít dịch bạch huyết** giàu protein, tế bào lạ và vi khuẩn được các mao mạch bạch huyết thu gom.\n- **Đường dẫn truyền sinh học:** Dịch bạch huyết từ nửa dưới cơ thể tập trung về Bể dưỡng chấp (Cisterna Chyli) ở bụng, đi lên qua **Ống ngực (Thoracic Duct)** và đổ vào Tĩnh mạch dưới đòn trái để tái hòa nhập dòng máu tuần hoàn.\n- **Trạm gác an ninh Hạch bạch huyết (Lymph Nodes):** Cơ thể có khoảng 600–700 hạch bạch huyết hình hạt đậu tập trung thành cụm ở cổ, nách, bẹn, mạc treo ruột. Hạch hoạt động như bộ lọc sinh học: dịch bạch huyết chảy chậm qua các xoang hạch chứa đầy đại thực bào và tế bào lympho để tiêu diệt mầm bệnh. Khi có viêm nhiễm tại chỗ, hạch tương ứng sẽ sưng to và đau (phản ứng hạch viêm bình thường).\n- **Lưu thông hệ bạch huyết:** Hệ bạch huyết **không có tim để bơm**; dòng dịch chảy được hoàn toàn nhờ sự co thắt của cơ bắp xung quanh, nhịp thở sâu của cơ hoành và van một chiều chống chảy ngược. Lười vận động làm dòng bạch huyết ứ trệ gây phù nề và tích lũy độc chất."}'::jsonb)
