insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('da9fc6b8-fe11-44fc-8d24-d482802b61a6', 'default', 'b0000000-0000-0000-0000-000000000051', 'text', 'y_nghia', 2, true, '{"text":"### 🧭 Tóm tắt cốt lõi: Hệ Nội tiết & Cơ chế truyền tin hormone toàn thân\n- **Bản chất của Hệ nội tiết:** Mạng lưới các tuyến không có ống dẫn, tiết trực tiếp các phân tử hóa học (Hormone) vào dòng máu để đến tác động lên các tế bào đích mang thụ thể tương ứng ở khắp cơ thể.\n- **Trục chỉ huy Vùng dưới đồi – Tuyến yên (HPA/HPT/HPG Axis):**\n  - Vùng dưới đồi (Hypothalamus) là nhạc trưởng tối cao, tích hợp tín hiệu thần kinh và giải phóng các hormone kích thích (RH) hoặc ức chế (IH).\n  - Tuyến yên (Pituitary Gland) là \"tuyến chỉ huy phó\", tiết các hormone kích thích tuyến đích: TSH (tuyến giáp), ACTH (vỏ thượng thận), LH/FSH (tuyến sinh dục), GH (tăng trưởng).\n- **Cơ chế điều hòa ngược âm tính (Negative Feedback):** Khi nồng độ hormone tuyến đích trong máu đạt ngưỡng tối ưu, chúng sẽ phát tín hiệu ức chế ngược lại vùng dưới đồi và tuyến yên để ngừng tiết kích thích tố, giữ cho nội môi không bị thừa thãi hormone.\n- **Phân loại hormone sinh học:** Hormone steroid (tan trong mỡ như Cortisol, Testosterone, Estrogen chui thẳng vào nhân tế bào tác động lên DNA) vs Hormone peptide/axit amin (tan trong nước như Insulin, Adrenaline gắn lên thụ thể bề mặt màng tế bào).","lines":["**Bản chất của Hệ nội tiết:** Mạng lưới các tuyến không có ống dẫn, tiết trực tiếp các phân tử hóa học (Hormone) vào dòng máu để đến tác động lên các tế bào đích mang thụ thể tương ứng ở khắp cơ thể.","**Trục chỉ huy Vùng dưới đồi – Tuyến yên (HPA/HPT/HPG Axis):**","Vùng dưới đồi (Hypothalamus) là nhạc trưởng tối cao, tích hợp tín hiệu thần kinh và giải phóng các hormone kích thích (RH) hoặc ức chế (IH).","Tuyến yên (Pituitary Gland) là \"tuyến chỉ huy phó\", tiết các hormone kích thích tuyến đích: TSH (tuyến giáp), ACTH (vỏ thượng thận), LH/FSH (tuyến sinh dục), GH (tăng trưởng).","**Cơ chế điều hòa ngược âm tính (Negative Feedback):** Khi nồng độ hormone tuyến đích trong máu đạt ngưỡng tối ưu, chúng sẽ phát tín hiệu ức chế ngược lại vùng dưới đồi và tuyến yên để ngừng tiết kích thích tố, giữ cho nội môi không bị thừa thãi hormone.","**Phân loại hormone sinh học:** Hormone steroid (tan trong mỡ như Cortisol, Testosterone, Estrogen chui thẳng vào nhân tế bào tác động lên DNA) vs Hormone peptide/axit amin (tan trong nước như Insulin, Adrenaline gắn lên thụ thể bề mặt màng tế bào)."],"title":"🧭 Tóm tắt cốt lõi: Hệ Nội tiết & Cơ chế truyền tin hormone toàn thân","format":"bullet","content":"### 🧭 Tóm tắt cốt lõi: Hệ Nội tiết & Cơ chế truyền tin hormone toàn thân\n- **Bản chất của Hệ nội tiết:** Mạng lưới các tuyến không có ống dẫn, tiết trực tiếp các phân tử hóa học (Hormone) vào dòng máu để đến tác động lên các tế bào đích mang thụ thể tương ứng ở khắp cơ thể.\n- **Trục chỉ huy Vùng dưới đồi – Tuyến yên (HPA/HPT/HPG Axis):**\n  - Vùng dưới đồi (Hypothalamus) là nhạc trưởng tối cao, tích hợp tín hiệu thần kinh và giải phóng các hormone kích thích (RH) hoặc ức chế (IH).\n  - Tuyến yên (Pituitary Gland) là \"tuyến chỉ huy phó\", tiết các hormone kích thích tuyến đích: TSH (tuyến giáp), ACTH (vỏ thượng thận), LH/FSH (tuyến sinh dục), GH (tăng trưởng).\n- **Cơ chế điều hòa ngược âm tính (Negative Feedback):** Khi nồng độ hormone tuyến đích trong máu đạt ngưỡng tối ưu, chúng sẽ phát tín hiệu ức chế ngược lại vùng dưới đồi và tuyến yên để ngừng tiết kích thích tố, giữ cho nội môi không bị thừa thãi hormone.\n- **Phân loại hormone sinh học:** Hormone steroid (tan trong mỡ như Cortisol, Testosterone, Estrogen chui thẳng vào nhân tế bào tác động lên DNA) vs Hormone peptide/axit amin (tan trong nước như Insulin, Adrenaline gắn lên thụ thể bề mặt màng tế bào)."}'::jsonb)
