insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('e6c076df-020d-4113-9dc7-16c63051c47e', 'default', 'b0000000-0000-0000-0006-000000000001', 'text', 'y_nghia', 2, true, '{"text":"### 🦋 Tóm tắt cốt lõi: Tuyến giáp – Nhạc trưởng điều hòa tốc độ chuyển hóa năng lượng\n- **Giải phẫu & Hormone tuyến giáp:** Tuyến giáp hình cánh bướm nằm trước cổ, sản xuất hormone Thyroxine ($T_4$ - 80%) và Triiodothyronine ($T_3$ - 20%, dạng hoạt tính sinh học mạnh gấp 4 lần). Cần nguyên tố vi lượng **I-ốt** và **Selen** (để enzyme Deiodinase chuyển đổi $T_4$ thành $T_3$ tại gan và thận).\n- **Vai trò chuyển hóa:** Tuyến giáp quyết định Tốc độ chuyển hóa cơ bản (BMR), điều hòa nhịp tim, thân nhiệt, tốc độ đốt cháy oxy của ty thể và sự phát triển trí não ở trẻ nhỏ.\n- **Suy giáp (Hypothyroidism) vs Cường giáp (Hyperthyroidism):**\n  - *Suy giáp (thường do viêm tuyến giáp tự miễn Hashimoto):* Thiếu $T_3/T_4$, chuyển hóa chậm chạp, mệt mỏi, sợ lạnh, tăng cân dù ăn ít, táo bón, rụng tóc, phù niêm, sương mù não.\n  - *Cường giáp (thường do bệnh Basedow/Graves):* Kháng thể kích thích thụ thể TSH làm tuyến giáp tiết ồ ạt hormone, gây tim đập nhanh, hồi hộp, sụt cân cấp, sợ nóng, run tay, mắt lồi.\n- **Tuyến cận giáp & Cường tuyến cận giáp:** 4 tuyến cận giáp tiết hormone PTH để kéo canxi từ xương vào máu khi canxi máu giảm. Cường cận giáp làm hủy hoại xương dẫn đến loãng xương nặng nề, sỏi thận tái phát nhiều lần.","lines":["**Giải phẫu & Hormone tuyến giáp:** Tuyến giáp hình cánh bướm nằm trước cổ, sản xuất hormone Thyroxine ($T_4$ - 80%) và Triiodothyronine ($T_3$ - 20%, dạng hoạt tính sinh học mạnh gấp 4 lần). Cần nguyên tố vi lượng **I-ốt** và **Selen** (để enzyme Deiodinase chuyển đổi $T_4$ thành $T_3$ tại gan và thận).","**Vai trò chuyển hóa:** Tuyến giáp quyết định Tốc độ chuyển hóa cơ bản (BMR), điều hòa nhịp tim, thân nhiệt, tốc độ đốt cháy oxy của ty thể và sự phát triển trí não ở trẻ nhỏ.","**Suy giáp (Hypothyroidism) vs Cường giáp (Hyperthyroidism):**","*Suy giáp (thường do viêm tuyến giáp tự miễn Hashimoto):* Thiếu $T_3/T_4$, chuyển hóa chậm chạp, mệt mỏi, sợ lạnh, tăng cân dù ăn ít, táo bón, rụng tóc, phù niêm, sương mù não.","*Cường giáp (thường do bệnh Basedow/Graves):* Kháng thể kích thích thụ thể TSH làm tuyến giáp tiết ồ ạt hormone, gây tim đập nhanh, hồi hộp, sụt cân cấp, sợ nóng, run tay, mắt lồi.","**Tuyến cận giáp & Cường tuyến cận giáp:** 4 tuyến cận giáp tiết hormone PTH để kéo canxi từ xương vào máu khi canxi máu giảm. Cường cận giáp làm hủy hoại xương dẫn đến loãng xương nặng nề, sỏi thận tái phát nhiều lần."],"title":"🦋 Tóm tắt cốt lõi: Tuyến giáp – Nhạc trưởng điều hòa tốc độ chuyển hóa năng lượng","format":"bullet","content":"### 🦋 Tóm tắt cốt lõi: Tuyến giáp – Nhạc trưởng điều hòa tốc độ chuyển hóa năng lượng\n- **Giải phẫu & Hormone tuyến giáp:** Tuyến giáp hình cánh bướm nằm trước cổ, sản xuất hormone Thyroxine ($T_4$ - 80%) và Triiodothyronine ($T_3$ - 20%, dạng hoạt tính sinh học mạnh gấp 4 lần). Cần nguyên tố vi lượng **I-ốt** và **Selen** (để enzyme Deiodinase chuyển đổi $T_4$ thành $T_3$ tại gan và thận).\n- **Vai trò chuyển hóa:** Tuyến giáp quyết định Tốc độ chuyển hóa cơ bản (BMR), điều hòa nhịp tim, thân nhiệt, tốc độ đốt cháy oxy của ty thể và sự phát triển trí não ở trẻ nhỏ.\n- **Suy giáp (Hypothyroidism) vs Cường giáp (Hyperthyroidism):**\n  - *Suy giáp (thường do viêm tuyến giáp tự miễn Hashimoto):* Thiếu $T_3/T_4$, chuyển hóa chậm chạp, mệt mỏi, sợ lạnh, tăng cân dù ăn ít, táo bón, rụng tóc, phù niêm, sương mù não.\n  - *Cường giáp (thường do bệnh Basedow/Graves):* Kháng thể kích thích thụ thể TSH làm tuyến giáp tiết ồ ạt hormone, gây tim đập nhanh, hồi hộp, sụt cân cấp, sợ nóng, run tay, mắt lồi.\n- **Tuyến cận giáp & Cường tuyến cận giáp:** 4 tuyến cận giáp tiết hormone PTH để kéo canxi từ xương vào máu khi canxi máu giảm. Cường cận giáp làm hủy hoại xương dẫn đến loãng xương nặng nề, sỏi thận tái phát nhiều lần."}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('4d375ab2-811a-4aae-9240-e14adfc4dfc1', 'default', 'e26ae74f-ff55-41e8-b3e5-5c63d87b9870', 'text', 'y_nghia', 2, true, '{"lines":["**Đau khớp gối: Khô dịch khớp và mòn sụn chêm**: Khớp gối gánh chịu tải trọng gấp 3-5 lần trọng lượng cơ thể khi đi lại và leo cầu thang. Đau khớp gối thường xuất phát từ sự sai lệch trục chân (chân chữ X, chân chữ O), gây mòn vẹt một bên sụn chêm và bao hoạt dịch giảm tiết dịch nhờn (hyaluronic acid). Cần phục hồi cơ tứ đầu đùi để ổn định bánh chè.","**Đau quanh khớp vai: Hội chứng chạm và viêm chóp xoay**: Khớp vai là khớp có biên độ vận động lớn nhất cơ thể nhưng độ vững cơ học phụ thuộc hoàn toàn vào 4 gân cơ chóp xoay (supraspinatus, infraspinatus, teres minor, subscapularis). Tư thế gù lưng rụt cổ khiến mỏm cùng vai đè bẹp gân cơ trên gai khi nhấc tay, gây viêm rách gân và kẹt khớp.","**Gai gót chân: Bản chất là viêm màng cân gan chân**: Gai xương gót chân trên phim X-quang thực chất không phải là thủ phạm đâm vào thịt gây đau, mà là phản ứng vôi hóa của cơ thể trước tình trạng màng cân gan chân (plantar fascia) bị kéo căng quá mức trong thời gian dài. Phục hồi cần tập dãn màng cân gan chân, chỉnh trục vòm bàn chân và dãn cơ bắp chân."],"title":"Tóm tắt cốt lõi & Nguyên lý sinh học","format":"bullet","content":"### 1. Đau khớp gối: Khô dịch khớp và mòn sụn chêm\n\nKhớp gối gánh chịu tải trọng gấp 3-5 lần trọng lượng cơ thể khi đi lại và leo cầu thang. Đau khớp gối thường xuất phát từ sự sai lệch trục chân (chân chữ X, chân chữ O), gây mòn vẹt một bên sụn chêm và bao hoạt dịch giảm tiết dịch nhờn (hyaluronic acid). Cần phục hồi cơ tứ đầu đùi để ổn định bánh chè.\n\n---\n\n### 2. Đau quanh khớp vai: Hội chứng chạm và viêm chóp xoay\n\nKhớp vai là khớp có biên độ vận động lớn nhất cơ thể nhưng độ vững cơ học phụ thuộc hoàn toàn vào 4 gân cơ chóp xoay (supraspinatus, infraspinatus, teres minor, subscapularis). Tư thế gù lưng rụt cổ khiến mỏm cùng vai đè bẹp gân cơ trên gai khi nhấc tay, gây viêm rách gân và kẹt khớp.\n\n---\n\n### 3. Gai gót chân: Bản chất là viêm màng cân gan chân\n\nGai xương gót chân trên phim X-quang thực chất không phải là thủ phạm đâm vào thịt gây đau, mà là phản ứng vôi hóa của cơ thể trước tình trạng màng cân gan chân (plantar fascia) bị kéo căng quá mức trong thời gian dài. Phục hồi cần tập dãn màng cân gan chân, chỉnh trục vòm bàn chân và dãn cơ bắp chân.","takeaways":[{"title":"Đau khớp gối: Khô dịch khớp và mòn sụn chêm","content":"Khớp gối gánh chịu tải trọng gấp 3-5 lần trọng lượng cơ thể khi đi lại và leo cầu thang. Đau khớp gối thường xuất phát từ sự sai lệch trục chân (chân chữ X, chân chữ O), gây mòn vẹt một bên sụn chêm và bao hoạt dịch giảm tiết dịch nhờn (hyaluronic acid). Cần phục hồi cơ tứ đầu đùi để ổn định bánh chè."},{"title":"Đau quanh khớp vai: Hội chứng chạm và viêm chóp xoay","content":"Khớp vai là khớp có biên độ vận động lớn nhất cơ thể nhưng độ vững cơ học phụ thuộc hoàn toàn vào 4 gân cơ chóp xoay (supraspinatus, infraspinatus, teres minor, subscapularis). Tư thế gù lưng rụt cổ khiến mỏm cùng vai đè bẹp gân cơ trên gai khi nhấc tay, gây viêm rách gân và kẹt khớp."},{"title":"Gai gót chân: Bản chất là viêm màng cân gan chân","content":"Gai xương gót chân trên phim X-quang thực chất không phải là thủ phạm đâm vào thịt gây đau, mà là phản ứng vôi hóa của cơ thể trước tình trạng màng cân gan chân (plantar fascia) bị kéo căng quá mức trong thời gian dài. Phục hồi cần tập dãn màng cân gan chân, chỉnh trục vòm bàn chân và dãn cơ bắp chân."}]}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('0ab615bc-6549-4de3-8514-c1dff636ce5b', 'default', 'b0000000-0000-0000-0000-000000000012', 'text', 'y_nghia', 2, true, '{"text":"### 🥩 Tóm tắt cốt lõi: Chất đạm (Protein) – Nền tảng xây dựng cơ bắp & Miễn dịch\n- **Vai trò sinh học của Protein:** Protein là vật liệu xây dựng mọi cấu trúc cơ thể: sợi cơ actin-myosin, kháng thể miễn dịch, enzyme xúc tác sinh hóa, hormone và collagen mô liên kết.\n- **Ngưỡng Leucine & Tổng hợp đạm cơ (MPS):** Axit amin thiết yếu Leucine đóng vai trò như chiếc chìa khóa kích hoạt công tắc mTORC1 tổng hợp cơ bắp. Mỗi bữa ăn cần đạt ngưỡng **2.5 – 3.0g Leucine** (tương đương 25–30g đạm nguyên chất) để tối ưu hóa sự phục hồi cơ.\n- **Nhu cầu đạm theo thể trạng:**\n  - Người ít vận động: 1.0 – 1.2 g/kg trọng lượng/ngày.\n  - Người cao tuổi (ngăn ngừa teo cơ Sarcopenia): 1.2 – 1.5 g/kg/ngày.\n  - Người tập kháng lực, giảm mỡ giữ cơ: 1.6 – 2.2 g/kg/ngày.\n- **Phối hợp đạm động vật vs thực vật:** Đạm động vật (trứng, cá, thịt gia cầm) có chỉ số giá trị sinh học DIAAS cao, đầy đủ 9 axit amin thiết yếu. Đạm thực vật (các loại đậu, hạt) giàu chất xơ, không chứa cholesterol xấu nhưng thường thiếu hụt methionine hoặc lysine; cần phối hợp đa dạng đậu và ngũ cốc để bổ khuyết axit amin.","lines":["**Vai trò sinh học của Protein:** Protein là vật liệu xây dựng mọi cấu trúc cơ thể: sợi cơ actin-myosin, kháng thể miễn dịch, enzyme xúc tác sinh hóa, hormone và collagen mô liên kết.","**Ngưỡng Leucine & Tổng hợp đạm cơ (MPS):** Axit amin thiết yếu Leucine đóng vai trò như chiếc chìa khóa kích hoạt công tắc mTORC1 tổng hợp cơ bắp. Mỗi bữa ăn cần đạt ngưỡng **2.5 – 3.0g Leucine** (tương đương 25–30g đạm nguyên chất) để tối ưu hóa sự phục hồi cơ.","**Nhu cầu đạm theo thể trạng:**","Người ít vận động: 1.0 – 1.2 g/kg trọng lượng/ngày.","Người cao tuổi (ngăn ngừa teo cơ Sarcopenia): 1.2 – 1.5 g/kg/ngày.","Người tập kháng lực, giảm mỡ giữ cơ: 1.6 – 2.2 g/kg/ngày.","**Phối hợp đạm động vật vs thực vật:** Đạm động vật (trứng, cá, thịt gia cầm) có chỉ số giá trị sinh học DIAAS cao, đầy đủ 9 axit amin thiết yếu. Đạm thực vật (các loại đậu, hạt) giàu chất xơ, không chứa cholesterol xấu nhưng thường thiếu hụt methionine hoặc lysine; cần phối hợp đa dạng đậu và ngũ cốc để bổ khuyết axit amin."],"title":"🥩 Tóm tắt cốt lõi: Chất đạm (Protein) – Nền tảng xây dựng cơ bắp & Miễn dịch","format":"bullet","content":"### 🥩 Tóm tắt cốt lõi: Chất đạm (Protein) – Nền tảng xây dựng cơ bắp & Miễn dịch\n- **Vai trò sinh học của Protein:** Protein là vật liệu xây dựng mọi cấu trúc cơ thể: sợi cơ actin-myosin, kháng thể miễn dịch, enzyme xúc tác sinh hóa, hormone và collagen mô liên kết.\n- **Ngưỡng Leucine & Tổng hợp đạm cơ (MPS):** Axit amin thiết yếu Leucine đóng vai trò như chiếc chìa khóa kích hoạt công tắc mTORC1 tổng hợp cơ bắp. Mỗi bữa ăn cần đạt ngưỡng **2.5 – 3.0g Leucine** (tương đương 25–30g đạm nguyên chất) để tối ưu hóa sự phục hồi cơ.\n- **Nhu cầu đạm theo thể trạng:**\n  - Người ít vận động: 1.0 – 1.2 g/kg trọng lượng/ngày.\n  - Người cao tuổi (ngăn ngừa teo cơ Sarcopenia): 1.2 – 1.5 g/kg/ngày.\n  - Người tập kháng lực, giảm mỡ giữ cơ: 1.6 – 2.2 g/kg/ngày.\n- **Phối hợp đạm động vật vs thực vật:** Đạm động vật (trứng, cá, thịt gia cầm) có chỉ số giá trị sinh học DIAAS cao, đầy đủ 9 axit amin thiết yếu. Đạm thực vật (các loại đậu, hạt) giàu chất xơ, không chứa cholesterol xấu nhưng thường thiếu hụt methionine hoặc lysine; cần phối hợp đa dạng đậu và ngũ cốc để bổ khuyết axit amin."}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('4204d74a-28ed-4232-9589-8e2d8b67923d', 'default', 'b0000000-0000-0000-0004-000000000006', 'text', 'y_nghia', 2, true, '{"text":"### 🛡️ Tóm tắt cốt lõi: Nhận diện & Kiểm soát các bệnh lý đường ruột thường gặp\n- **Vi khuẩn Helicobacter pylori (H.pylori):** Vi khuẩn xoắn khuẩn Gr(-) sống dưới lớp chất nhầy dạ dày nhờ tiết enzyme Urease trung hòa axit xung quanh. 80% người nhiễm không triệu chứng, nhưng là nguyên nhân hàng đầu gây viêm dạ dày mạn tính, loét dạ dày - tá tràng và ung thư biểu mô tuyến dạ dày.\n- **Hội chứng ruột kích thích (IBS - Irritable Bowel Syndrome):** Rối loạn tương tác não - ruột đặc trưng bởi đau bụng tái diễn liên quan đến đi ngoài (IBS-C thể táo, IBS-D thể lỏng hoặc hỗn hợp) mà không có tổn thương cấu trúc trên nội soi. Yếu tố khởi phát chính là căng thẳng thần kinh và nhạy cảm với thực phẩm FODMAPs.\n- **Viêm ruột từng vùng Crohn & Viêm loét đại tràng (IBD):** Bệnh lý tự miễn mạn tính gây loét sâu, chảy máu, tiêu chảy kéo dài và nguy cơ thủng ruột hoặc hẹp lòng ruột.\n- **Chiến lược phục hồi 4R chuẩn y khoa:**\n  1. *Remove (Loại bỏ):* Bỏ thực phẩm dị ứng, thức ăn rác, diệt khuẩn có hại.\n  2. *Replace (Thay thế):* Bổ sung enzyme tiêu hóa, axit dạ dày sinh học.\n  3. *Reinoculate (Cấy lại):* Bổ sung Probiotic và Prebiotic chất lượng cao.\n  4. *Repair (Làm lành):* Dùng L-Glutamine, Kẽm Carnosine, Curcumin để tái tạo niêm mạc.","lines":["**Vi khuẩn Helicobacter pylori (H.pylori):** Vi khuẩn xoắn khuẩn Gr(-) sống dưới lớp chất nhầy dạ dày nhờ tiết enzyme Urease trung hòa axit xung quanh. 80% người nhiễm không triệu chứng, nhưng là nguyên nhân hàng đầu gây viêm dạ dày mạn tính, loét dạ dày - tá tràng và ung thư biểu mô tuyến dạ dày.","**Hội chứng ruột kích thích (IBS - Irritable Bowel Syndrome):** Rối loạn tương tác não - ruột đặc trưng bởi đau bụng tái diễn liên quan đến đi ngoài (IBS-C thể táo, IBS-D thể lỏng hoặc hỗn hợp) mà không có tổn thương cấu trúc trên nội soi. Yếu tố khởi phát chính là căng thẳng thần kinh và nhạy cảm với thực phẩm FODMAPs.","**Viêm ruột từng vùng Crohn & Viêm loét đại tràng (IBD):** Bệnh lý tự miễn mạn tính gây loét sâu, chảy máu, tiêu chảy kéo dài và nguy cơ thủng ruột hoặc hẹp lòng ruột.","**Chiến lược phục hồi 4R chuẩn y khoa:**","*Remove (Loại bỏ):* Bỏ thực phẩm dị ứng, thức ăn rác, diệt khuẩn có hại.","*Replace (Thay thế):* Bổ sung enzyme tiêu hóa, axit dạ dày sinh học.","*Reinoculate (Cấy lại):* Bổ sung Probiotic và Prebiotic chất lượng cao.","*Repair (Làm lành):* Dùng L-Glutamine, Kẽm Carnosine, Curcumin để tái tạo niêm mạc."],"title":"🛡️ Tóm tắt cốt lõi: Nhận diện & Kiểm soát các bệnh lý đường ruột thường gặp","format":"bullet","content":"### 🛡️ Tóm tắt cốt lõi: Nhận diện & Kiểm soát các bệnh lý đường ruột thường gặp\n- **Vi khuẩn Helicobacter pylori (H.pylori):** Vi khuẩn xoắn khuẩn Gr(-) sống dưới lớp chất nhầy dạ dày nhờ tiết enzyme Urease trung hòa axit xung quanh. 80% người nhiễm không triệu chứng, nhưng là nguyên nhân hàng đầu gây viêm dạ dày mạn tính, loét dạ dày - tá tràng và ung thư biểu mô tuyến dạ dày.\n- **Hội chứng ruột kích thích (IBS - Irritable Bowel Syndrome):** Rối loạn tương tác não - ruột đặc trưng bởi đau bụng tái diễn liên quan đến đi ngoài (IBS-C thể táo, IBS-D thể lỏng hoặc hỗn hợp) mà không có tổn thương cấu trúc trên nội soi. Yếu tố khởi phát chính là căng thẳng thần kinh và nhạy cảm với thực phẩm FODMAPs.\n- **Viêm ruột từng vùng Crohn & Viêm loét đại tràng (IBD):** Bệnh lý tự miễn mạn tính gây loét sâu, chảy máu, tiêu chảy kéo dài và nguy cơ thủng ruột hoặc hẹp lòng ruột.\n- **Chiến lược phục hồi 4R chuẩn y khoa:**\n  1. *Remove (Loại bỏ):* Bỏ thực phẩm dị ứng, thức ăn rác, diệt khuẩn có hại.\n  2. *Replace (Thay thế):* Bổ sung enzyme tiêu hóa, axit dạ dày sinh học.\n  3. *Reinoculate (Cấy lại):* Bổ sung Probiotic và Prebiotic chất lượng cao.\n  4. *Repair (Làm lành):* Dùng L-Glutamine, Kẽm Carnosine, Curcumin để tái tạo niêm mạc."}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('5c836015-9e79-4f24-8ba4-088fa8181c7f', 'default', 'b0000000-0000-0000-0005-000000000004', 'text', 'y_nghia', 2, true, '{"text":"### 🥤 Tóm tắt cốt lõi: Nguyên tắc uống nước chuẩn sinh học & Công nghệ Hydro hoạt tính\n- **Thời điểm vàng uống nước sinh học:** 1 ly (250–300ml) nước ấm ngay sau khi thức dậy bù dịch sau 8 tiếng ngủ và kích thích nhu động đại tràng; 1 ly trước bữa ăn 30 phút hỗ trợ tiết dịch vị; 1 ly trước khi tắm và trước khi đi ngủ ngăn ngừa đông máu cục bộ.\n- **Quy tắc uống chậm từng ngụm:** Uống ừng ực lượng lớn làm căng dãn đột ngột dạ dày, ức chế ADH khiến thận thải nước tức thì ra bàng quang thay vì thẩm thấu vào tế bào; cần ngậm và nuốt chậm để kích hoạt thụ thể thần kinh tại khoang miệng.\n- **Chỉ số chống oxy hóa ORP (Oxidation Reduction Potential):** Nước tốt có ORP âm sâu (-300mV đến -600mV), mang điện thế khử mạnh giúp trung hòa các gốc tự do Hydroxyl (*OH) nguy hại bên trong ty thể tế bào.\n- **Phân tử Hydro (H2) sinh học:** Là chất chống oxy hóa nhỏ nhất trong vũ trụ, có khả năng xuyên qua màng sinh học kép, màng nhân và hàng rào máu não để bảo vệ DNA ty thể mà không can thiệp vào các gốc tự do có lợi cho miễn dịch.","lines":["**Thời điểm vàng uống nước sinh học:** 1 ly (250–300ml) nước ấm ngay sau khi thức dậy bù dịch sau 8 tiếng ngủ và kích thích nhu động đại tràng; 1 ly trước bữa ăn 30 phút hỗ trợ tiết dịch vị; 1 ly trước khi tắm và trước khi đi ngủ ngăn ngừa đông máu cục bộ.","**Quy tắc uống chậm từng ngụm:** Uống ừng ực lượng lớn làm căng dãn đột ngột dạ dày, ức chế ADH khiến thận thải nước tức thì ra bàng quang thay vì thẩm thấu vào tế bào; cần ngậm và nuốt chậm để kích hoạt thụ thể thần kinh tại khoang miệng.","**Chỉ số chống oxy hóa ORP (Oxidation Reduction Potential):** Nước tốt có ORP âm sâu (-300mV đến -600mV), mang điện thế khử mạnh giúp trung hòa các gốc tự do Hydroxyl (*OH) nguy hại bên trong ty thể tế bào.","**Phân tử Hydro (H2) sinh học:** Là chất chống oxy hóa nhỏ nhất trong vũ trụ, có khả năng xuyên qua màng sinh học kép, màng nhân và hàng rào máu não để bảo vệ DNA ty thể mà không can thiệp vào các gốc tự do có lợi cho miễn dịch."],"title":"🥤 Tóm tắt cốt lõi: Nguyên tắc uống nước chuẩn sinh học & Công nghệ Hydro hoạt tính","format":"bullet","content":"### 🥤 Tóm tắt cốt lõi: Nguyên tắc uống nước chuẩn sinh học & Công nghệ Hydro hoạt tính\n- **Thời điểm vàng uống nước sinh học:** 1 ly (250–300ml) nước ấm ngay sau khi thức dậy bù dịch sau 8 tiếng ngủ và kích thích nhu động đại tràng; 1 ly trước bữa ăn 30 phút hỗ trợ tiết dịch vị; 1 ly trước khi tắm và trước khi đi ngủ ngăn ngừa đông máu cục bộ.\n- **Quy tắc uống chậm từng ngụm:** Uống ừng ực lượng lớn làm căng dãn đột ngột dạ dày, ức chế ADH khiến thận thải nước tức thì ra bàng quang thay vì thẩm thấu vào tế bào; cần ngậm và nuốt chậm để kích hoạt thụ thể thần kinh tại khoang miệng.\n- **Chỉ số chống oxy hóa ORP (Oxidation Reduction Potential):** Nước tốt có ORP âm sâu (-300mV đến -600mV), mang điện thế khử mạnh giúp trung hòa các gốc tự do Hydroxyl (*OH) nguy hại bên trong ty thể tế bào.\n- **Phân tử Hydro (H2) sinh học:** Là chất chống oxy hóa nhỏ nhất trong vũ trụ, có khả năng xuyên qua màng sinh học kép, màng nhân và hàng rào máu não để bảo vệ DNA ty thể mà không can thiệp vào các gốc tự do có lợi cho miễn dịch."}'::jsonb)
on conflict (id) do update set
  type = excluded.type,
  display_style = excluded.display_style,
  data = excluded.data,
  sort_order = excluded.sort_order;
insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('bd9b4de0-8de0-4e55-977a-8fd048218747', 'default', 'b0000000-0000-0000-0006-000000000002', 'text', 'y_nghia', 2, true, '{"text":"### ⚡ Tóm tắt cốt lõi: Tuyến thượng thận, Cortisol & Phản ứng kiệt quệ Stress\n- **Cấu trúc 2 phần của tuyến thượng thận:**\n  - *Tủy thượng thận (Bên trong):* Tiết **Adrenaline** và **Noradrenaline** kích hoạt phản xạ \"Chiến hay Chạy\" tức thời (tăng nhịp tim, giãn phế quản, dồn máu tới cơ bắp).\n  - *Vỏ thượng thận (Bên ngoài):* Tiết Aldosterone (giữ muối nước), Androgen (hormone sinh dục) và đặc biệt là **Cortisol** (Glucocorticoid - hormone sinh tồn dài hạn).\n- **Nhịp sinh học tự nhiên của Cortisol:** Đỉnh cao nhất vào 6–8h sáng để đánh thức cơ thể và bơm năng lượng; giảm dần trong ngày và chạm đáy vào nửa đêm để nhường chỗ cho hormone giấc ngủ Melatonin.\n- **Cơ chế Stress mạn tính & Kháng Cortisol:** Căng thẳng kéo dài làm Cortisol tăng cao liên tục, gây tăng đường huyết, tích mỡ nội tạng quanh bụng, ức chế miễn dịch, teo hồi hải mã não bộ và phá hủy giấc ngủ sâu.\n- **Hội chứng kiệt quệ thượng thận (Adrenal Burnout):** Sau giai đoạn căng thẳng kéo dài quá mức, tuyến thượng thận rơi vào trạng thái suy kiệt không thể sản xuất đủ Cortisol, dẫn đến kiệt sức vào ban ngày nhưng thao thức ban đêm, tụt huyết áp tư thế và thèm đồ ngọt/muối dữ dội.","lines":["**Cấu trúc 2 phần của tuyến thượng thận:**","*Tủy thượng thận (Bên trong):* Tiết **Adrenaline** và **Noradrenaline** kích hoạt phản xạ \"Chiến hay Chạy\" tức thời (tăng nhịp tim, giãn phế quản, dồn máu tới cơ bắp).","*Vỏ thượng thận (Bên ngoài):* Tiết Aldosterone (giữ muối nước), Androgen (hormone sinh dục) và đặc biệt là **Cortisol** (Glucocorticoid - hormone sinh tồn dài hạn).","**Nhịp sinh học tự nhiên của Cortisol:** Đỉnh cao nhất vào 6–8h sáng để đánh thức cơ thể và bơm năng lượng; giảm dần trong ngày và chạm đáy vào nửa đêm để nhường chỗ cho hormone giấc ngủ Melatonin.","**Cơ chế Stress mạn tính & Kháng Cortisol:** Căng thẳng kéo dài làm Cortisol tăng cao liên tục, gây tăng đường huyết, tích mỡ nội tạng quanh bụng, ức chế miễn dịch, teo hồi hải mã não bộ và phá hủy giấc ngủ sâu.","**Hội chứng kiệt quệ thượng thận (Adrenal Burnout):** Sau giai đoạn căng thẳng kéo dài quá mức, tuyến thượng thận rơi vào trạng thái suy kiệt không thể sản xuất đủ Cortisol, dẫn đến kiệt sức vào ban ngày nhưng thao thức ban đêm, tụt huyết áp tư thế và thèm đồ ngọt/muối dữ dội."],"title":"⚡ Tóm tắt cốt lõi: Tuyến thượng thận, Cortisol & Phản ứng kiệt quệ Stress","format":"bullet","content":"### ⚡ Tóm tắt cốt lõi: Tuyến thượng thận, Cortisol & Phản ứng kiệt quệ Stress\n- **Cấu trúc 2 phần của tuyến thượng thận:**\n  - *Tủy thượng thận (Bên trong):* Tiết **Adrenaline** và **Noradrenaline** kích hoạt phản xạ \"Chiến hay Chạy\" tức thời (tăng nhịp tim, giãn phế quản, dồn máu tới cơ bắp).\n  - *Vỏ thượng thận (Bên ngoài):* Tiết Aldosterone (giữ muối nước), Androgen (hormone sinh dục) và đặc biệt là **Cortisol** (Glucocorticoid - hormone sinh tồn dài hạn).\n- **Nhịp sinh học tự nhiên của Cortisol:** Đỉnh cao nhất vào 6–8h sáng để đánh thức cơ thể và bơm năng lượng; giảm dần trong ngày và chạm đáy vào nửa đêm để nhường chỗ cho hormone giấc ngủ Melatonin.\n- **Cơ chế Stress mạn tính & Kháng Cortisol:** Căng thẳng kéo dài làm Cortisol tăng cao liên tục, gây tăng đường huyết, tích mỡ nội tạng quanh bụng, ức chế miễn dịch, teo hồi hải mã não bộ và phá hủy giấc ngủ sâu.\n- **Hội chứng kiệt quệ thượng thận (Adrenal Burnout):** Sau giai đoạn căng thẳng kéo dài quá mức, tuyến thượng thận rơi vào trạng thái suy kiệt không thể sản xuất đủ Cortisol, dẫn đến kiệt sức vào ban ngày nhưng thao thức ban đêm, tụt huyết áp tư thế và thèm đồ ngọt/muối dữ dội."}'::jsonb)
on conflict (id) do update set
