insert into public.blocks (id, workspace_id, page_id, type, display_style, sort_order, is_visible, data)
values ('5a0cccfe-fa40-44dc-954d-9a04de5ec27f', 'default', 'b0000000-0000-0000-0005-000000000001', 'text', 'y_nghia', 2, true, '{"text":"### 💧 Tóm tắt cốt lõi: Nước – Dung môi của sự sống & Cân bằng dịch nội bào\n- **Tỷ trọng sinh học:** Nước chiếm 60–70% trọng lượng cơ thể người trưởng thành, phân bổ thành 2 khoang chính: Dịch nội bào (ICF - 67%) và Dịch ngoại bào (ECF - 33%, bao gồm huyết tương và dịch gian bào).\n- **Cơ chế trao đổi dịch Starling:** Sự dịch chuyển nước qua thành mao mạch phụ thuộc vào cân bằng giữa Áp lực thủy tĩnh (đẩy dịch ra) và Áp lực keo của Albumin (kéo dịch vào lòng mạch). Giảm Albumin hoặc ứ trệ tuần hoàn gây thoát dịch vào mô kẽ tạo phù nề.\n- **Dung môi đệm thần kinh & Hàng rào máu não:** Dịch não tủy (CSF) chứa 99% nước, lưu thông liên tục 150ml để nâng đỡ, hấp thu xung chấn cơ học cho não bộ và tủy sống, đồng thời dẫn lưu các sản phẩm chuyển hóa độc hại ra khỏi tế bào thần kinh.\n- **Tiêu chuẩn nước uống sạch:** Nước tinh khiết đạt chuẩn phải loại bỏ triệt để tạp chất rắn lơ lửng, kim loại nặng độc hại (Asen, Chì, Thủy ngân), hợp chất hữu cơ dễ bay hơi (VOCs, Clo dư) và vi sinh vật gây bệnh, đảm bảo an toàn tuyệt đối trước khi bổ sung khoáng chất sinh học.","lines":["**Tỷ trọng sinh học:** Nước chiếm 60–70% trọng lượng cơ thể người trưởng thành, phân bổ thành 2 khoang chính: Dịch nội bào (ICF - 67%) và Dịch ngoại bào (ECF - 33%, bao gồm huyết tương và dịch gian bào).","**Cơ chế trao đổi dịch Starling:** Sự dịch chuyển nước qua thành mao mạch phụ thuộc vào cân bằng giữa Áp lực thủy tĩnh (đẩy dịch ra) và Áp lực keo của Albumin (kéo dịch vào lòng mạch). Giảm Albumin hoặc ứ trệ tuần hoàn gây thoát dịch vào mô kẽ tạo phù nề.","**Dung môi đệm thần kinh & Hàng rào máu não:** Dịch não tủy (CSF) chứa 99% nước, lưu thông liên tục 150ml để nâng đỡ, hấp thu xung chấn cơ học cho não bộ và tủy sống, đồng thời dẫn lưu các sản phẩm chuyển hóa độc hại ra khỏi tế bào thần kinh.","**Tiêu chuẩn nước uống sạch:** Nước tinh khiết đạt chuẩn phải loại bỏ triệt để tạp chất rắn lơ lửng, kim loại nặng độc hại (Asen, Chì, Thủy ngân), hợp chất hữu cơ dễ bay hơi (VOCs, Clo dư) và vi sinh vật gây bệnh, đảm bảo an toàn tuyệt đối trước khi bổ sung khoáng chất sinh học."],"title":"💧 Tóm tắt cốt lõi: Nước – Dung môi của sự sống & Cân bằng dịch nội bào","format":"bullet","content":"### 💧 Tóm tắt cốt lõi: Nước – Dung môi của sự sống & Cân bằng dịch nội bào\n- **Tỷ trọng sinh học:** Nước chiếm 60–70% trọng lượng cơ thể người trưởng thành, phân bổ thành 2 khoang chính: Dịch nội bào (ICF - 67%) và Dịch ngoại bào (ECF - 33%, bao gồm huyết tương và dịch gian bào).\n- **Cơ chế trao đổi dịch Starling:** Sự dịch chuyển nước qua thành mao mạch phụ thuộc vào cân bằng giữa Áp lực thủy tĩnh (đẩy dịch ra) và Áp lực keo của Albumin (kéo dịch vào lòng mạch). Giảm Albumin hoặc ứ trệ tuần hoàn gây thoát dịch vào mô kẽ tạo phù nề.\n- **Dung môi đệm thần kinh & Hàng rào máu não:** Dịch não tủy (CSF) chứa 99% nước, lưu thông liên tục 150ml để nâng đỡ, hấp thu xung chấn cơ học cho não bộ và tủy sống, đồng thời dẫn lưu các sản phẩm chuyển hóa độc hại ra khỏi tế bào thần kinh.\n- **Tiêu chuẩn nước uống sạch:** Nước tinh khiết đạt chuẩn phải loại bỏ triệt để tạp chất rắn lơ lửng, kim loại nặng độc hại (Asen, Chì, Thủy ngân), hợp chất hữu cơ dễ bay hơi (VOCs, Clo dư) và vi sinh vật gây bệnh, đảm bảo an toàn tuyệt đối trước khi bổ sung khoáng chất sinh học."}'::jsonb)
